/** Keys in the STATS dataset that represent envelope-relative usage percentages */
const ENVELOPE_METRIC_KEYS = ['percentAllottedGPU', 'percentAllottedCPU', 'percentAllottedRAM', 'percentAllottedVRAM'] as const;
type EnvelopeMetricKey = (typeof ENVELOPE_METRIC_KEYS)[number];

const METRIC_LABEL: Record<EnvelopeMetricKey, string> = {
    percentAllottedGPU: 'GPU',
    percentAllottedCPU: 'CPU',
    percentAllottedRAM: 'RAM',
    percentAllottedVRAM: 'VRAM',
};

const BREACH_THRESHOLD = 100; // % — above this is "over allocation"

export type PerformanceSeverity = 'pass' | 'warn' | 'fail';

export interface PerformanceSummary {
    text: string;
    severity: PerformanceSeverity;
    metrics: {
        key: EnvelopeMetricKey;
        label: string;
        avg: number;
        peak: number;
        breachDurationMs: number;
    }[];
}

interface DataPoint {
    lineKey: string;
    value: number;
    date: Date;
    relativeMs?: number;
}

function round(n: number, decimals = 0): number {
    const factor = 10 ** decimals;
    return Math.round(n * factor) / factor;
}

function formatDuration(ms: number): string {
    if (ms < 1000) return `${round(ms)}ms`;
    const s = ms / 1000;
    if (s < 60) return `${round(s)}s`;
    return `${round(s / 60, 1)}m`;
}

interface MetricStats {
    key: EnvelopeMetricKey;
    label: string;
    avg: number;
    peak: number;
    breachDurationMs: number;
}

function computeMetricStats(points: DataPoint[]): MetricStats[] {
    const byKey: Map<EnvelopeMetricKey, DataPoint[]> = new Map();

    for (const key of ENVELOPE_METRIC_KEYS) {
        byKey.set(key, []);
    }

    for (const pt of points) {
        if (ENVELOPE_METRIC_KEYS.includes(pt.lineKey as EnvelopeMetricKey)) {
            byKey.get(pt.lineKey as EnvelopeMetricKey)!.push(pt);
        }
    }

    return ENVELOPE_METRIC_KEYS.map((key) => {
        const pts = byKey.get(key) ?? [];
        if (pts.length === 0) {
            return { key, label: METRIC_LABEL[key], avg: 0, peak: 0, breachDurationMs: 0 };
        }

        const values = pts.map((p) => p.value);
        const avg = values.reduce((s, v) => s + v, 0) / values.length;
        const peak = Math.max(...values);

        // Estimate breach duration: count consecutive pairs of breach points
        const sorted = [...pts].sort((a, b) => a.date.getTime() - b.date.getTime());
        let breachMs = 0;
        for (let i = 1; i < sorted.length; i++) {
            if (sorted[i - 1].value > BREACH_THRESHOLD && sorted[i].value > BREACH_THRESHOLD) {
                breachMs += sorted[i].date.getTime() - sorted[i - 1].date.getTime();
            }
        }

        return { key, label: METRIC_LABEL[key], avg: round(avg, 1), peak: round(peak, 1), breachDurationMs: breachMs };
    });
}

function buildSummaryText(metrics: MetricStats[], sessionDurationMs: number): { text: string; severity: PerformanceSeverity } {
    const breaching = metrics.filter((m) => m.peak > BREACH_THRESHOLD);
    const sustained = breaching.filter((m) => m.breachDurationMs > 5_000);

    if (breaching.length === 0) {
        const sorted = [...metrics].sort((a, b) => b.avg - a.avg);
        const topTwo = sorted.slice(0, 2).map((m) => `${m.label} at ${m.avg}%`).join(', ');
        return {
            severity: 'pass',
            text: `All resources stayed within allocation limits throughout the session. Averages: ${topTwo}. No performance issues detected.`,
        };
    }

    if (sustained.length === 0) {
        // Brief spikes only
        const labels = breaching.map((m) => `${m.label} (peak ${m.peak}%)`).join(', ');
        return {
            severity: 'warn',
            text: `Brief allocation spikes detected on ${labels}. Spikes were short-lived and unlikely to impact session quality. Consider monitoring these metrics over multiple sessions.`,
        };
    }

    // Sustained breaches
    const parts = sustained.map((m) => {
        const pct = sessionDurationMs > 0 ? round((m.breachDurationMs / sessionDurationMs) * 100) : 0;
        return `${m.label} exceeded allocation for ~${formatDuration(m.breachDurationMs)} (${pct}% of session, peak ${m.peak}%)`;
    });

    const withinBounds = metrics.filter((m) => m.peak <= BREACH_THRESHOLD).map((m) => m.label);

    let text = parts.join('. ') + '.';
    if (withinBounds.length > 0) {
        text += ` ${withinBounds.join(' and ')} remained within bounds.`;
    }

    const worstMetric = sustained.reduce((a, b) => (a.peak > b.peak ? a : b));
    text += ` Recommendation: increase the ${worstMetric.label} envelope limit or reduce ${worstMetric.label.toLowerCase()} workload for this game.`;

    return { severity: 'fail', text };
}

/**
 * Generates a concise natural-language summary of session performance
 * against resource allocation limits from the raw stats dataset.
 */
export function generatePerformanceSummary(
    statsPoints: DataPoint[],
    sessionDurationMs?: number,
): PerformanceSummary {
    if (!statsPoints || statsPoints.length === 0) {
        return {
            severity: 'pass',
            text: 'No performance data was recorded for this session.',
            metrics: [],
        };
    }

    const metrics = computeMetricStats(statsPoints);
    const duration = sessionDurationMs ?? (() => {
        const dates = statsPoints.map((p) => p.date.getTime()).filter(Boolean);
        return dates.length >= 2 ? Math.max(...dates) - Math.min(...dates) : 0;
    })();

    const { text, severity } = buildSummaryText(metrics, duration);
    return { text, severity, metrics };
}
