import type * as OcgaProto from '@ocga/proto';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo, useRef } from 'react';

export const SESSION_NETWORK_LOGS = 'sessionGameLogsErrors';

export const useTelemetryMessageTypesEvents = (
    gsId: string | undefined,
    messageTypes: OcgaProto.MessageType.MessageType[] = [],
) => {
    const lastFetch = useRef(0);
    const queryClient = useQueryClient();
    const query = useQuery<any>({
        queryKey: [SESSION_NETWORK_LOGS, gsId],
        enabled: !!gsId,
        gcTime: 0, // These sessions are all historical
        queryFn: async () => {
            const result = await fetch(
                `/api/t2/${gsId}?${new URLSearchParams({
                    messageTypes: messageTypes.join(','),
                    method: 'rest',
                })}`,
            );
            const jsonResult = await result.text();
            lastFetch.current = Date.now();
            return jsonResult;
        },
    });

    const logs = useMemo(() => {
        let logsArray = null;
        try {
            logsArray = JSON.parse(query.data)?.data;
        } catch (error) {
            return [];
        }
        if (!query.data || !Array.isArray(logsArray)) {
            return [];
        }
        return logsArray
            .map((logJson: string) => {
                return JSON.parse(logJson);
            })
            .sort((a: any, b: any) => -a.Timestamp.localeCompare(b.Timestamp))
            .map((log: any, index: number) => {
                const hostConnection = log.Message?.HostConnectionEvent;
                // Add a unique ID for the table
                if (hostConnection) {
                    return {
                        ...hostConnection,
                        id: `${hostConnection?.Hostname}-${hostConnection?.IPAddr}-${hostConnection?.Port}-${index}`,
                    };
                }
                return null;
            })
            .filter((log: any) => log !== null);
    }, [query.data]);

    const refetch = useCallback(() => {
        queryClient.invalidateQueries({ queryKey: [SESSION_NETWORK_LOGS, gsId] });
    }, [queryClient, gsId]);

    return {
        ...query,
        refetch,
        lastFetch: lastFetch.current,
        logs,
    };
};
