import {
    IconArrowLeft,
    IconArrowRight,
    IconBroom,
    IconDownload,
    IconFilter,
    IconMagnifyingGlass,
    IconSettings,
    IconX,
} from '@hawkins/assets';
import { Button, ButtonGroup, Checkbox, Menu, MenuGroup, MenuItem, Stack, Text } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useCallback } from 'react';
import { SearchInput } from '../SearchInput';
import styles from './SearchToolbar.module.css';

const EXPAND_FILTER_SEARCH = 3;
interface SearchToolbarProps {
    autoscroll: boolean;
    relativeTimestamps: boolean;
    filter: string;
    firstOnly: boolean;
    loading?: boolean;
    streamingComplete?: boolean;
    searchMatchesCount: number;
    hiddenLogsCount: number;
    searchIndex: number;
    onClear?: () => void;
    onSubmit: () => void;
    onSearchPrevious: () => void;
    onSearchNext: () => void;
    onClearLogs?: () => void;
    onDownloadCSV: () => void;
    onDownloadLog: () => void;
    setAutoscroll: (value: boolean) => void;
    setRelativeTimestamps: (value: boolean) => void;
    setFilter: (value: string) => void;
    setFirstOnly: (value: boolean) => void;
    showCollapsedCount: boolean;
    setShowCollapsedCount: (value: boolean) => void;
    filterMatchesOnly: boolean;
    setFilterMatchesOnly: (value: boolean) => void;
}

export const SearchToolbar = (props: SearchToolbarProps) => {
    const {
        autoscroll,
        relativeTimestamps,
        filter,
        firstOnly,
        loading,
        streamingComplete = true,
        searchMatchesCount,
        hiddenLogsCount,
        searchIndex,
        onSubmit,
        onClear,
        onSearchPrevious,
        onSearchNext,
        onClearLogs,
        onDownloadCSV,
        onDownloadLog,
        setAutoscroll,
        setRelativeTimestamps,
        setFilter,
        setFirstOnly,
        showCollapsedCount,
        setShowCollapsedCount,
        filterMatchesOnly,
        setFilterMatchesOnly,
    } = props;

    const onSearchFilterChange = useCallback(
        (text: string) => {
            setFilter(text);
        },
        [setFilter],
    );

    const endAdornment = filter.trim() ? (
        <Button
            variant='icon'
            onClick={() => {
                onClear?.();
                setFilter('');
            }}
            compact
            icon={IconX}
        />
    ) : (
        <IconMagnifyingGlass size='small' />
    );

    return (
        <div className={styles.toolBar}>
            <Menu showCaret trigger={<Button aria-label='Log Settings' icon={IconSettings} variant='tertiary' />}>
                <MenuItem disabled={loading} onChange={() => setAutoscroll(!autoscroll)}>
                    <Checkbox
                        disabled={loading}
                        // onChange={() => setAutoscroll(!autoscroll)}
                        label={
                            <Text level={2} variant='label' className={styles.label}>
                                Autoscroll to the bottom
                            </Text>
                        }
                        checked={autoscroll}
                    />
                </MenuItem>

                <MenuItem disabled={loading} onChange={() => setRelativeTimestamps(!relativeTimestamps)}>
                    <Checkbox
                        disabled={loading}
                        label={
                            <Text level={2} variant='label' className={styles.label}>
                                Relative time
                            </Text>
                        }
                        checked={relativeTimestamps}
                    />
                </MenuItem>

                <MenuItem disabled={loading} onChange={() => setFirstOnly(!firstOnly)}>
                    <Checkbox
                        disabled={loading}
                        label={
                            <Text level={2} variant='label' className={styles.label}>
                                First line only
                            </Text>
                        }
                        checked={firstOnly}
                    />
                </MenuItem>

                <MenuItem disabled={loading} onChange={() => setShowCollapsedCount(!showCollapsedCount)}>
                    <Checkbox
                        disabled={loading}
                        label={
                            <Text level={2} variant='label' className={styles.label}>
                                Show collapsed count
                            </Text>
                        }
                        checked={showCollapsedCount}
                    />
                </MenuItem>
            </Menu>
            <div className={styles.actions}>
                {filter && (
                    <Stack gap={Dimensions.Space4} orientation='horizontal' layout={{ alignItems: 'center' }}>
                        {(searchMatchesCount > 1 || hiddenLogsCount > 0) && (
                            <>
                                <Stack orientation='horizontal' gap={Dimensions.Space2}>
                                    {searchMatchesCount > 1 && (
                                        <>
                                            <Text
                                                component='span'
                                                variant='label'
                                            >{`${searchIndex !== -1 ? `${searchIndex} of` : ''}`}</Text>
                                            <Text component='span' variant='label'>{`${searchMatchesCount}`}</Text>
                                        </>
                                    )}
                                    {hiddenLogsCount > 0 && (
                                        <Text
                                            component='span'
                                            variant='label'
                                            style={{ opacity: 0.5 }}
                                        >{`(${hiddenLogsCount} hidden)`}</Text>
                                    )}
                                </Stack>

                                {searchMatchesCount > 1 && (
                                    <ButtonGroup gap={Dimensions.Space4}>
                                        <Button
                                            variant='icon'
                                            tooltipLabel='Previous'
                                            compact
                                            icon={IconArrowLeft}
                                            aria-label='previous'
                                            onClick={onSearchPrevious}
                                        />
                                        <Button
                                            variant='icon'
                                            tooltipLabel='Next'
                                            compact
                                            icon={IconArrowRight}
                                            aria-label='next'
                                            onClick={onSearchNext}
                                        />
                                    </ButtonGroup>
                                )}
                            </>
                        )}
                    </Stack>
                )}

                <Button
                    variant={filterMatchesOnly ? 'secondary' : 'tertiary'}
                    aria-label='Toggle matches only filter'
                    tooltipLabel='Show matches only'
                    icon={IconFilter}
                    disabled={loading || !filter.trim() || searchMatchesCount === 0}
                    onClick={() => setFilterMatchesOnly(!filterMatchesOnly)}
                />

                <SearchInput
                    value={filter}
                    onChange={onSearchFilterChange}
                    onSubmit={onSubmit}
                    loading={loading}
                    endAdornment={endAdornment}
                />

                <ButtonGroup gap={Dimensions.Space8}>
                    <Button
                        variant='tertiary'
                        aria-label='Clear logs'
                        tooltipLabel='Clear logs'
                        tooltipDescription={!streamingComplete ? 'Logs are still loading.' : undefined}
                        icon={IconBroom}
                        disabled={loading || !streamingComplete}
                        onClick={onClearLogs}
                    />
                    <Menu
                        disableAutoFocusOnOpen={true}
                        disableAutoFocusOnClose={true}
                        disabled={loading || !streamingComplete}
                        trigger={
                            <Button
                                variant='tertiary'
                                aria-label='Download'
                                tooltipLabel='Download'
                                tooltipDescription={
                                    !streamingComplete
                                        ? 'Logs are still loading.'
                                        : 'Option to download via LOG or CSV format.'
                                }
                                icon={IconDownload}
                                disabled={loading || !streamingComplete}
                            />
                        }
                    >
                        <MenuGroup label='FORMATS'>
                            <MenuItem onClick={onDownloadLog}>LOG</MenuItem>
                            <MenuItem onClick={onDownloadCSV}>CSV</MenuItem>
                        </MenuGroup>
                    </Menu>
                </ButtonGroup>
            </div>
        </div>
    );
};
