import { HoverCard, type HoverCardProps, MenuItem, Paper } from '@hawkins/components';
import type { ReactNode } from 'react';
import styles from './HoverCardTooltip.module.css';

type HoverCardTooltipProps = {
    label: (string | ReactNode)[];
    description?: (string | ReactNode)[];
} & HoverCardProps;

export const HoverCardTooltip = ({ label, description, children, ...rest }: HoverCardTooltipProps) => {
    return (
        <HoverCard {...rest}>
            <HoverCard.Trigger>{children}</HoverCard.Trigger>
            <HoverCard.Content>
                <Paper elevation={2} className={styles.paper}>
                    {label.map((lab, i) => {
                        return (
                            <MenuItem
                                key={`${label}-${i}`}
                                label={lab}
                                subtitle={description?.[i]}
                                className={styles.item}
                            />
                        );
                    })}
                </Paper>
            </HoverCard.Content>
        </HoverCard>
    );
};
