import { type DebounceSettings, debounce } from 'lodash-es';
import { type SetStateAction, useCallback, useRef, useState } from 'react';

export const useStateDebounced = <T>(
    defaultValue: T,
    wait?: number,
    settings?: DebounceSettings,
): [T, (value: SetStateAction<T>) => void] => {
    const [, setId] = useState(0);
    const refState = useRef<T>(defaultValue);
    const debounceRender = useRef(debounce(() => setId(new Date().getTime()), wait, settings));

    const setState = useCallback(
        (value: SetStateAction<T>) => {
            // always update ref
            refState.current = value instanceof Function ? value(refState.current) : value;
            // debounce render
            debounceRender.current();
        },
        [debounceRender],
    );

    return [refState.current, setState];
};
