import { type Item, useLocalStorage } from '@gsm-common/hooks/useLocalStorage';
import { IconTrashCan } from '@hawkins/assets';
import { Button, ClampedText, Input, Menu, MenuItem } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { type KeyboardEvent, type ReactNode, useCallback, useEffect, useRef, useState } from 'react';

interface SearchInputProps {
    loading?: boolean;
    onSubmit: () => void;
    onChange: (value: string) => void;
    value: string;
    endAdornment?: ReactNode;
}

export const SearchInput = (props: SearchInputProps) => {
    const { loading, onSubmit, onChange, value, endAdornment } = props;
    const inputRef = useRef<HTMLElement>(null);
    const innerRef = useRef<HTMLInputElement>(null);
    const [syncedStore, setSyncedStore] = useLocalStorage<Item[]>('LOG_SEARCH_ITEMS', []);
    const [focused, setFocused] = useState(false);

    useEffect(() => {
        const handleClick = (e: MouseEvent) => {
            // clicks are lost on the player so make sure the input looses focus
            if (focused && !innerRef.current?.contains(e.target as Element)) {
                innerRef.current?.blur();
            }
        };
        document.addEventListener('click', handleClick);
        return () => {
            document.removeEventListener('click', handleClick);
        };
    }, [innerRef, focused]);

    const handleSearchFocus = useCallback(() => setFocused(true), []);
    const handleSearchBlur = useCallback(() => setFocused(false), []);

    const handleSearchKeyUp = useCallback(
        (e: KeyboardEvent<HTMLInputElement>) => {
            if (e.key === 'Enter') {
                onSubmit?.();
                handleAddItem(value);
            }
            // prevent input events being sent to game
            e.stopPropagation();
        },
        [value, onSubmit],
    );

    const handleSearchKeyDown = useCallback((e: KeyboardEvent<HTMLInputElement>) => {
        // prevent input events being sent to game
        e.stopPropagation();
    }, []);

    const handleRemoveItem = useCallback(
        (item: Item) => {
            setSyncedStore((store) => store.filter((sItem) => sItem.id !== item.id));
        },
        [setSyncedStore],
    );

    const handleAddItem = useCallback(
        (item: Item | string) => {
            let newItem: Item;
            if (typeof item === 'string') {
                newItem = {
                    id: new Date().getTime().toString(),
                    text: item,
                };
            } else {
                newItem = item;
            }

            // only sync items that are missing
            setSyncedStore((store) => {
                if (!store.find((sItem) => sItem.text === newItem.text)) {
                    return [...store, newItem];
                }
                return store;
            });
            onChange(newItem.text);
        },
        [onChange, setSyncedStore],
    );

    return (
        <Menu
            disableAutoFocusOnOpen={true}
            disableAutoFocusOnClose={true}
            trigger={
                <Input
                    ref={inputRef}
                    inputRef={innerRef}
                    disabled={loading}
                    value={value}
                    onChange={(e) => onChange(e.target.value)}
                    placeholder='Filter (e.g. match, -exclude)'
                    endAdornment={endAdornment}
                    autoComplete='off'
                    autoCorrect='off'
                    fullWidth
                    containerProps={{ style: { width: Dimensions.Size448 } }}
                    onKeyUp={handleSearchKeyUp}
                    onKeyDown={handleSearchKeyDown}
                    onFocus={handleSearchFocus}
                    onBlur={handleSearchBlur}
                />
            }
            fullWidth
            open={syncedStore.length === 0 ? false : undefined}
        >
            {syncedStore.map((item) => (
                <MenuItem key={item.id} compact onClick={() => handleAddItem(item)}>
                    <div style={{ display: 'flex' }}>
                        <ClampedText numLines={2}>{item.text}</ClampedText>
                        <div style={{ flex: 1 }} />
                        <Button
                            compact
                            icon={IconTrashCan}
                            onClick={(e) => {
                                handleRemoveItem(item);
                                e.stopPropagation();
                            }}
                            variant='icon'
                        >
                            Remove
                        </Button>
                    </div>
                </MenuItem>
            ))}
        </Menu>
    );
};
