export type LogTypeKey = 'error' | 'warn' | 'info' | 'network';

export const ALL_LOG_TYPES = new Set<LogTypeKey>(['error', 'warn', 'info', 'network']);

export const LOG_TYPE_LABELS: Record<LogTypeKey, string> = {
    error: 'Error',
    warn: 'Warning',
    info: 'Info',
    network: 'Network',
};

export const LOG_TYPE_ICON_COLOR: Record<LogTypeKey, string | undefined> = {
    error: 'var(--hawkins-theme-foreground-system-error)',
    warn: 'var(--hawkins-theme-foreground-system-warning)',
    info: undefined,
    network: 'var(--hawkins-theme-foreground-system-link)',
};

const ERROR_REGEX = /\b(error|exception)\b/i;
const WARN_REGEX = /\bwarn(ing)?\b/i;

/** Classifies a [timestamp, message, ...] log tuple into a LogTypeKey based on its message content. */
export function classifyLog(log: string[]): LogTypeKey {
    if (log[2]) return 'network';
    if (ERROR_REGEX.test(log[1])) return 'error';
    if (WARN_REGEX.test(log[1])) return 'warn';
    return 'info';
}
