import type { Build } from './Build';

export interface Channel {
    id: string;
    name: string;
    activeBuild: Build;
    assignedTarget: {
        targetSelectorRule: {
            name: string;
        };
    };
}

export interface DeploymentTarget {
    name: string;
}

const OCGA_2026_HARDWARE_REVISION = 'FRANMFCP0A';
const VIRTUAL_OCGA_HOSTNAME_PREFIX = 'i-';

export function isOcga2026Session(ocgaHardwareRevision: string | undefined): boolean {
    return ocgaHardwareRevision === OCGA_2026_HARDWARE_REVISION;
}

export function isVirtualOcgaSession(machineHostname: string | undefined): boolean {
    return machineHostname?.startsWith(VIRTUAL_OCGA_HOSTNAME_PREFIX) ?? false;
}
