import { useSessionTimelineData } from '@ncgt/session-timeline';
import { ChartType } from '@ncgt/session-timeline/src/types';
import styles from './SessionTimelineChart.module.css';
import { format } from './utils';

export const ScrubberSideCard = () => {
    const { datasets } = useSessionTimelineData();
    const chartDataset: any[] | undefined = datasets?.[ChartType.STATS];

    if (!chartDataset?.length) return <div className={styles.scrubberCard} />;

    const firstMs = chartDataset[0].relativeMs ?? 0;
    const lastMs = chartDataset[chartDataset.length - 1].relativeMs ?? 0;
    const durationFormatted = format(lastMs - firstMs);

    return (
        <div className={styles.scrubberCard}>
            <span className={styles.scrubberLabel}>Session Duration</span>
            <span className={styles.scrubberValue}>{durationFormatted}</span>
        </div>
    );
};
