import { CLIENT_NAME } from '@gsm-app/constants';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import { startMockTelemetry } from '@gsm-app/mocks/mockTelemetry';
import type { ErrorMessage } from '@gsm-app/models/ErrorMessage';
import type { Message } from '@gsm-app/models/Message';
import type { Messages } from '@gsm-app/models/Messages';
import { useCallback, useEffect, useRef } from 'react';
import useWebSocket, { ReadyState } from 'react-use-websocket';

type TelemetryContext = 'game' | 'session' | 'ncgtmetrics' | 'controller';
type UseTelemetryProps<S> = {
    sessionId?: string;
    disabled?: boolean;
    live?: boolean;
    context: TelemetryContext;
    targetInstanceCount?: number;
    is1080p?: boolean;
    onMessage?: (message: Message<S>) => void;
    onError?: (error: ErrorMessage) => void;
    onOpen?: (event: Event) => void;
    onComplete?: (context: string) => void;
};

type TelemetryData = {
    sessionId: string;
    context: TelemetryContext;
};

type TelemetryMessage = Message<TelemetryData, 'telemetry'>;

const MAX_RECONNECT_ATTEMPTS = 5;

const parseMessage = <T>(data: string) => {
    let parsed: undefined | Messages<T> = undefined;
    // handle healthcheck
    if (data === 'pong') {
        return undefined;
    }
    try {
        parsed = JSON.parse(data);
    } catch (error) {
        console.log({ data, error });
    }
    return parsed;
};

/**
 * Local-only UI dev mode — stands in for the real `/wss` telemetry socket with an interval-based
 * fixture generator (see `mocks/mockTelemetry.ts`). Backs game logs, controller logs, and the perf
 * graph's fps/stats/instanceCount datasets, since all three share this one hook by `context`.
 */
const useMockTelemetry = <R extends { Timestamp?: string }>({
    sessionId,
    disabled,
    context,
    onMessage,
    onOpen,
}: UseTelemetryProps<R>) => {
    useEffect(() => {
        if (disabled || !sessionId) return;
        return startMockTelemetry(context, {
            onOpen,
            onMessage: (message) => onMessage?.(message as Message<R>),
        });
    }, [context, disabled, sessionId, onMessage, onOpen]);

    return { readyState: disabled || !sessionId ? ReadyState.CLOSED : ReadyState.OPEN };
};

const useRealTelemetry = <R extends { Timestamp?: string }>({
    sessionId,
    disabled,
    live,
    context,
    targetInstanceCount,
    is1080p,
    onMessage,
    onError,
    onOpen,
    onComplete,
}: UseTelemetryProps<R>) => {
    const startTimeRef = useRef<string>();
    const reconnectAttempts = useRef(0);
    // Track if initial request was sent to prevent duplicate requests
    const initialRequestSentRef = useRef(false);

    const handleMessage = useCallback(
        (event: MessageEvent<string>) => {
            const message = parseMessage<R>(event.data);
            if (!message) {
                return;
            }
            if (message.type === 'Error') {
                onError?.(message);
            } else if (message.type === 'Complete') {
                onComplete?.(message.context);
            } else if (message.type === 'Batch') {
                for (const item of message.data) {
                    if (item.Timestamp) {
                        startTimeRef.current = String((BigInt(item.Timestamp) + BigInt(1000)) / BigInt(1000));
                    }
                    onMessage?.({ type: 'Message', data: item } as Message<R>);
                }
            } else if (message.type === 'Message') {
                // set the startTime after the last message timestamp
                if (message.data.Timestamp) {
                    startTimeRef.current = String((BigInt(message.data.Timestamp) + BigInt(1000)) / BigInt(1000));
                }
                onMessage?.(message);
            }
        },
        [onError, onMessage, onComplete, startTimeRef, context],
    );

    const { readyState, sendJsonMessage } = useWebSocket(
        // since is not possible to pass headers in a ws connection we pass the client as query param
        `wss://${window.location.host}/wss?client=${CLIENT_NAME}`,
        {
            reconnectAttempts: MAX_RECONNECT_ATTEMPTS,
            heartbeat: {
                message: 'ping',
                returnMessage: 'pong',
                interval: 25_000,
                timeout: 60_000 * 3,
            },
            shouldReconnect: () => {
                reconnectAttempts.current++;
                // BUGFIX: enforce the max attempts constraint
                return reconnectAttempts.current <= MAX_RECONNECT_ATTEMPTS;
            },
            onMessage: handleMessage,
            onOpen,
        },
        !disabled,
    );

    // Reset state when sessionId changes
    useEffect(() => {
        reconnectAttempts.current = 0;
        startTimeRef.current = undefined;
        initialRequestSentRef.current = false;
    }, [sessionId]);

    // request telemetry
    useEffect(() => {
        if (sessionId && !disabled && readyState === ReadyState.OPEN) {
            // Prevent duplicate initial requests (when startTime is undefined)
            if (!startTimeRef.current && initialRequestSentRef.current) {
                return;
            }
            initialRequestSentRef.current = true;
            sendJsonMessage({
                type: 'telemetry',
                data: {
                    sessionId,
                    context,
                    startTime: startTimeRef.current,
                    targetInstanceCount,
                    is1080p,
                },
            } as TelemetryMessage);
        }
    }, [context, sendJsonMessage, readyState, live, disabled, sessionId, targetInstanceCount, is1080p]);

    return {
        readyState,
    };
};

export const useTelemetry = <R extends { Timestamp?: string }>(props: UseTelemetryProps<R>) => {
    // Mock-mode is a fixed build-time flag, so unconditionally taking one branch or the other here
    // is safe — a given running app instance always calls the same one, every render.
    if (isMockPlayMode) {
        return useMockTelemetry(props);
    }
    return useRealTelemetry(props);
};
