import type { Screenshot } from '@gsm-common/hooks/usePeriodicScreenshots';
import { formatRelativeTime } from '@gsm-common/hooks/usePeriodicScreenshots';
import { download } from '@gsm-common/utils/file/download';
import { useSessionTimelineData } from '@ncgt/session-timeline';
import { IconDownload } from '@hawkins/assets';
import { Button, Modal, ModalBody, ModalFooter, ModalHeader } from '@hawkins/components';
import { useCallback, useState } from 'react';
import { createPortal } from 'react-dom';
import styles from './ScreenshotFilmstrip.module.css';

interface ScreenshotFilmstripProps {
    brushXExtent: [Date, Date] | null;
    sessionStartTimestamp: number;
}

interface HoverState {
    index: number;
    rect: DOMRect;
}

function downloadScreenshot(shot: Screenshot, index: number) {
    const timeLabel = formatRelativeTime(shot.relativeMs).replace(':', 'm');
    const a = document.createElement('a');
    a.href = shot.dataUrl;
    a.download = `screenshot-${index + 1}-${timeLabel}s.jpg`;
    a.click();
}

export const ScreenshotFilmstrip = ({ brushXExtent, sessionStartTimestamp }: ScreenshotFilmstripProps) => {
    const { datasets } = useSessionTimelineData();
    const screenshots = (datasets?.screenshots as Screenshot[] | undefined) ?? [];

    const [hover, setHover] = useState<HoverState | null>(null);
    const [selectedIndex, setSelectedIndex] = useState<number | null>(null);

    const handleMouseEnter = useCallback((index: number, e: React.MouseEvent<HTMLDivElement>) => {
        setHover({ index, rect: e.currentTarget.getBoundingClientRect() });
    }, []);

    const handleMouseLeave = useCallback(() => {
        setHover(null);
    }, []);

    const handleClick = useCallback((index: number) => {
        setHover(null);
        setSelectedIndex(index);
    }, []);

    const handleCloseModal = useCallback(() => {
        setSelectedIndex(null);
    }, []);

    if (screenshots.length === 0) {
        return (
            <div className={styles.empty}>
                <span className={styles.emptyText}>Screenshots captured every 30s during gameplay</span>
            </div>
        );
    }

    // Determine visible domain: use brush extent, or fall back to full screenshot range
    let domainStart: number;
    let domainEnd: number;

    if (brushXExtent) {
        domainStart = brushXExtent[0].getTime();
        domainEnd = brushXExtent[1].getTime();
    } else {
        const times = screenshots.map((s) => sessionStartTimestamp + s.relativeMs);
        domainStart = Math.min(...times);
        domainEnd = Math.max(...times);
    }

    const domainSpan = domainEnd - domainStart;

    const hoveredShot = hover !== null ? screenshots[hover.index] : null;
    const selectedShot = selectedIndex !== null ? screenshots[selectedIndex] : null;

    // For the modal timeline bar — full session range
    const sessionTotalMs = screenshots[screenshots.length - 1]?.relativeMs ?? 0;

    return (
        <>
            <div className={styles.filmstrip}>
                {screenshots.map((shot, i) => {
                    const shotTime = sessionStartTimestamp + shot.relativeMs;
                    const ratio = domainSpan > 0 ? (shotTime - domainStart) / domainSpan : 0;
                    const leftPct = `${(ratio * 100).toFixed(4)}%`;
                    const isHovered = hover?.index === i;

                    return (
                        <div
                            key={i}
                            className={styles.frameWrapper}
                            style={{ left: leftPct }}
                            onMouseEnter={(e) => handleMouseEnter(i, e)}
                            onMouseLeave={handleMouseLeave}
                            onClick={() => handleClick(i)}
                        >
                            <img
                                src={shot.dataUrl}
                                alt={`Screenshot at ${formatRelativeTime(shot.relativeMs)}`}
                                className={`${styles.frame}${isHovered ? ` ${styles.frameHovered}` : ''}`}
                            />
                        </div>
                    );
                })}
            </div>

            {/* Hover popover */}
            {hover !== null && hoveredShot &&
                createPortal(
                    <div
                        className={styles.popover}
                        style={{
                            top: hover.rect.top - 8,
                            left: hover.rect.left + hover.rect.width / 2,
                        }}
                        onMouseEnter={() => setHover(null)}
                    >
                        <span className={styles.popoverTime}>{formatRelativeTime(hoveredShot.relativeMs)}</span>
                        <img
                            src={hoveredShot.dataUrl}
                            alt={`Screenshot at ${formatRelativeTime(hoveredShot.relativeMs)}`}
                            className={styles.popoverImage}
                        />
                        <span className={styles.popoverHint}>Click to expand</span>
                    </div>,
                    document.body,
                )}

            {/* Screenshot detail modal */}
            {selectedShot && (
                <Modal open={selectedIndex !== null} onClose={handleCloseModal} maxWidth='large'>
                    <ModalHeader
                        title={`Screenshot · ${formatRelativeTime(selectedShot.relativeMs)}`}
                    />
                    <ModalBody>
                        {/* Full-size screenshot */}
                        <img
                            src={selectedShot.dataUrl}
                            alt={`Screenshot at ${formatRelativeTime(selectedShot.relativeMs)}`}
                            className={styles.modalImage}
                        />
                    </ModalBody>
                    <ModalFooter>
                        <div className={styles.modalActions}>
                            <Button
                                variant='secondary'
                                icon={IconDownload}
                                onClick={() => downloadScreenshot(selectedShot, selectedIndex ?? 0)}
                            >
                                Download
                            </Button>
                            <Button variant='primary' onClick={handleCloseModal}>
                                Close
                            </Button>
                        </div>
                    </ModalFooter>
                </Modal>
            )}
        </>
    );
};
