import Convert from 'ansi-to-html';
import parse from 'html-react-parser';

export const logFormatter = (s: string, firstOnly: boolean) => {
    return firstOnly ? s.split(/\r?\n/)[0] : s;
};

export const ansiLogFormatter = (() => {
    const convert = new Convert({ escapeXML: true });
    return (s: string, firstOnly: boolean) => {
        return parse(convert.toHtml(logFormatter(s, firstOnly)));
    };
})();
