import { useSessionTimelineData } from '@ncgt/session-timeline';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { GraphSideCard } from './GraphSideCard';
import { computeYAxisLabels } from './utils';

export type FpsSideCardProps = {
    brushXExtent: any[] | null;
};

export const FpsSideCard = ({ brushXExtent }: FpsSideCardProps) => {
    const { datasets } = useSessionTimelineData();
    const fpsDataset: any[] | undefined = datasets?.[ChartType.FPS];

    if (!fpsDataset?.length) return null;

    const [start, end] = brushXExtent ? (brushXExtent as [Date, Date]) : [null, null];

    let visibleSum = 0;
    let visibleCount = 0;
    let sessionSum = 0;
    const allValues: number[] = [];

    for (const point of fpsDataset) {
        sessionSum += point.value;
        allValues.push(point.value);
        if (start && end && point.date >= start && point.date <= end) {
            visibleSum += point.value;
            visibleCount++;
        }
    }

    const visibleAvg = visibleCount > 0 ? visibleSum / visibleCount : null;
    const sessionAvg = fpsDataset.length > 0 ? sessionSum / fpsDataset.length : null;
    const yAxisLabels = computeYAxisLabels(allValues);

    return (
        <GraphSideCard
            title='FPS'
            scoreValue={visibleAvg}
            statRows={[{ label: 'Session Average', value: sessionAvg, decimals: 0 }]}
            yAxisLabels={yAxisLabels}
        />
    );
};
