import {
    type ScaleFn,
    XBandAnnotation,
    XYPopperLines,
    YBandAnnotation,
    YReferenceLine,
} from '@netflix-internal/react-vizkit';
import { SessionChart } from './SessionChart';

export interface TimePeriod {
    value: number;
    label: string;
}

import { useSessionTimelineData } from '@ncgt/session-timeline';
import { CHART_INFO, ChartColors, getRandomColor } from '@ncgt/session-timeline/src/constants';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { useMemo } from 'react';
import styles from './SessionTimelineChart.module.css';
import { withHoverTimeCorner } from './utils';

export interface TargetInstanceCountGraphProps {
    brushXExtent?: any[] | null;
}

const INSTANCE_COUNT_KEY = 'instanceCount';
const BREACH_FILL = 'rgba(229, 9, 20, 0.10)';

function computeInstanceBreachBands(rawData: any[], targetInstanceCount: number): [Date, Date][] {
    const breachTimes = new Set<number>();
    for (const point of rawData) {
        if (point.lineKey === INSTANCE_COUNT_KEY && point.value < targetInstanceCount) {
            breachTimes.add(point.date.getTime());
        }
    }
    if (breachTimes.size === 0) return [];

    const allTimes = [...new Set(rawData.map((d: any) => d.date.getTime() as number))].sort((a, b) => a - b);

    const bands: [Date, Date][] = [];
    let bandStart: number | null = null;
    let prev: number | null = null;

    for (const t of allTimes) {
        if (breachTimes.has(t)) {
            if (bandStart === null) bandStart = t;
            prev = t;
        } else if (bandStart !== null) {
            bands.push([new Date(bandStart), new Date(prev!)]);
            bandStart = null;
            prev = null;
        }
    }
    if (bandStart !== null) bands.push([new Date(bandStart), new Date(prev!)]);
    return bands;
}

export const TargetInstanceCountGraph = (props: TargetInstanceCountGraphProps) => {
    const { datasets, targetInstanceCount } = useSessionTimelineData();

    const { brushXExtent } = props;

    const yBands = useMemo(() => {
        return [[0, targetInstanceCount]] as const;
    }, [targetInstanceCount]);

    const instanceCountDataSet = datasets ? datasets[ChartType.INSTANCE_COUNT] : undefined;

    const breachBands = useMemo(
        () => (instanceCountDataSet ? computeInstanceBreachBands(instanceCountDataSet, targetInstanceCount) : []),
        [instanceCountDataSet, targetInstanceCount],
    );

    if (!instanceCountDataSet?.length) {
        return null;
    }

    const sessionStartTimestamp = instanceCountDataSet[0]
        ? instanceCountDataSet[0].date.getTime() - instanceCountDataSet[0].relativeMs
        : 0;

    const instanceCountData: any | undefined = instanceCountDataSet
        ? {
              points: instanceCountDataSet,
              channels: {
                  x: 'date',
                  y: 'value',
                  dataset: 'lineKey',
                  color: 'lineKey',
                  datasetTitle: (d: any) => {
                      const chartName = CHART_INFO[ChartType.INSTANCE_COUNT]?.name;
                      return chartName || String(d.lineKey).toUpperCase();
                  },
              },
          }
        : undefined;

    return (
        <SessionChart
            data={instanceCountData}
            height={180}
            brushXExtent={brushXExtent}
            color={{
                scale: ((series: string | undefined) => {
                    return series ? ChartColors[series] : getRandomColor(series);
                }) as ScaleFn,
            }}
        >
            <YBandAnnotation bands={yBands} rectProps={{ fill: BREACH_FILL, fillOpacity: 1, stroke: 'none' }} />
            {breachBands.length > 0 && (
                <XBandAnnotation
                    bands={breachBands}
                    rectProps={{ fill: BREACH_FILL, fillOpacity: 1, stroke: 'none' }}
                />
            )}
            <YReferenceLine
                value={targetInstanceCount}
                hideValue
                lineProps={{ stroke: '#eb3942', strokeDasharray: '4 3', strokeWidth: 1.5 }}
            />
            <XYPopperLines
                customize={(info, current) =>
                    withHoverTimeCorner(current, info[0].xValue, sessionStartTimestamp, {
                        hoverTooltipWrap: styles.hoverTooltipWrap,
                        hoverTimeCorner: styles.hoverTimeCorner,
                    })
                }
            />
        </SessionChart>
    );
};
