import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { GraphSideCard } from './GraphSideCard';

export type ErrorWarningSideCardProps = {
    events: LogErrorWarningEvent[];
    // Matches the `any[] | null` shape used by the sibling side cards (FpsSideCard, InstanceCountSideCard, etc.)
    // biome-ignore lint/suspicious/noExplicitAny: matches the sibling side cards' brushXExtent typing
    brushXExtent: any[] | null;
};

export const ErrorWarningSideCard = ({ events, brushXExtent }: ErrorWarningSideCardProps) => {
    const [start, end] = brushXExtent ? (brushXExtent as [Date, Date]) : [null, null];
    const visibleCount = start && end ? events.filter((e) => e.date >= start && e.date <= end).length : null;

    return (
        <GraphSideCard
            title='Errors'
            scoreValue={visibleCount ?? events.length}
            statRows={[{ label: 'Session Total', value: events.length, decimals: 0 }]}
            rowLayout='inline'
        />
    );
};
