import type { LogErrorWarningEvent } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { DataTooltipContents, type DataTooltipContentsProps } from '@netflix-internal/react-vizkit';
import { useMemo, useState } from 'react';
import styles from './SessionTimelineChart.module.css';
import { format, withHoverTimeCorner } from './utils';

export type ErrorWarningMarkersProps = {
    events: LogErrorWarningEvent[];
    /** Visible time domain — same domain driving the shared x-axis / playhead for every other row. */
    domain: [Date, Date] | undefined;
    sessionStartTimestamp: number;
    /** Called with the exact event time (seconds from session start) when a marker is clicked. */
    onMarkerClick?: (seconds: number) => void;
};

const HOVER_TIME_CORNER_CLASSES = {
    hoverTooltipWrap: styles.hoverTooltipWrap,
    hoverTimeCorner: styles.hoverTimeCorner,
};

type PositionedEvent = { event: LogErrorWarningEvent; xPercent: number };

export const ErrorWarningMarkers = ({
    events,
    domain,
    sessionStartTimestamp,
    onMarkerClick,
}: ErrorWarningMarkersProps) => {
    const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);

    // Positioned by percentage of the row's own (rendered) width rather than a JS-measured pixel
    // width — this way the browser handles sizing directly and markers are correctly placed
    // regardless of how the surrounding layout (Dockview panel, flex split, etc.) sizes this row,
    // with no ResizeObserver/measurement timing to get wrong.
    const positioned = useMemo<PositionedEvent[]>(() => {
        if (!domain) return [];
        const [domainStart, domainEnd] = domain;
        const domainStartMs = domainStart.getTime();
        const domainEndMs = domainEnd.getTime();
        if (domainEndMs <= domainStartMs) return [];

        const result: PositionedEvent[] = [];
        for (const event of events) {
            const ms = event.date.getTime();
            if (ms < domainStartMs || ms > domainEndMs) continue;
            const xPercent = ((ms - domainStartMs) / (domainEndMs - domainStartMs)) * 100;
            result.push({ event, xPercent });
        }
        return result;
    }, [events, domain]);

    return (
        <div className={styles.errorMarkersRow}>
            {positioned.map(({ event, xPercent }, index) => {
                const seconds = (event.date.getTime() - sessionStartTimestamp) / 1000;
                const isHovered = hoveredIndex === index;
                return (
                    <button
                        type='button'
                        key={`${event.date.getTime()}-${index}`}
                        className={styles.errorMarker}
                        style={{ left: `${xPercent}%` }}
                        aria-label={`${event.severity === 'error' ? 'Error' : 'Warning'} at ${format(seconds * 1000)}: ${event.message}`}
                        onMouseEnter={() => setHoveredIndex(index)}
                        onMouseLeave={() => setHoveredIndex((prev) => (prev === index ? null : prev))}
                        onFocus={() => setHoveredIndex(index)}
                        onBlur={() => setHoveredIndex((prev) => (prev === index ? null : prev))}
                        onClick={(e) => {
                            e.stopPropagation();
                            onMarkerClick?.(seconds);
                        }}
                    >
                        <div
                            className={
                                event.severity === 'error' ? styles.errorMarkerHeadError : styles.errorMarkerHeadWarn
                            }
                        />
                        <div
                            className={
                                event.severity === 'error' ? styles.errorMarkerLineError : styles.errorMarkerLineWarn
                            }
                        />
                        {isHovered &&
                            (() => {
                                const severityColor =
                                    event.severity === 'error'
                                        ? 'var(--hawkins-theme-foreground-system-error)'
                                        : 'var(--hawkins-theme-foreground-system-warning)';
                                // Same shape every other chart's hover card is built from: a title (here,
                                // the severity) with the shared elapsed-time corner badge, then a colored
                                // dot + label/value metric row (here, the log source) — exactly like the
                                // FPS/STATS tooltips' "● FPS   28.3" row — instead of bespoke subtitle text.
                                const tooltipProps = withHoverTimeCorner<DataTooltipContentsProps>(
                                    {
                                        title: event.severity === 'error' ? 'Error' : 'Warning',
                                        titleColor: severityColor,
                                        metrics: [
                                            {
                                                color: severityColor,
                                                title: 'Source',
                                                value: event.source === 'game' ? 'Game' : 'Controller',
                                            },
                                        ],
                                        description: event.message,
                                    },
                                    event.date,
                                    sessionStartTimestamp,
                                    HOVER_TIME_CORNER_CLASSES,
                                );
                                return (
                                    // Reuses the same standard tooltip box (`vk-tooltip-div`) and contents
                                    // renderer (`DataTooltipContents`) that every other graph's hover card is
                                    // built from — no bespoke tooltip markup/styling, so background, border,
                                    // shadow, and typography stay pixel-for-pixel consistent with the rest of
                                    // the chart.
                                    <div className={`${styles.errorMarkerTooltip} vk-tooltip-div`}>
                                        <DataTooltipContents {...tooltipProps} />
                                    </div>
                                );
                            })()}
                    </button>
                );
            })}
        </div>
    );
};
