export interface TimePeriod {
    value: number;
    label: string;
}

const timePeriods: TimePeriod[] = [
    { value: 10000, label: '10s' },
    { value: 30000, label: '30s' },
    { value: 60000, label: '1m' },
    { value: 300000, label: '5m' },
];

export type SessionTimelineChartProps = {
    sessionId?: string;
    mode: StreamingMode;
    hideInstanceCount?: boolean;
    isVirtualHardware?: boolean;
    enforceEnvelope?: boolean;
    waitingMessage?: string;
    showWaitingLoader?: boolean;
    /** Shared playhead position, in seconds from session start. Null when nothing is selected. */
    currentTime?: number | null;
    /** Epoch ms for t=0 (session start), shared with the logs list for consistent time matching. */
    sessionStartMs?: number;
    /** Which side last set currentTime — used to only auto pan the zoom window for log-originated jumps. */
    playheadSource?: 'graph' | 'log' | null;
    /** Called when the user clicks the graph's plot area, with the clicked time in seconds from session start. */
    onGraphPlayhead?: (seconds: number) => void;
    /** Error/warning markers derived from game + controller logs — always shown, below the screenshots row. */
    errorWarningEvents?: LogErrorWarningEvent[];
};

/** Width (px) of the fixed side-card column to the left of every chart row — see .mainContent grid-template-columns. */
const SIDE_CARD_WIDTH = 150;

type VisibilityState = Partial<Record<ChartType, boolean>>;
enum VisibilityActionTypes {
    TOGGLE = 'TOGGLE',
}
type VisibilityAction = { type: VisibilityActionTypes.TOGGLE; payload: ChartType };

const initialChartVisibilityState: VisibilityState = {
    [ChartType.STATS]: true,
    [ChartType.FPS]: true,
    [ChartType.INSTANCE_COUNT]: true,
    [ChartType.SCREENSHOTS]: true,
};

const toggleVisibilityReducer = (state: VisibilityState, action: VisibilityAction) => {
    switch (action.type) {
        case VisibilityActionTypes.TOGGLE: {
            return { ...state, [action.payload]: !state[action.payload] };
        }
        default:
            return state;
    }
};

const HIDDEN_ENVELOPE_KEYS = new Set(['instanceCountPrediction', 'percentAllottedVRAM', 'vramUsed']);
const STATS_HIDDEN_KEYS = new Set(['instanceCountPrediction']);

const BREACH_KEYS = new Set(['percentAllottedGPU', 'percentAllottedCPU', 'percentAllottedRAM', 'percentAllottedVRAM']);

function computeBreachBands(rawData: any[]): [Date, Date][] {
    const breachTimes = new Set<number>();
    for (const point of rawData) {
        if (BREACH_KEYS.has(point.lineKey) && point.value > 100) {
            breachTimes.add(point.date.getTime());
        }
    }
    if (breachTimes.size === 0) return [];

    const allTimes = [...new Set(rawData.map((d: any) => d.date.getTime() as number))].sort((a, b) => a - b);

    const bands: [Date, Date][] = [];
    let bandStart: number | null = null;
    let prev: number | null = null;

    for (const t of allTimes) {
        if (breachTimes.has(t)) {
            if (bandStart === null) bandStart = t;
            prev = t;
        } else if (bandStart !== null) {
            bands.push([new Date(bandStart), new Date(prev!)]);
            bandStart = null;
            prev = null;
        }
    }
    if (bandStart !== null) bands.push([new Date(bandStart), new Date(prev!)]);
    return bands;
}

export const SessionTimelineChart = (props: SessionTimelineChartProps) => {
    const {
        sessionId,
        mode,
        hideInstanceCount = false,
        isVirtualHardware = false,
        enforceEnvelope,
        waitingMessage,
        showWaitingLoader = false,
        currentTime = null,
        sessionStartMs = 0,
        playheadSource = null,
        onGraphPlayhead,
        errorWarningEvents = [],
    } = props;
    const { datasets, error, isLoading } = useSessionTimelineData();
    const exportOrder = (datasets as any)?.exportOrder;

    const isHiddenKey = (lineKey: string) => hideInstanceCount && HIDDEN_ENVELOPE_KEYS.has(lineKey);

    const theme = useTheme();
    const [state, dispatch] = useReducer(toggleVisibilityReducer, initialChartVisibilityState);

    const chartDataset = datasets ? datasets[ChartType.STATS] : undefined;
    const fpsDataset = datasets ? datasets[ChartType.FPS] : undefined;
    const exportDataSet = datasets ? datasets[ChartType.EXPORT] : undefined;
    const [brushXExtentState, setBrushXExtent] = useState<
        { type: BrushType.LATEST; delta: number } | { type: BrushType.RANGE; extent: any[] } | null
    >({ type: BrushType.LATEST, delta: timePeriods[0].value });

    const fpsData: any | undefined = fpsDataset
        ? {
              points: fpsDataset,
              channels: {
                  x: 'date',
                  y: 'value',
                  dataset: 'lineKey',
                  color: 'lineKey',
                  datasetTitle: (d: any) => ChartLineLabel[d.lineKey] || 'FPS',
              },
          }
        : undefined;

    const data: any | undefined = chartDataset
        ? {
              points: chartDataset.filter(
                  (d: any) => !d.hidden && !isHiddenKey(d.lineKey) && !STATS_HIDDEN_KEYS.has(d.lineKey),
              ),
              channels: {
                  x: 'date',
                  y: 'value',
                  dataset: 'lineKey',
                  color: 'lineKey',
                  datasetTitle: (d: any) => ChartLineLabel[d.lineKey] || String(d.lineKey).toUpperCase(),
              },
          }
        : undefined;

    // Get session start timestamp to convert between relativeMs and Date
    const sessionStartTimestamp = chartDataset?.[0] ? chartDataset[0].date.getTime() - chartDataset[0].relativeMs : 0;

    const hoverTimeCornerClasses = useMemo(
        () => ({ hoverTooltipWrap: styles.hoverTooltipWrap, hoverTimeCorner: styles.hoverTimeCorner }),
        [],
    );

    // Get the latest date timestamp for brush calculations
    const latestDateTimestamp = chartDataset ? chartDataset[chartDataset.length - 1]?.date.getTime() : 0;

    // replace "latest" with actual date to activate maintaining latest edge
    const brushXExtent = useMemo(() => {
        if (brushXExtentState === null) {
            return null;
        }
        if (brushXExtentState.type === BrushType.RANGE) {
            return brushXExtentState.extent;
        }
        // otherwise latest...
        return [new Date(latestDateTimestamp - brushXExtentState.delta), new Date(latestDateTimestamp)];
    }, [brushXExtentState, latestDateTimestamp]);

    const [dismissedError, setDismissedError] = useState<unknown>(null);
    const errorDismissed = error != null && dismissedError === error;

    // Bridge ref + hidden keys state for STATS chart line toggling via side card
    const statsBridgeRef = useRef<VizBridgeRef | null>(null);
    const [hiddenStatKeys, setHiddenStatKeys] = useState<Set<string>>(new Set());
    const toggleStatKey = useCallback((key: string) => {
        statsBridgeRef.current?.toggle(key);
        setHiddenStatKeys((prev) => {
            const next = new Set(prev);
            if (next.has(key)) next.delete(key);
            else next.add(key);
            return next;
        });
    }, []);

    // Stable empty dataset for the ghost x-axis TimeSeries (no marks, just scale)
    const ghostDataRef = useRef({
        points: [] as any[],
        channels: { x: 'date', y: 'value', dataset: 'lineKey', color: 'lineKey', datasetTitle: () => '' },
    });

    // Domain for the ghost axis: use brush extent, or full dataset range as fallback
    const ghostXDomain = useMemo(
        () =>
            brushXExtent ??
            (chartDataset?.length ? [chartDataset[0].date, chartDataset[chartDataset.length - 1].date] : undefined),
        [brushXExtent, chartDataset],
    );

    const breachBands = useMemo(
        () => (enforceEnvelope && chartDataset ? computeBreachBands(chartDataset) : []),
        // chartDataset?.length catches in-place array mutations from live streaming
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [enforceEnvelope, chartDataset, chartDataset?.length],
    );

    const SCRUBBER_BREACH_DELAY_MS = 7000;
    const breachFirstDetectedAt = useRef<number | null>(null);
    const [scrubberBreachBands, setScrubberBreachBands] = useState<[Date, Date][]>([]);

    useEffect(() => {
        if (!enforceEnvelope || breachBands.length === 0) {
            breachFirstDetectedAt.current = null;
            setScrubberBreachBands([]);
            return;
        }
        if (breachFirstDetectedAt.current === null) {
            breachFirstDetectedAt.current = Date.now();
        }
        const remaining = Math.max(0, SCRUBBER_BREACH_DELAY_MS - (Date.now() - breachFirstDetectedAt.current));
        const timer = setTimeout(() => setScrubberBreachBands(breachBands), remaining);
        return () => clearTimeout(timer);
    }, [breachBands, enforceEnvelope]);

    const [hoverX, setHoverX] = useState<number | null>(null);

    const handleChartMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const x = e.clientX - rect.left - SIDE_CARD_WIDTH;
        setHoverX(x >= 0 ? x : null);
    }, []);

    const handleChartMouseLeave = useCallback(() => {
        setHoverX(null);
    }, []);

    // --- Click-sync playhead (sticky, click-only — separate from the hover-only syncSlicer above) ---

    // Tracks the last value *this* click handler produced, so the pan-into-view effect below
    // can tell a log-originated jump (external) apart from a graph click (self-inflicted).
    const lastGraphPlayheadTime = useRef<number | null>(null);

    const handleChartClick = useCallback(
        (e: React.MouseEvent<HTMLDivElement>) => {
            if (!onGraphPlayhead || !ghostXDomain) return;
            const rect = e.currentTarget.getBoundingClientRect();
            const x = e.clientX - rect.left - SIDE_CARD_WIDTH;
            const width = rect.width - SIDE_CARD_WIDTH;
            if (x < 0 || width <= 0) return;

            const [domainStart, domainEnd] = ghostXDomain as [Date, Date];
            const domainStartMs = domainStart.getTime();
            const domainEndMs = domainEnd.getTime();
            if (domainEndMs <= domainStartMs) return;

            const ratio = Math.min(1, Math.max(0, x / width));
            const clickedMs = domainStartMs + ratio * (domainEndMs - domainStartMs);
            const seconds = (clickedMs - sessionStartMs) / 1000;
            lastGraphPlayheadTime.current = seconds;
            onGraphPlayhead(seconds);
        },
        [ghostXDomain, sessionStartMs, onGraphPlayhead],
    );

    // Clicking an error/warning marker snaps precisely to that event's own timestamp,
    // instead of the approximate pixel-derived time `handleChartClick` would compute.
    const handleMarkerClick = useCallback(
        (seconds: number) => {
            if (!onGraphPlayhead) return;
            lastGraphPlayheadTime.current = seconds;
            onGraphPlayhead(seconds);
        },
        [onGraphPlayhead],
    );

    // Percentage position (0-100) of the sticky playhead within the plot area — derived every
    // render from currentTime + the visible domain. Expressed as a CSS percentage rather than a
    // JS-measured pixel width so it's always correct regardless of how the surrounding layout
    // sizes the plot column (this previously relied on a ResizeObserver-measured pixel width,
    // which could land on a stale value depending on the host layout — e.g. a Dockview panel).
    const playheadXPercent = useMemo(() => {
        if (currentTime === null || !ghostXDomain) return null;
        const [domainStart, domainEnd] = ghostXDomain as [Date, Date];
        const domainStartMs = domainStart.getTime();
        const domainEndMs = domainEnd.getTime();
        if (domainEndMs <= domainStartMs) return null;

        const targetMs = sessionStartMs + currentTime * 1000;
        if (targetMs < domainStartMs || targetMs > domainEndMs) return null;

        return ((targetMs - domainStartMs) / (domainEndMs - domainStartMs)) * 100;
    }, [currentTime, ghostXDomain, sessionStartMs]);

    // Logs -> graph: pan/re-center the zoom window when a log-originated jump lands outside the
    // currently visible domain. Graph-originated clicks never need this (they're always in view).
    useEffect(() => {
        if (currentTime === null || playheadSource !== 'log' || !ghostXDomain) return;
        if (lastGraphPlayheadTime.current === currentTime) return;

        const [domainStart, domainEnd] = ghostXDomain as [Date, Date];
        const domainStartMs = domainStart.getTime();
        const domainEndMs = domainEnd.getTime();
        const targetMs = sessionStartMs + currentTime * 1000;
        if (targetMs >= domainStartMs && targetMs <= domainEndMs) return;

        const windowDuration = domainEndMs - domainStartMs;
        setBrushXExtent({
            type: BrushType.RANGE,
            extent: [new Date(targetMs - windowDuration / 2), new Date(targetMs + windowDuration / 2)],
        });
    }, [currentTime, playheadSource, ghostXDomain, sessionStartMs]);

    const { trackEvent } = useFullStory();

    const onExportCSV = useCallback(() => {
        trackEvent('Perf Graph CSV');
        const relativeMap = new Map();
        const series: { [key: string]: any[] } = {};

        // Aggregate by relativeMs and keep track of associated points
        exportDataSet.forEach((point: any) => {
            const relativeMs = point.relativeMs;
            if (!relativeMap.has(relativeMs)) {
                relativeMap.set(relativeMs, { points: [point], row: [] });
            } else {
                relativeMap.get(relativeMs).points.push(point);
            }
            if (!series[point.lineKey]) {
                series[point.lineKey] = [];
            }
        });

        // Use server-provided exportOrder for header columns
        if (!exportOrder) {
            createError({
                title: 'CSV Export Failed',
                body: 'No export data available',
                options: {
                    id: 'csv-export-error',
                },
            });
            return;
        }
        const filteredExportOrder = hideInstanceCount
            ? exportOrder.filter((key: string) => !HIDDEN_ENVELOPE_KEYS.has(key))
            : exportOrder;
        const keys = ['ts', ...filteredExportOrder];
        const headerRow = keys.map((key) => (key === 'ts' ? 'Time (s)' : ChartLineLabel[key] || key.toUpperCase()));
        const csv = [[...headerRow].join(',')];

        // Build data rows - iterate through relativeMs values and look up values for each metric
        const relativeValues = Array.from(relativeMap.keys()).sort((a, b) => a - b);
        for (const relativeMs of relativeValues) {
            // Convert to relative seconds from session start
            const relativeTimeSec = (relativeMs / 1000).toFixed(3);
            const row: (string | number)[] = [relativeTimeSec];
            const data = relativeMap.get(relativeMs);

            for (const metricKey of filteredExportOrder) {
                const point = data?.points.find((p: any) => p.lineKey === metricKey);
                if (point?.value !== undefined && point?.value !== null) {
                    // Format based on metric name: utilization metrics get 6 decimals, others get 1
                    const formatted = metricKey.toLowerCase().includes('utilization')
                        ? point.value.toFixed(6)
                        : point.value.toFixed(1);
                    row.push(formatted);
                } else {
                    row.push('');
                }
            }

            csv.push(row.join(','));
        }

        download(`perf_${sessionId ?? 'data'}`, csv.join('\n'));
    }, [sessionId, trackEvent, exportDataSet, exportOrder, hideInstanceCount]);

    const onBrush = useCallback((bounds: any, { xScale }: any) => {
        if (bounds) {
            const xExtent = [(xScale as any).invert(bounds[0][0]), (xScale as any).invert(bounds[1][0])] as [
                Date,
                Date,
            ];

            // if we dragged to the end, save the end value is "latest" so we can dynamically fill it in.
            const draggedToEnd = bounds[1][0] >= xScale.range()[1];
            if (draggedToEnd) {
                setBrushXExtent({
                    type: BrushType.LATEST,
                    delta: xExtent[1].getTime() - xExtent[0].getTime(),
                });
                return;
            }

            // otherwise fix the range even as data updates
            setBrushXExtent({ type: BrushType.RANGE, extent: xExtent });
        } else {
            setBrushXExtent(null);
        }
    }, []);

    // Only show full error state if there's no chart data to display
    if (error && !chartDataset) {
        return (
            <div className={styles.errorWrapper}>
                <Stack gap={Dimensions.Space4}>
                    <Text as='h4' weight='bold'>
                        Session Performance Error
                    </Text>
                    <Text colorVariant='faded'>
                        {typeof error === 'string'
                            ? error
                            : 'An unknown error occurred while loading session performance data.'}
                    </Text>
                </Stack>
            </div>
        );
    }

    return (
        <div className={styles.chartRoot}>
            {error && !errorDismissed && (
                <ContextualBanner
                    variant='neutral'
                    text={
                        typeof error === 'string'
                            ? error
                            : 'Data stream interrupted. Showing data collected before the error.'
                    }
                    actionIcon={IconX}
                    onActionClick={() => setDismissedError(error)}
                    fullWidth
                    compact
                />
            )}
            {isVirtualHardware && (
                <ContextualBanner
                    text='Running on virtual OCGA hardware. Resource utilization percentages are not calibrated and not all metrics are available. RAM and VRAM values in MB are accurate.'
                    variant='warning'
                />
            )}

            {/* Action bar: always visible — icon-only action buttons (right) */}
            <div className={styles.actionBar}>
                <div className={styles.actionBarLeft} />
                <Stack gap={Dimensions.Space8} orientation='horizontal'>
                    <Button
                        compact
                        variant='icon'
                        icon={IconDownload}
                        aria-label='Export CSV'
                        tooltipLabel='Download the performance graph report.'
                        disabled={!exportDataSet}
                        onClick={onExportCSV}
                    />
                    <Menu
                        showCaret
                        trigger={
                            <Button
                                compact
                                variant='icon'
                                icon={IconGraphDashed}
                                aria-label='Graph options'
                                tooltipLabel='Toggle the visibilities of session performance graphs.'
                            />
                        }
                    >
                        {[
                            ChartType.STATS,
                            ChartType.FPS,
                            ...(hideInstanceCount || isVirtualHardware ? [] : [ChartType.INSTANCE_COUNT]),
                            ChartType.SCREENSHOTS,
                        ].map((chartType: ChartType) => (
                            <MenuItem
                                key={chartType}
                                onClick={() => {
                                    dispatch({ type: VisibilityActionTypes.TOGGLE, payload: chartType });
                                }}
                            >
                                <Stack
                                    gap={Dimensions.Space8}
                                    orientation='horizontal'
                                    layout={{ justifyContent: 'space-between', display: 'flex' }}
                                >
                                    {CHART_INFO[chartType]?.name}
                                    {state[chartType] ? (
                                        <IconCheckboxSelected size='small' />
                                    ) : (
                                        <IconCheckboxUnselected size='small' />
                                    )}
                                </Stack>
                            </MenuItem>
                        ))}
                    </Menu>
                </Stack>
            </div>

            {chartDataset ? (
                <>
                    {/* Session averages top card */}
                    <SessionTimelineSummaryCard hideInstanceCount={hideInstanceCount} />

                    {/* Time period bar: toggle group (left, 150px) + shared x-axis (right, full chart width) */}
                    <div className={styles.timePeriodBar}>
                        <div className={styles.timePeriodButtons}>
                            <ToggleButtonGroup
                                compact
                                value={
                                    (brushXExtentState?.type === BrushType.LATEST && brushXExtentState?.delta) || null
                                }
                                onChange={(_, value: ToggleButtonValue | ToggleButtonValue[]) => {
                                    if (value) {
                                        setBrushXExtent({ type: BrushType.LATEST, delta: Number(value) });
                                    }
                                }}
                            >
                                {timePeriods.map((tp) => (
                                    <ToggleButton key={tp.label} value={tp.value}>
                                        {tp.label}
                                    </ToggleButton>
                                ))}
                            </ToggleButtonGroup>
                        </div>
                        {/* Ghost TimeSeries — renders only the shared XAxis, no data marks */}
                        <VizkitProvider darkMode={theme.name === 'dark'}>
                            <div className={styles.xAxisArea}>
                                <TimeSeries
                                    data={ghostDataRef.current}
                                    width='100%'
                                    height={32}
                                    x={{
                                        accessor: 'date',
                                        domain: ghostXDomain,
                                    }}
                                    y={{
                                        accessor: 'value',
                                        axis: false,
                                    }}
                                    disableGroups={['LineEndcaps', 'XYPopperLines', 'CursorLine']}
                                >
                                    <XAxis
                                        formatter={(tick: Date) => {
                                            const delta = tick.getTime() - sessionStartTimestamp;
                                            return format(delta);
                                        }}
                                        render={({ tick, ticks, index, formatter }) => {
                                            const formatted = formatter(tick, index, ticks);
                                            if (
                                                index > 0 &&
                                                (formatted == null ||
                                                    formatter(ticks[index - 1], index - 1, ticks) === formatted)
                                            ) {
                                                return null;
                                            }
                                            return undefined;
                                        }}
                                    />
                                </TimeSeries>
                            </div>
                        </VizkitProvider>
                    </div>

                    {/* Main: scrollable area containing all graph rows */}
                    <div className={styles.chartsScrollArea}>
                        <VizkitProvider darkMode={theme.name === 'dark'}>
                            <div
                                className={styles.mainContent}
                                onMouseMove={handleChartMouseMove}
                                onMouseLeave={handleChartMouseLeave}
                                onClick={handleChartClick}
                            >
                                {/* STATS row */}
                                {state[ChartType.STATS] && (
                                    <>
                                        <div className={styles.sideCardCell}>
                                            <VisibleAveragesCard
                                                brushXExtent={brushXExtent}
                                                hideInstanceCount={hideInstanceCount}
                                                onToggleKey={toggleStatKey}
                                                hiddenKeys={hiddenStatKeys}
                                            />
                                        </div>
                                        <div className={styles.chartCell}>
                                            <SessionChart
                                                data={data}
                                                height='auto'
                                                defaultHeight={300}
                                                brushXExtent={brushXExtent}
                                                color={{
                                                    scale: ((series: string | undefined) => {
                                                        return series ? ChartColors[series] : getRandomColor(series);
                                                    }) as ScaleFn,
                                                }}
                                            >
                                                {enforceEnvelope && data && data.points.length > 0 && (
                                                    <>
                                                        <YBandAnnotation
                                                            bands={[[100, 1e6]]}
                                                            rectProps={{
                                                                fill: 'rgba(229, 9, 20, 0.07)',
                                                                fillOpacity: 1,
                                                                stroke: 'none',
                                                            }}
                                                        />
                                                        {breachBands.length > 0 && (
                                                            <XBandAnnotation
                                                                bands={breachBands}
                                                                rectProps={{
                                                                    fill: 'rgba(229, 9, 20, 0.07)',
                                                                    fillOpacity: 1,
                                                                    stroke: 'none',
                                                                }}
                                                            />
                                                        )}
                                                        <YReferenceLine
                                                            value={100}
                                                            hideValue
                                                            lineProps={{
                                                                stroke: '#eb3942',
                                                                strokeDasharray: '4 3',
                                                                strokeWidth: 1.5,
                                                            }}
                                                        />
                                                    </>
                                                )}
                                                <XYPopperLines
                                                    customize={(info, current, viz) => {
                                                        const xValue = info[0].xValue?.getTime();
                                                        let withExtras = current;
                                                        const extraPoints = xValue
                                                            ? chartDataset?.filter(
                                                                  (d: any) => d.hidden && d.date.getTime() === xValue,
                                                              )
                                                            : undefined;
                                                        if (extraPoints && extraPoints.length > 0) {
                                                            withExtras = {
                                                                ...current,
                                                                metrics: [
                                                                    ...(current.metrics ?? []),
                                                                    ...extraPoints.map((extraPoint: any) => ({
                                                                        // biome-ignore lint/style/noNonNullAssertion: Docs example
                                                                        value: info[0].yFormatter(
                                                                            viz.yAccessor!(extraPoint),
                                                                        ),
                                                                        label:
                                                                            ChartLineLabel[extraPoint.lineKey] ||
                                                                            extraPoint.lineKey.toUpperCase(),
                                                                        divider: extraPoint.divider,
                                                                    })),
                                                                ],
                                                            };
                                                        }
                                                        return withHoverTimeCorner(
                                                            withExtras,
                                                            info[0].xValue,
                                                            sessionStartTimestamp,
                                                            hoverTimeCornerClasses,
                                                        );
                                                    }}
                                                />
                                                <VizBridge bridgeRef={statsBridgeRef} />
                                            </SessionChart>
                                            {hoverX !== null && (
                                                <div className={styles.syncSlicer} style={{ left: hoverX }} />
                                            )}
                                            {playheadXPercent !== null && (
                                                <div
                                                    className={styles.playhead}
                                                    style={{ left: `${playheadXPercent}%` }}
                                                >
                                                    <span className={styles.playheadLabel}>
                                                        {format((currentTime ?? 0) * 1000)}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}

                                {/* FPS row */}
                                {state[ChartType.FPS] && (
                                    <>
                                        <div className={styles.sideCardCell}>
                                            <FpsSideCard brushXExtent={brushXExtent} />
                                        </div>
                                        <div className={styles.chartCell}>
                                            <SessionChart
                                                data={fpsData}
                                                height={150}
                                                brushXExtent={brushXExtent}
                                                color={{
                                                    scale: ((_series: string | undefined) => '#e0e0e0') as ScaleFn,
                                                }}
                                            >
                                                <XYPopperLines
                                                    customize={(info, current) =>
                                                        withHoverTimeCorner(
                                                            current,
                                                            info[0].xValue,
                                                            sessionStartTimestamp,
                                                            hoverTimeCornerClasses,
                                                        )
                                                    }
                                                />
                                            </SessionChart>
                                            {hoverX !== null && (
                                                <div className={styles.syncSlicer} style={{ left: hoverX }} />
                                            )}
                                            {playheadXPercent !== null && (
                                                <div
                                                    className={styles.playhead}
                                                    style={{ left: `${playheadXPercent}%` }}
                                                >
                                                    <span className={styles.playheadLabel}>
                                                        {format((currentTime ?? 0) * 1000)}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}

                                {/* Instance Count row */}
                                {!hideInstanceCount && !isVirtualHardware && state[ChartType.INSTANCE_COUNT] && (
                                    <>
                                        <div className={styles.sideCardCell}>
                                            <InstanceCountSideCard brushXExtent={brushXExtent} />
                                        </div>
                                        <div className={styles.chartCell}>
                                            <TargetInstanceCountGraph brushXExtent={brushXExtent} />
                                            {hoverX !== null && (
                                                <div className={styles.syncSlicer} style={{ left: hoverX }} />
                                            )}
                                            {playheadXPercent !== null && (
                                                <div
                                                    className={styles.playhead}
                                                    style={{ left: `${playheadXPercent}%` }}
                                                >
                                                    <span className={styles.playheadLabel}>
                                                        {format((currentTime ?? 0) * 1000)}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}

                                {/* Screenshots row */}
                                {state[ChartType.SCREENSHOTS] && (
                                    <>
                                        <div className={styles.sideCardCell}>
                                            <ScreenshotSideCard />
                                        </div>
                                        <div className={styles.chartCell}>
                                            <ScreenshotFilmstrip
                                                brushXExtent={brushXExtent as [Date, Date] | null}
                                                sessionStartTimestamp={sessionStartTimestamp}
                                            />
                                            {hoverX !== null && (
                                                <div className={styles.syncSlicer} style={{ left: hoverX }} />
                                            )}
                                            {playheadXPercent !== null && (
                                                <div
                                                    className={styles.playhead}
                                                    style={{ left: `${playheadXPercent}%` }}
                                                >
                                                    <span className={styles.playheadLabel}>
                                                        {format((currentTime ?? 0) * 1000)}
                                                    </span>
                                                </div>
                                            )}
                                        </div>
                                    </>
                                )}

                                {/* Error & Warnings row — always shown (not gated behind the graph options
                                    toggle), derived from game + controller logs rather than a ChartType dataset. */}
                                <div className={styles.sideCardCell}>
                                    <ErrorWarningSideCard events={errorWarningEvents} brushXExtent={brushXExtent} />
                                </div>
                                <div className={styles.chartCell}>
                                    <ErrorWarningMarkers
                                        events={errorWarningEvents}
                                        domain={ghostXDomain as [Date, Date] | undefined}
                                        sessionStartTimestamp={sessionStartTimestamp}
                                        onMarkerClick={handleMarkerClick}
                                    />
                                    {hoverX !== null && <div className={styles.syncSlicer} style={{ left: hoverX }} />}
                                    {playheadXPercent !== null && (
                                        <div className={styles.playhead} style={{ left: `${playheadXPercent}%` }}>
                                            <span className={styles.playheadLabel}>
                                                {format((currentTime ?? 0) * 1000)}
                                            </span>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </VizkitProvider>
                    </div>

                    {/* Scrubber — always at the bottom, outside the chart stack */}
                    {chartDataset?.length > 2 && (
                        <div className={styles.scrubberRow}>
                            <ScrubberSideCard />
                            <VizkitProvider darkMode={theme.name === 'dark'}>
                                <div className={styles.scrubberChartArea}>
                                    <TimeSeries
                                        data={data}
                                        width={'100%'}
                                        height={80}
                                        color={{
                                            scale: ((series: string | undefined) => {
                                                return series ? ChartColors[series] : getRandomColor(series);
                                            }) as ScaleFn,
                                        }}
                                        x={{
                                            accessor: 'date',
                                            title: 'Time',
                                            showTitle: false,
                                        }}
                                        y={{
                                            accessor: 'value',
                                            title: 'Some number',
                                            axis: false,
                                            showTitle: false,
                                            domainMin: 0,
                                        }}
                                        disableGroups={['LineEndcaps', 'XYPopperLines', 'CursorLine']}
                                    >
                                        <XAxis
                                            formatter={(tick: Date) => {
                                                const delta = tick.getTime() - sessionStartTimestamp;
                                                return format(delta);
                                            }}
                                            render={({ tick, ticks, index, formatter }) => {
                                                const formatted = formatter(tick, index, ticks);
                                                if (
                                                    index > 0 &&
                                                    (formatted == null ||
                                                        formatter(ticks[index - 1], index - 1, ticks) === formatted)
                                                ) {
                                                    return null;
                                                }
                                                return undefined;
                                            }}
                                        />
                                        {scrubberBreachBands.length > 0 && (
                                            <XBandAnnotation
                                                bands={scrubberBreachBands}
                                                rectProps={{
                                                    fill: 'rgba(229, 9, 20, 0.3)',
                                                    fillOpacity: 1,
                                                    stroke: 'none',
                                                }}
                                            />
                                        )}
                                        <Brush axis='x' brushExtent={brushXExtent} onBrush={onBrush} />
                                    </TimeSeries>
                                </div>
                            </VizkitProvider>
                        </div>
                    )}
                </>
            ) : (
                <div className={styles.centeredLayout}>
                    {waitingMessage ? (
                        <>
                            {showWaitingLoader && <Loader />}
                            <Text colorVariant='faded'>{waitingMessage}</Text>
                        </>
                    ) : mode === StreamingMode.INITIAL || mode === StreamingMode.CLOSED ? (
                        <Text>No data</Text>
                    ) : (
                        <Loader />
                    )}
                </div>
            )}
        </div>
    );
};
