import { IconX } from '@hawkins/assets';
import clsx from 'clsx';
import styles from './SessionSummaryBanner.module.css';
import type { PerformanceSummary } from './generatePerformanceSummary';

interface SessionSummaryBannerProps {
    summary: PerformanceSummary;
    onDismiss: () => void;
}

const SEVERITY_LABEL: Record<PerformanceSummary['severity'], string> = {
    fail: '⚠ Performance Issues',
    warn: '△ Minor Spikes',
    pass: '✓ Session Passed',
};

export const SessionSummaryBanner = ({ summary, onDismiss }: SessionSummaryBannerProps) => {
    const { severity, text } = summary;

    // All three severities render on a solid Hawkins system color (error/warning/success), so
    // text, badge, and dismiss button always use the inverse foreground token for contrast.
    const bannerClass = clsx(styles.banner, {
        [styles.bannerFail]: severity === 'fail',
        [styles.bannerWarn]: severity === 'warn',
        [styles.bannerPass]: severity === 'pass',
    });

    return (
        <div className={bannerClass} role='status' aria-live='polite'>
            {/* AI badge */}
            <span className={styles.badge}>✦ AI Summary</span>

            {/* One-line body */}
            <div className={styles.body}>
                <span className={styles.severityLabel}>{SEVERITY_LABEL[severity]}</span>
                <span className={styles.text}>{text}</span>
            </div>

            {/* Dismiss */}
            <button
                className={styles.dismiss}
                onClick={onDismiss}
                aria-label='Dismiss performance summary'
                type='button'
            >
                <IconX size='small' />
            </button>
        </div>
    );
};
