import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import { getMockScreenAt } from '@gsm-app/mocks/mockGameplayScreens';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useCallback, useEffect, useRef, useState } from 'react';

export type Screenshot = {
    /** Milliseconds since session start */
    relativeMs: number;
    dataUrl: string;
};

export const SCREENSHOT_INTERVAL_OPTIONS = [
    { label: '2s', value: 2_000 },
    { label: '5s', value: 5_000 },
    { label: '10s', value: 10_000 },
    { label: '30s', value: 30_000 },
    { label: '60s', value: 60_000 },
];

export type ScreenshotQuality = 'low' | 'medium' | 'high';

export const SCREENSHOT_QUALITY_OPTIONS: { label: string; value: ScreenshotQuality }[] = [
    { label: 'Low', value: 'low' },
    { label: 'Medium', value: 'medium' },
    { label: 'High', value: 'high' },
];

const QUALITY_JPEG_VALUE: Record<ScreenshotQuality, number> = {
    low: 0.4,
    medium: 0.7,
    high: 0.95,
};

export const DEFAULT_CAPTURE_INTERVAL_MS = 5_000;
export const DEFAULT_SCREENSHOT_QUALITY: ScreenshotQuality = 'medium';
const FIRST_CAPTURE_DELAY_MS = 3_000;

const captureVideoFrame = (sessionStartMs: number, quality: ScreenshotQuality): Screenshot | null => {
    const video = document.querySelector<HTMLVideoElement>('#video_canvas > video');
    if (!video || video.readyState < 2 || video.videoWidth === 0) return null;

    try {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (!ctx) return null;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        return {
            relativeMs: Date.now() - sessionStartMs,
            dataUrl: canvas.toDataURL('image/jpeg', QUALITY_JPEG_VALUE[quality]),
        };
    } catch {
        return null;
    }
};

export const formatRelativeTime = (ms: number): string => {
    const totalSeconds = Math.floor(ms / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
};

/**
 * Shared OPEN/CLOSED/INITIAL lifecycle + capture-interval plumbing, parameterized by how an
 * individual frame is actually captured — used by both the real (video-frame) and mock
 * (placeholder-image) implementations below.
 *
 * Lifecycle:
 *   OPEN (fresh start) → clears any previous session's screenshots, begins capturing
 *   CLOSED             → stops capturing, retains screenshots so they remain viewable
 *   INITIAL            → full reset (clears screenshots)
 */
const usePeriodicScreenshotsCore = (
    mode: StreamingMode,
    enabled: boolean,
    captureIntervalMs: number,
    captureFn: (sessionStartMs: number) => Screenshot | null,
): Screenshot[] => {
    const [screenshots, setScreenshots] = useState<Screenshot[]>([]);
    const sessionStartMsRef = useRef<number | null>(null);

    useEffect(() => {
        if (mode === StreamingMode.OPEN) {
            if (sessionStartMsRef.current === null) {
                // New session starting — discard any screenshots from the previous session
                setScreenshots([]);
                sessionStartMsRef.current = Date.now();
            }
        } else if (mode === StreamingMode.CLOSED) {
            // Session ended — stop the capture timer but keep screenshots for review
            sessionStartMsRef.current = null;
        } else if (mode === StreamingMode.INITIAL) {
            // App-level reset — clear everything
            sessionStartMsRef.current = null;
            setScreenshots([]);
        }
    }, [mode]);

    const capture = useCallback(() => {
        const start = sessionStartMsRef.current;
        if (start === null) return;
        const shot = captureFn(start);
        if (shot) setScreenshots((prev) => [...prev, shot]);
    }, [captureFn]);

    useEffect(() => {
        if (mode !== StreamingMode.OPEN || !enabled) return;

        const firstCapture = setTimeout(capture, FIRST_CAPTURE_DELAY_MS);
        const interval = setInterval(capture, captureIntervalMs);

        return () => {
            clearTimeout(firstCapture);
            clearInterval(interval);
        };
    }, [mode, enabled, captureIntervalMs, capture]);

    return screenshots;
};

/** Periodically captures real JPEG frames from the game video stream while a session is active. */
const useRealPeriodicScreenshots = (
    mode: StreamingMode,
    enabled: boolean,
    captureIntervalMs: number,
    quality: ScreenshotQuality,
): Screenshot[] => {
    const captureFn = useCallback((start: number) => captureVideoFrame(start, quality), [quality]);
    return usePeriodicScreenshotsCore(mode, enabled, captureIntervalMs, captureFn);
};

/**
 * Local-only UI dev mode — there's no real video element to grab a frame from (see
 * `MockGameplayPlaceholder`), so this "captures" whichever placeholder image the mock gameplay
 * view was showing at that instant instead, via the same time-based `getMockScreenAt` lookup.
 */
const useMockPeriodicScreenshots = (
    mode: StreamingMode,
    enabled: boolean,
    captureIntervalMs: number,
): Screenshot[] => {
    const captureFn = useCallback((start: number): Screenshot => {
        const now = Date.now();
        return { relativeMs: now - start, dataUrl: getMockScreenAt(now) };
    }, []);
    return usePeriodicScreenshotsCore(mode, enabled, captureIntervalMs, captureFn);
};

export const usePeriodicScreenshots = (
    mode: StreamingMode,
    enabled: boolean,
    captureIntervalMs: number = DEFAULT_CAPTURE_INTERVAL_MS,
    quality: ScreenshotQuality = DEFAULT_SCREENSHOT_QUALITY,
): Screenshot[] => {
    // Mock-mode is a fixed build-time flag, so unconditionally taking one branch or the other here
    // is safe — a given running app instance always calls the same one, every render.
    if (isMockPlayMode) {
        return useMockPeriodicScreenshots(mode, enabled, captureIntervalMs);
    }
    return useRealPeriodicScreenshots(mode, enabled, captureIntervalMs, quality);
};
