import type { ErrorMessage } from '@gsm-app/models/ErrorMessage';
import type { Message } from '@gsm-app/models/Message';
import { useStateDebounced } from '@gsm-common/hooks/useStateDebounced';
import { createError } from '@gsm-common/utils/toast/createError';
import * as OcgaProto from '@ocga/proto';
import { useCallback, useEffect, useState } from 'react';
import { useTelemetry } from './useTelemetry';

type UseSessionLogsProps = {
    sessionId?: string | undefined;
    live?: boolean;
    disabled?: boolean;
};

type Log = {
    MessageType: number;
    Timestamp: string;
    ProcessContext?: {
        Component: number;
    };
    Message: {
        LogEvent?: {
            Fields?: {
                subService?: {
                    String?: string;
                };
            };
            Message: string;
        };
        HostConnectionEvent?: {
            Hostname: string;
            IPAddr: string;
            Port: number;
        };
    };
};

export const formatLog = (message: Message<Log>): undefined | string[] => {
    let msg: string | undefined;
    let type: string | undefined;

    switch (message.data?.MessageType) {
        case OcgaProto.MessageType.MessageType.LogEvent: {
            const logEvent = message?.data?.Message?.LogEvent;
            // Check if this is a game log from component or subservice
            const component = message?.data?.ProcessContext?.Component;
            const subService = logEvent?.Fields?.subService?.String;
            const isGameLog = subService === 'game' || component === OcgaProto.Component.Component.Game;

            msg = isGameLog ? logEvent?.Message : undefined;
            break;
        }
        case OcgaProto.MessageType.MessageType.HostConnectionEvent: {
            const { Hostname, IPAddr, Port } = message?.data?.Message.HostConnectionEvent || {};
            msg = `[NetworkEvent]\nHost: ${Hostname}\nIp: ${IPAddr}\nPort: ${Port}`;
            type = `${OcgaProto.MessageType.MessageType.HostConnectionEvent}`;
            break;
        }
        default:
            break;
    }
    let timestamp = message?.data?.Timestamp;

    if (!msg || !timestamp) {
        return undefined;
    }

    timestamp = new Date(Number(timestamp.slice(0, 10)) * 1000).toISOString();

    const result = [timestamp ?? '', msg ?? ''];
    if (type) {
        result.push(type);
    }
    return result;
};

const handleDeviceLost = (log: string[] | undefined) => {
    if (log && Boolean(log.find((str) => str.toUpperCase().includes('VK_ERROR_DEVICE_LOST')))) {
        createError({
            title: 'Error Device Lost',
            body: 'The session could not connect to the device.',
            options: {
                id: 'device-lost-error',
            },
        });
    }
};

export const useSessionGameLogs = ({ disabled, sessionId, live }: UseSessionLogsProps = {}) => {
    const [error, setError] = useState<ErrorMessage | undefined>();
    const [completed, setCompleted] = useState(false);
    const [logs, setLogs] = useStateDebounced<string[][]>([], 200, { maxWait: 2000, leading: true });

    const onMessage = useCallback(
        (message: Message<Log>) => {
            const log = formatLog(message);
            if (log) {
                handleDeviceLost(log);
                setLogs((prev) => [...prev, log]);
            }
        },
        [setLogs],
    );

    // clear the session logs on new session
    useEffect(() => {
        setLogs([]);
        setCompleted(false);
    }, [setLogs, sessionId]);

    const onError = useCallback(({ message }: any) => {
        setError(message);
    }, []);

    const onComplete = useCallback(() => {
        setCompleted(true);
    }, []);

    useTelemetry<Log>({
        sessionId,
        disabled,
        live,
        context: 'game',
        onMessage,
        onError,
        onComplete,
    });

    const clearLogs = useCallback(() => setLogs([]), [setLogs]);

    return {
        error,
        data: logs,
        loading: logs.length === 0 && !error && !(completed && !live),
        completed: completed && !live,
        clearLogs,
    };
};
