import { useCallback, useEffect, useState } from 'react';

export interface Item {
    id: string;
    text: string;
}

const getLocalStorageValue = <T>(key: string, defaultValue: T) => {
    let value;
    try {
        value = JSON.parse(localStorage.getItem(key) ?? '');
    } catch {
        value = defaultValue;
    }
    return value;
};

export const useLocalStorage = <T>(key: string, defaultValue: T) => {
    // set default if value is missing
    useEffect(() => {
        if (!localStorage.getItem(key)) {
            window.localStorage.setItem(key, JSON.stringify(defaultValue));
        }
    }, [key, defaultValue]);

    const [syncedStore, setSyncedStore] = useState<Item[]>(getLocalStorageValue(key, defaultValue));

    // keep localstorage and state in-sync
    const setStorage = useCallback(
        (callback: (value: Item[]) => Item[]) => {
            setSyncedStore(oldValue => {
                let newValue = callback(oldValue);
                window.localStorage.setItem(key, JSON.stringify(newValue));
                return newValue;
            });
        },
        [key, setSyncedStore, setSyncedStore],
    );

    return [syncedStore, setStorage] as const;
};
