import type { Message } from '@gsm-app/models/Message';
import { Component, MessageType } from '@ocga/proto';

type MockTelemetryContext = 'game' | 'session' | 'ncgtmetrics' | 'controller';

const GAME_LOG_LINES = [
    'Loaded save checkpoint from slot 3',
    'Player joined lobby',
    'Rendered frame batch (1832 draw calls)',
    'Physics tick completed in 4.2ms',
    'Audio buffer underrun recovered',
    'AI pathfinding recalculated for 12 units',
    'Streaming asset bundle "level_04.pak"',
    'Checkpoint saved',
];
const GAME_ERROR_LINES = [
    'Error: failed to load texture atlas "characters_04.png"',
    'Exception thrown while parsing save file (corrupt checkpoint)',
    'Error: null reference in EnemySpawner.Update()',
];
const CONTROLLER_LOG_LINES = [
    'Controller input latency 8ms',
    'Rumble effect triggered',
    'Stick drift compensation applied',
    'Button mapping profile "default" loaded',
];
const CONTROLLER_ERROR_LINES = [
    'Error: controller disconnected unexpectedly',
    'Exception: failed to parse input report',
];

let nanoBase = BigInt(Date.now()) * 1_000_000n;
const nextTimestampNs = (): string => {
    nanoBase += 1_000_000_000n; // +1s
    return nanoBase.toString();
};

const pick = <T>(arr: T[]): T => arr[Math.floor(Math.random() * arr.length)];

const buildLogMessage = (text: string, source: 'game' | 'controller'): Message<any> => ({
    type: 'Message',
    data: {
        MessageType: MessageType.MessageType.LogEvent,
        Timestamp: nextTimestampNs(),
        ProcessContext: { Component: source === 'game' ? Component.Component.Game : Component.Component.GIM },
        Message: {
            LogEvent: {
                Fields: { subService: { String: source } },
                Message: text,
            },
        },
    },
});

const randomWalk = (prev: number, min: number, max: number, step: number): number => {
    const next = prev + (Math.random() - 0.5) * step;
    return Math.min(max, Math.max(min, next));
};

/**
 * Drives `onMessage`/`onOpen`/`onComplete` on an interval, standing in for the real `/wss` telemetry
 * WebSocket in local-only mock mode (see `useTelemetry.ts`). One generator per `context` covers game
 * logs, controller logs, and the perf graph's fps/stats/instanceCount datasets — the same three
 * consumers that share the real `useTelemetry` hook — so all of it lights up together with zero
 * per-hook mocking. Returns a cleanup function to stop the interval.
 */
export const startMockTelemetry = (
    context: MockTelemetryContext,
    handlers: {
        onOpen?: (event: Event) => void;
        onMessage: (message: Message<any>) => void;
    },
): (() => void) => {
    handlers.onOpen?.(new Event('open'));

    if (context === 'session') {
        return () => {};
    }

    if (context === 'game' || context === 'controller') {
        const lines = context === 'game' ? GAME_LOG_LINES : CONTROLLER_LOG_LINES;
        const errorLines = context === 'game' ? GAME_ERROR_LINES : CONTROLLER_ERROR_LINES;
        const interval = setInterval(() => {
            const isError = Math.random() < 0.08;
            const text = isError ? pick(errorLines) : pick(lines);
            handlers.onMessage(buildLogMessage(text, context));
        }, 1500);
        return () => clearInterval(interval);
    }

    // context === 'ncgtmetrics' — perf graph datasets (fps/stats/instanceCount lines).
    let cpu = 30;
    let gpu = 35;
    let ram = 40;
    let vram = 25;
    let fps = 58;
    let instanceCount = 3;

    // The chart derives its x-axis (and "session start" reference used for tick labels / CSV export)
    // from each point's `relativeMs` — mirroring the real backend's `date - sessionStartTime`
    // (see apps/server/utils/telemetry.ts's `createMetricObjects`). Without it, `relativeMs` is
    // `undefined` on every point and `date.getTime() - relativeMs` (SessionTimelineChart.tsx) is NaN,
    // rendering "NaN:NaN" axis ticks even though the data values themselves are fine.
    const sessionStartTime = Date.now();

    const interval = setInterval(() => {
        cpu = randomWalk(cpu, 5, 95, 12);
        gpu = randomWalk(gpu, 5, 95, 14);
        ram = randomWalk(ram, 5, 90, 8);
        vram = randomWalk(vram, 5, 85, 6);
        fps = randomWalk(fps, 28, 60, 6);
        instanceCount = Math.round(randomWalk(instanceCount, 1, 8, 1));

        const now = Date.now();
        const relativeMs = now - sessionStartTime;
        handlers.onMessage({
            type: 'Message',
            data: {
                // Keys/units mirror exactly what the real backend puts in the 'stats' telemetry
                // category (apps/server/utils/telemetry.ts's TELEMETRY_METRICS_CONFIG) — the raw
                // per-process counters (gameCPUUtilization, etc.) are 'export'-only there and never
                // actually reach the live graph, so mocking them here (as an earlier version of this
                // file did) fed the chart keys it doesn't have display names/colors for.
                stats: [
                    { lineKey: 'percentAllottedCPU', value: cpu, date: now, relativeMs },
                    { lineKey: 'percentAllottedGPU', value: gpu, date: now, relativeMs },
                    { lineKey: 'percentAllottedRAM', value: ram, date: now, relativeMs },
                    { lineKey: 'percentAllottedVRAM', value: vram, date: now, relativeMs },
                ],
                fps: [{ lineKey: 'fps', value: fps, date: now, relativeMs }],
                instanceCount: [{ lineKey: 'instanceCountPrediction', value: instanceCount, date: now, relativeMs }],
            },
        });
    }, 1000);
    return () => clearInterval(interval);
};
