type CSVOptions = { removeEmptyRows?: boolean };

export const toCSV = <T>(data: T[][], options: CSVOptions = { removeEmptyRows: true }): string => {
    const csv: string[] = [];
    data.forEach((row) => {
        if (row) {
            let empty = true;
            const rowString = row
                .map((col) => {
                    const isString = typeof col === 'string';
                    if (col === null || col === undefined || (isString && col === '')) {
                        return '""';
                    }
                    empty = false;
                    if (isString && (col.includes(',') || col.includes('"') || col.includes('\n'))) {
                        return `"${col.replace(/"/g, '""')}"`;
                    }
                    return col;
                })
                .join(',');
            // row should have a value
            if (options?.removeEmptyRows && empty) {
                return;
            }
            return csv.push(rowString);
        }
    });
    return csv.join('\r\n');
};
