import { useSessionTimelineData } from '@ncgt/session-timeline';
import { ChartColors } from '@ncgt/session-timeline/src/constants';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { GraphSideCard } from './GraphSideCard';
import { computeYAxisLabels } from './utils';

export type VisibleAveragesCardProps = {
    brushXExtent: any[] | null;
    hideInstanceCount?: boolean;
    onToggleKey?: (key: string) => void;
    hiddenKeys?: Set<string>;
};

const HIDDEN_ENVELOPE_KEYS = new Set(['instanceCountPrediction', 'percentAllottedVRAM', 'vramUsed']);

const SUMMARY_ORDER = [
    'percentAllottedGPU',
    'percentAllottedCPU',
    'percentAllottedRAM',
    'percentAllottedVRAM',
    'instanceCountPrediction',
];

const HIDDEN_METRIC_KEYS = new Set(['fps', 'instanceCountPrediction']);

const sortByOrder = (keys: string[]) =>
    [...keys].sort((a, b) => {
        const ai = SUMMARY_ORDER.indexOf(a);
        const bi = SUMMARY_ORDER.indexOf(b);
        return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
    });

const METRIC_SHORT_NAMES: Record<string, string> = {
    percentAllottedGPU: 'GPU',
    percentAllottedCPU: 'CPU',
    percentAllottedRAM: 'RAM',
    percentAllottedVRAM: 'VRAM',
    fps: 'FPS',
    instanceCountPrediction: 'Instances',
};

const METRIC_UNITS: Record<string, string> = {
    percentAllottedGPU: '%',
    percentAllottedCPU: '%',
    percentAllottedRAM: '%',
    percentAllottedVRAM: '%',
    fps: '',
    instanceCountPrediction: '',
};

const STACK_VALUE_KEYS = new Set(['instanceCountPrediction', 'gpuVRAMUsed', 'residentMemory']);
const THRESHOLD_KEYS = new Set([
    'percentAllottedGPU',
    'percentAllottedCPU',
    'percentAllottedRAM',
    'percentAllottedVRAM',
]);

// Keys whose raw data values are not in the same "percentage" unit space as the
// primary allotted-resource metrics. Excluded from Y-axis range computation so
// byte-scale values (gpuVRAMUsed, residentMemory) don't blow out the scale.
const BYTE_SCALE_KEYS = new Set(['gpuVRAMUsed', 'residentMemory', 'vramUsed']);

function formatBytes(bytes: number): { value: number; unit: string } {
    if (bytes >= 1024 ** 3) return { value: bytes / 1024 ** 3, unit: 'GB' };
    if (bytes >= 1024 ** 2) return { value: bytes / 1024 ** 2, unit: 'MB' };
    if (bytes >= 1024) return { value: bytes / 1024, unit: 'KB' };
    return { value: bytes, unit: 'B' };
}

const METRIC_VALUE_TRANSFORMS: Record<string, (v: number) => { value: number; unit: string }> = {
    gpuVRAMUsed: formatBytes,
    residentMemory: formatBytes,
};

export const VisibleAveragesCard = ({
    brushXExtent,
    hideInstanceCount = false,
    onToggleKey,
    hiddenKeys,
}: VisibleAveragesCardProps) => {
    const { datasets } = useSessionTimelineData();

    // Compute Y-axis labels from the full STATS dataset so the scale reflects
    // the real data range. Filter out the same keys the chart excludes, plus
    // user-toggled-off keys (hiddenKeys) so the scale shrinks when a high-value
    // line is hidden — matching user expectations.
    const statsDataset: any[] | undefined = datasets?.[ChartType.STATS];
    const statsValues: number[] = [];
    if (statsDataset) {
        for (const point of statsDataset) {
            if (point.hidden) continue;
            if (HIDDEN_METRIC_KEYS.has(point.lineKey)) continue;
            if (hideInstanceCount && HIDDEN_ENVELOPE_KEYS.has(point.lineKey)) continue;
            if (BYTE_SCALE_KEYS.has(point.lineKey)) continue;
            if (hiddenKeys?.has(point.lineKey)) continue;
            statsValues.push(point.value);
        }
    }
    const yAxisLabels = computeYAxisLabels(statsValues);

    const visibleAverages: Record<string, { count: number; value: number }> = {};

    if (brushXExtent) {
        const [start, end] = brushXExtent as Date[];
        for (const chartType of [ChartType.STATS, ChartType.FPS, ChartType.INSTANCE_COUNT]) {
            if (datasets?.[chartType]) {
                (datasets[chartType] as any[]).forEach((point: any) => {
                    if (hideInstanceCount && HIDDEN_ENVELOPE_KEYS.has(point.lineKey)) return;
                    if (point.date >= start && point.date <= end) {
                        if (!visibleAverages[point.lineKey]) {
                            visibleAverages[point.lineKey] = { count: 0, value: 0 };
                        }
                        visibleAverages[point.lineKey].count += 1;
                        visibleAverages[point.lineKey].value += point.value;
                    }
                });
            }
        }
    }

    const keys = sortByOrder(Object.keys(visibleAverages)).filter((key) => !HIDDEN_METRIC_KEYS.has(key));
    const hasData = keys.length > 0;

    return (
        <GraphSideCard
            title='Visible Averages'
            metrics={
                hasData
                    ? keys.map((key) => {
                          const raw = visibleAverages[key].value / visibleAverages[key].count;
                          const transform = METRIC_VALUE_TRANSFORMS[key];
                          const { value, unit } = transform
                              ? transform(raw)
                              : { value: raw, unit: METRIC_UNITS[key] || undefined };
                          return {
                              lineKey: key,
                              color: ChartColors[key] ?? '#888',
                              label: METRIC_SHORT_NAMES[key] ?? key.toUpperCase(),
                              value,
                              unit,
                              stackValue: STACK_VALUE_KEYS.has(key),
                              threshold: THRESHOLD_KEYS.has(key) ? 100 : undefined,
                          };
                      })
                    : []
            }
            yAxisLabels={yAxisLabels}
            emptyMessage='Select a range'
            onToggleKey={onToggleKey}
            hiddenKeys={hiddenKeys}
        />
    );
};
