import { type PromiseStatus, PromiseTracker } from '@gsm-common/hooks/usePromiseTracker';
import { type AnyIconProps, IconCheckmark, IconWarning } from '@hawkins/assets';
import type { ComponentType, ReactNode } from 'react';
import toast, { type ToastOptions } from 'react-hot-toast';
import { createToast, type ToastProps } from './createToast';

type Icon = false | ComponentType<AnyIconProps> | undefined;
type StatusElements<T> = Partial<Record<PromiseStatus, T>>;

type ToastProgressProps = Omit<ToastProps, 'title' | 'icon'> & {
    title: StatusElements<ReactNode>;
    icon?: StatusElements<Icon>;
    showLoader?: boolean;
    options: ToastOptions & { id: string };
};

const defaultIcons: StatusElements<Icon> = {
    success: IconCheckmark,
    error: IconWarning,
};

export const createProgress = (
    promise: Promise<unknown>,
    { icon = defaultIcons, title, showLoader = true, ...rest }: ToastProgressProps,
) => {
    return new PromiseTracker(promise, status => {
        // explicitly remove the previous toast
        toast.remove(rest.options.id);

        createToast({
            title: title[status],
            icon: icon?.[status],
            dismissible: status !== 'loading',
            showLoader: showLoader && status === 'loading',
            ...rest,
            options: {
                duration: status === 'success' ? rest?.options.duration : Infinity,
                ...rest.options,
            },
        });
    });
};
