import type { Message } from '@gsm-app/models/Message';
import type { ResourceEnvelope } from '@ncgt/resource-envelope';
import { type ChartType, ChartTypes } from '@ncgt/session-timeline/src/types';
import type { DataConfig } from '@netflix-internal/react-vizkit';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useSessionSettings } from './useSessionSettings';
import { DEFAULT_TARGET_INSTANCE_COUNT, useTargetInstanceCount } from './useTargetInstanceCount';
import { useTelemetry } from './useTelemetry';

type UseSessionMetricsProps = {
    gameId?: number | undefined;
    sessionId?: string | undefined;
    live?: boolean;
    disabled?: boolean;
    resourceEnvelope?: ResourceEnvelope | null;
    videoResolution?: number;
};

const MACHINE_RAM_GIB = 256;

/*
 * When a workload-budget envelope is present, replaces server-computed percentAllotted*
 * values with envelope-relative percentages so graphs reflect this game's specific budget.
 */
function applyEnvelopeOverride(message: any, envelope: ResourceEnvelope): any {
    const exportItems: any[] = message.export ?? [];

    const valuesByKey = new Map<string, number>();
    for (const item of exportItems) {
        if (item.lineKey && item.value != null) {
            valuesByKey.set(item.lineKey, item.value);
        }
    }

    const overrides: Record<string, number> = {};

    const percentOfBudget = (budget: number | undefined, actual: number | undefined): number | undefined =>
        budget && budget > 0 && actual != null ? (100 * actual) / budget : undefined;

    const cpu = percentOfBudget(envelope.cpuUtilization, valuesByKey.get('gameCPUUtilization'));
    if (cpu != null) overrides.percentAllottedCPU = cpu;

    const gpu = percentOfBudget(envelope.gpuUtilization, valuesByKey.get('gameGPUTimeUtilization'));
    if (gpu != null) overrides.percentAllottedGPU = gpu;

    const gameRAMUtilization = valuesByKey.get('gameRAMUtilization');
    const ram = percentOfBudget(
        envelope.ramSizeGiB,
        gameRAMUtilization != null ? gameRAMUtilization * MACHINE_RAM_GIB : undefined,
    );
    if (ram != null) overrides.percentAllottedRAM = ram;

    if (Object.keys(overrides).length === 0) return message;

    const applyToArray = (arr: any[]): any[] =>
        arr.map((point: any) => (point.lineKey in overrides ? { ...point, value: overrides[point.lineKey] } : point));

    return {
        ...message,
        stats: message.stats ? applyToArray(message.stats) : message.stats,
        export: message.export ? applyToArray(message.export) : message.export,
    };
}

export function getTime(timestamp: string | number): number {
    // convert the timestamp from nanoseconds to milliseconds
    return (Number(timestamp) / 1000000) * 1000;
}

export const useSessionTimelineMetrics = ({
    gameId,
    sessionId,
    live,
    disabled,
    resourceEnvelope,
    videoResolution,
}: UseSessionMetricsProps) => {
    const datasetsRef = useRef<{ [key: string]: DataConfig<any> | any[] | undefined }>({});
    const targetInstanceCountRef = useRef<number | undefined>(undefined);
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(!live);

    const { resolution: settingsResolution } = useSessionSettings(gameId?.toString());
    // Use video resolution if provided (for historical sessions), otherwise fall back to session settings
    const resolution = videoResolution ?? settingsResolution;
    const {
        targetInstanceCount: fetchedTargetInstanceCount,
        isFetched: isTargetFetched,
        isError: isTargetError,
    } = useTargetInstanceCount(gameId?.toString(), resolution);

    // Reset the graph when session changes
    // biome-ignore lint/correctness/useExhaustiveDependencies: Force trigger on datasetRef and session changes
    useEffect(() => {
        if (sessionId) {
            datasetsRef.current = {};
            targetInstanceCountRef.current = undefined;
            setError(null);
            setLoading(!live);
        }
    }, [sessionId, datasetsRef]);

    // Capture target instance count once when it's fetched for this session
    useEffect(() => {
        if (sessionId && isTargetFetched && targetInstanceCountRef.current === undefined) {
            targetInstanceCountRef.current = fetchedTargetInstanceCount;
        }
    }, [sessionId, fetchedTargetInstanceCount, isTargetFetched]);

    // Surface target IC fetch failure (unlikely — requires all react-query retries to fail).
    // Graph still renders but metrics are scaled to the default target. Error is not cleared
    // on retry success because already-rendered data used the wrong target; changing it in
    // flight would be confusing. User must refresh to get correctly scaled metrics.
    useEffect(() => {
        if (isTargetError) {
            setError('Failed to fetch target instance count for this game. Metric percentages may be inaccurate using default target.');
        }
    }, [isTargetError]);

    const sortPendingRef = useRef(false);
    const dirtyChartsRef = useRef(new Set<string>());

    const scheduleSortOnce = useCallback(() => {
        if (!sortPendingRef.current) {
            sortPendingRef.current = true;
            queueMicrotask(() => {
                sortPendingRef.current = false;
                for (const chart of dirtyChartsRef.current) {
                    (datasetsRef.current[chart] as any[])?.sort((a, b) => a.relativeMs - b.relativeMs);
                }
                dirtyChartsRef.current.clear();
            });
        }
    }, []);

    const updateMetrics = useCallback(
        (message: any) => {
            const adjusted = resourceEnvelope ? applyEnvelopeOverride(message, resourceEnvelope) : message;

            // Capture exportOrder from the first message and store in datasetsRef
            if (!datasetsRef.current.exportOrder && adjusted.exportOrder) {
                datasetsRef.current.exportOrder = adjusted.exportOrder;
            }

            const chartTypes = Object.keys(adjusted);
            chartTypes.forEach((chart) => {
                if (!datasetsRef.current[chart]) {
                    datasetsRef.current[chart] = [];
                }

                // Check for the message type is for a chart
                if (!ChartTypes.includes(chart as ChartType)) {
                    return;
                }

                adjusted[chart]?.forEach((point: any) => {
                    const date = new Date(point.date);
                    (datasetsRef.current[chart] as any[]).push({
                        ...point,
                        date,
                    });
                });

                dirtyChartsRef.current.add(chart);
            });

            // Defer sort — coalesces multiple updateMetrics calls into a single sort pass
            scheduleSortOnce();
        },
        [resourceEnvelope, datasetsRef, scheduleSortOnce],
    );

    const onMessage = useCallback(
        (message: Message) => {
            updateMetrics(message.data);
        },
        [updateMetrics],
    );

    const onError = useCallback((error: any) => {
        setError(error.message);
    }, []);

    const onComplete = useCallback(() => {
        setLoading(false);
    }, []);

    const targetInstanceCount = targetInstanceCountRef.current ?? DEFAULT_TARGET_INSTANCE_COUNT;

    useTelemetry({
        sessionId,
        live,
        disabled: disabled || !isTargetFetched,
        context: 'ncgtmetrics',
        targetInstanceCount,
        is1080p: resolution === 1080,
        onMessage,
        onError,
        onComplete,
    });

    return {
        targetInstanceCount,
        datasets: datasetsRef?.current,
        error,
        exportOrder: datasetsRef.current.exportOrder as string[] | undefined,
        loading,
    };
};
