import { useSessionTimelineData } from '@ncgt/session-timeline';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { GraphSideCard, type GraphSideCardStatRow } from './GraphSideCard';
import { computeYAxisLabels } from './utils';

export type InstanceCountSideCardProps = {
    brushXExtent: any[] | null;
};

export const InstanceCountSideCard = ({ brushXExtent }: InstanceCountSideCardProps) => {
    const { datasets, targetInstanceCount } = useSessionTimelineData();
    const instanceDataset: any[] | undefined = datasets?.[ChartType.INSTANCE_COUNT];

    if (!instanceDataset?.length) return null;

    const [start, end] = brushXExtent ? (brushXExtent as [Date, Date]) : [null, null];

    let visibleSum = 0;
    let visibleCount = 0;
    let sessionSum = 0;
    const allValues: number[] = [];

    for (const point of instanceDataset) {
        sessionSum += point.value;
        allValues.push(point.value);
        if (start && end && point.date >= start && point.date <= end) {
            visibleSum += point.value;
            visibleCount++;
        }
    }

    const visibleAvg = visibleCount > 0 ? visibleSum / visibleCount : null;
    const sessionAvg = instanceDataset.length > 0 ? sessionSum / instanceDataset.length : null;
    const yAxisLabels = computeYAxisLabels(allValues);

    const statRows: GraphSideCardStatRow[] = [
        { label: 'Session Average', value: sessionAvg, decimals: 0 },
        ...(targetInstanceCount != null ? [{ label: 'Threshold', value: targetInstanceCount, decimals: 0 }] : []),
    ];

    return (
        <GraphSideCard
            title='Instance Count'
            scoreValue={visibleAvg}
            statRows={statRows}
            yAxisLabels={yAxisLabels}
            scoreAlertBelow={30}
        />
    );
};
