/**
 * Values accepted by games-start / BFG `ocgaSoftwareConstraints.allowedGameDevPool`.
 */
export const SOFTWARE_GAME_DEV_POOL_VALUES = [
    'GAME_DEV_POOL_PREVIEW',
    'GAME_DEV_POOL_OFFICIAL',
    'GAME_DEV_POOL_PREVIOUS',
] as const;

export type SoftwareGameDevPoolValue = (typeof SOFTWARE_GAME_DEV_POOL_VALUES)[number];

/** Which OCGA steering override card is active in the session settings form */
export type SteeringOverrideMode = 'uuid' | 'hardware' | 'software';

export interface SessionSettings {
    resolutionOverride?: number;
    fpsOverride?: number;
    ocgaSteeringOverride?: string;
    hardwareVersionSelection?: string; // Format: "hardwareName:environment"
    softwareGameDevPool?: SoftwareGameDevPoolValue;
}

export type SoftwarePoolDropdownOption = { label: string; value: SoftwareGameDevPoolValue };

/**
 * Hardware + environment row from {@link useOcgaHardwareVersions} (VOCGA name × DEV / GAME_DEV).
 * `isInternal` shows the internal-only tag for the DEV option.
 */
export type HardwareVersionDropdownOption = {
    label: string;
    value: string;
    subtitle: string;
    isInternal?: boolean;
};
