import { InternalMenuTag } from '@gsm-app/components/InternalMenuTag';
import { TEST_FPS_OPTIONS, VIDEO_RESOLUTION_OPTIONS } from '@gsm-app/constants';
import { DEFAULT_TEST_FPS, DEFAULT_TEST_RESOLUTION } from '@gsm-app/constants';
import { useFeature } from '@gsm-app/hooks/useFeature';
import type { NgpConfig } from '@gsm-app/hooks/useNgpConfig';
import { useOcgaHardwareVersions } from '@gsm-app/hooks/useOcgaHardwareVersions';
import { useSessionSettings } from '@gsm-app/hooks/useSessionSettings';
import { isValidUUID } from '@gsm-app/utils/uuid';
import { IconRefresh } from '@hawkins/assets';
import {
    Button,
    ButtonGroup,
    ContextualBanner,
    Dropdown,
    type DropdownOption,
    Input,
    Paper,
    Popover,
    type PopoverProps,
    Stack,
    Text,
    Toggle,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { yupResolver } from '@hookform/resolvers/yup';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useState } from 'react';
import { Controller, useForm } from 'react-hook-form';
import { useSearchParams } from 'react-router-dom';
import * as yup from 'yup';
import type { SessionSettings } from './SessionSettingsModal';

const OVERRIDE_HISTORY_KEY = 'ncgt_overrideHistory';
const MAX_OVERRIDE_HISTORY_LENGTH = 5;

const sessionSettingsSchema = yup.object({
    ocgaSteeringOverride: yup
        .string()
        .test('is-valid-uuid', 'Must be a valid UUID', (value) => {
            if (!value || value === '') return true;
            return isValidUUID(value);
        })
        .optional(),
    hardwareVersionSelection: yup.string().optional(),
    resolutionOverride: yup.number().oneOf([720, 1080]).optional(),
    fpsOverride: yup.number().oneOf([30, 60]).optional(),
});

const HARDWARE_NAME_MAP: Record<string, string> = {
    'CG-AWS-G6-4XL-01': 'VOCGA G6',
    'CG-AWS-G5-4XL-01': 'VOCGA G5',
    'CG-AWS-G4DN-4XL-01': 'VOCGA G4DN',
    'CG-2026-01': 'OCGA 2026',
    'CG-2025-01': 'OCGA V3',
    'CG-2024-01': 'OCGA V2',
    'CG-2024-02': 'OCGA V2',
    'CG-2022-02': 'OCGA V1',
    'CG-2022-01': 'OCGA V1',
};

const getFriendlyHardwareName = (name: string): string => HARDWARE_NAME_MAP[name] || name;

export interface SessionSettingsContentRef {
    save: () => void;
}

export interface SessionSettingsContentProps {
    /** Used to trigger form reset when the panel/modal becomes active */
    isActive: boolean;
    playing?: boolean;
    gameId: string;
    ngpConfig?: NgpConfig;
    onSave: (settings: SessionSettings) => void;
    onCancel?: () => void;
    /** When true, renders Save/Cancel buttons at the bottom */
    showFooter?: boolean;
}

export const SessionSettingsContent = forwardRef<SessionSettingsContentRef, SessionSettingsContentProps>(
    function SessionSettingsContentInner(
    {
    isActive,
    playing,
    gameId: _gameId,
    ngpConfig,
    onSave,
    onCancel,
    showFooter = true,
}: SessionSettingsContentProps, ref) {
    const { sessionSettings } = useSessionSettings();
    const { data: hardwareVersions, isLoading: isLoadingHardwareVersions } = useOcgaHardwareVersions();
    const { ocgaTargeting } = useFeature();
    const telemetry = useTelemetry();
    telemetry.setLoggingTag('ncgtportal', 'SessionSettingsContent');

    const [overrideOcgaSteering, setOverrideOcgaSteering] = useState(false);
    const [overrideOcgaVideoSettings, setOverrideOcgaVideoSettings] = useState(false);
    const [overrideMethod, setOverrideMethod] = useState<'uuid' | 'hardware'>('uuid');
    const [isPopoverOpen, setPopoverOpen] = useState(false);
    const [searchParams, setSearchParams] = useSearchParams();

    const onToggle: PopoverProps['onToggle'] = ({ open, reason }) => {
        if (reason !== 'click' || open === true) {
            setPopoverOpen(open);
        }
    };

    const getDefaultValues = useCallback(() => {
        const ngpResolution = ngpConfig?.resolution || DEFAULT_TEST_RESOLUTION;
        const ngpFps = ngpConfig?.fps || DEFAULT_TEST_FPS;
        return {
            ocgaSteeringOverride: sessionSettings.ocgaSteeringOverride || '',
            hardwareVersionSelection: sessionSettings.hardwareVersionSelection || undefined,
            resolutionOverride: sessionSettings.resolutionOverride || ngpResolution,
            fpsOverride: sessionSettings.fpsOverride || ngpFps,
        };
    }, [ngpConfig, sessionSettings]);

    const {
        control,
        handleSubmit,
        reset,
        formState: { errors },
        watch,
        setValue,
        getValues,
    } = useForm<SessionSettings>({
        resolver: yupResolver(sessionSettingsSchema),
        defaultValues: getDefaultValues(),
    });

    useEffect(() => {
        const ocgaUUIDParam = searchParams.get('ocgaUUID');
        if (ocgaUUIDParam) {
            setOverrideOcgaSteering(true);
            setValue('ocgaSteeringOverride', ocgaUUIDParam);
        }
    }, [searchParams, setValue]);

    useEffect(() => {
        if (isActive) {
            setOverrideOcgaSteering(
                Boolean(sessionSettings.ocgaSteeringOverride || sessionSettings.hardwareVersionSelection),
            );
            setOverrideOcgaVideoSettings(Boolean(sessionSettings.resolutionOverride || sessionSettings.fpsOverride));
            if (sessionSettings.hardwareVersionSelection) {
                setOverrideMethod('hardware');
            } else {
                setOverrideMethod('uuid');
            }
            reset(getDefaultValues());
        }
    }, [isActive, sessionSettings, reset, getDefaultValues]);

    const currentOcgaSteering = watch('ocgaSteeringOverride');
    const currentResolution = watch('resolutionOverride');
    const currentFps = watch('fpsOverride');

    type HardwareOption = { label: string; value: string; subtitle: string; isInternal?: boolean };

    const hardwareEnvironmentOptions = useMemo(() => {
        const options: HardwareOption[] = [];
        hardwareVersions.forEach((hw) => {
            const friendlyName = getFriendlyHardwareName(hw.name);
            if (hw.availableIn.DEV) {
                options.push({
                    label: friendlyName,
                    value: `${hw.name}:DEV`,
                    subtitle: `${hw.name} | DEV`,
                    isInternal: true,
                });
            }
            if (hw.availableIn.GAME_DEV) {
                options.push({ label: friendlyName, value: `${hw.name}:GAME_DEV`, subtitle: `${hw.name} | GAME_DEV` });
            }
        });
        return options;
    }, [hardwareVersions]);

    const CustomDropdownListItemLabel = (props: {
        option?: HardwareOption;
        getOptionLabel?: (opt: HardwareOption) => string;
    }) => {
        const { option, getOptionLabel } = props;
        return (
            <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', width: '100%' }}>
                <span>{option && getOptionLabel?.(option)}</span>
                {option?.isInternal && (
                    <InternalMenuTag style={{ marginLeft: Dimensions.Space8, marginTop: Dimensions.Space8 }} />
                )}
            </div>
        );
    };

    const applyDefaults = useCallback(() => {
        const ngpResolution = ngpConfig?.resolution || DEFAULT_TEST_RESOLUTION;
        const ngpFps = ngpConfig?.fps || DEFAULT_TEST_FPS;
        setValue('resolutionOverride', ngpResolution);
        setValue('fpsOverride', ngpFps);
    }, [ngpConfig, setValue]);

    const buildSettings = useCallback(
        (data: SessionSettings): SessionSettings => {
            const settings: SessionSettings = {};
            if (overrideOcgaSteering) {
                if (overrideMethod === 'uuid') {
                    const uuid = data.ocgaSteeringOverride?.trim();
                    if (uuid && isValidUUID(uuid)) settings.ocgaSteeringOverride = uuid;
                } else if (overrideMethod === 'hardware' && data.hardwareVersionSelection) {
                    settings.hardwareVersionSelection = data.hardwareVersionSelection;
                }
            }
            if (overrideOcgaVideoSettings) {
                if (data.resolutionOverride) settings.resolutionOverride = data.resolutionOverride;
                if (data.fpsOverride) settings.fpsOverride = data.fpsOverride;
            }
            return settings;
        },
        [overrideOcgaSteering, overrideMethod, overrideOcgaVideoSettings],
    );

    const [overrideHistory, setOverrideHistory] = useState<string[]>([]);

    const readNormalizedOverrideHistory = useCallback(() => {
        try {
            const raw = localStorage.getItem(OVERRIDE_HISTORY_KEY) ?? '[]';
            let parsed: unknown;
            try {
                parsed = JSON.parse(raw);
            } catch (e) {
                telemetry.logger.warn(`overrideHistory:parse_failed_raw_json: ${String(e)}`);
                parsed = raw;
            }
            if (typeof parsed === 'string') {
                const normalized = isValidUUID(parsed) ? [parsed] : [];
                try {
                    localStorage.setItem(OVERRIDE_HISTORY_KEY, JSON.stringify(normalized));
                } catch (e) {
                    telemetry.logger.warn(`overrideHistory:setItem_failed_normalized_single: ${String(e)}`);
                }
                return normalized;
            }
            if (Array.isArray(parsed)) {
                const cleaned = (parsed as unknown[]).filter(
                    (v): v is string => typeof v === 'string' && isValidUUID(v),
                );
                try {
                    localStorage.setItem(OVERRIDE_HISTORY_KEY, JSON.stringify(cleaned));
                } catch (e) {
                    telemetry.logger.warn(`overrideHistory:setItem_failed_cleaned_array: ${String(e)}`);
                }
                return cleaned;
            }
            try {
                localStorage.removeItem(OVERRIDE_HISTORY_KEY);
            } catch (e) {
                telemetry.logger.warn(`overrideHistory:removeItem_failed: ${String(e)}`);
            }
            return [];
        } catch (e) {
            telemetry.logger.warn(`overrideHistory:read_failed: ${String(e)}`);
            return [];
        }
    }, [telemetry.logger]);

    const updateOverrideStorage = useCallback(() => {
        try {
            const next = readNormalizedOverrideHistory();
            const value = currentOcgaSteering?.trim();
            if (value && isValidUUID(value)) {
                const existingIndex = next.indexOf(value);
                if (existingIndex > -1) next.splice(existingIndex, 1);
                next.unshift(value);
            }
            if (next.length > MAX_OVERRIDE_HISTORY_LENGTH) next.length = MAX_OVERRIDE_HISTORY_LENGTH;
            try {
                localStorage.setItem(OVERRIDE_HISTORY_KEY, JSON.stringify(next));
            } catch (e) {
                telemetry.logger.warn(`overrideHistory:setItem_failed_update: ${String(e)}`);
            }
        } catch (e) {
            telemetry.logger.warn(`overrideHistory:update_failed: ${String(e)}`);
        }
    }, [currentOcgaSteering, readNormalizedOverrideHistory, telemetry.logger]);

    const saveSettings = useCallback(
        (settings: SessionSettings) => {
            if (!settings.ocgaSteeringOverride) {
                const nextParams = new URLSearchParams(searchParams);
                nextParams.delete('ocgaUUID');
                setSearchParams(nextParams);
            }
            onSave(settings);
            updateOverrideStorage();
        },
        [searchParams, setSearchParams, onSave, updateOverrideStorage],
    );

    const onSubmit = handleSubmit((data) => saveSettings(buildSettings(data)));

    const handleSaveAndClose = useCallback(() => {
        saveSettings(buildSettings(getValues()));
    }, [getValues, buildSettings, saveSettings]);

    useImperativeHandle(ref, () => ({ save: handleSaveAndClose }), [handleSaveAndClose]);

    useEffect(() => {
        if (isActive) setOverrideHistory(readNormalizedOverrideHistory());
    }, [isActive, readNormalizedOverrideHistory]);

    const resolutionOptionValue = useMemo(
        () => VIDEO_RESOLUTION_OPTIONS.find((o) => o.value === currentResolution),
        [currentResolution],
    );
    const fpsOptionValue = useMemo(() => TEST_FPS_OPTIONS.find((o) => o.value === currentFps), [currentFps]);

    return (
        <Stack gap={Dimensions.RawSpace16}>
            <Text variant='body' colorVariant='faded' gutterBottom={Dimensions.Space4}>
                {playing ? (
                    <ContextualBanner
                        text='Session settings cannot be modified during play'
                        variant='error'
                        fullWidth
                    />
                ) : (
                    'Session settings are set at the start of a game'
                )}
            </Text>

            <Stack gap={Dimensions.RawSpace12}>
                <Toggle
                    disabled={playing}
                    checked={overrideOcgaSteering}
                    label='Override OCGA Steering'
                    name='OCGA Steering Override Toggle'
                    onChange={(_event, newChecked) => {
                        setOverrideOcgaSteering(newChecked);
                        if (!newChecked) {
                            setValue('ocgaSteeringOverride', '');
                            setValue('hardwareVersionSelection', undefined);
                        }
                    }}
                />
                {overrideOcgaSteering && (
                    <Stack gap={Dimensions.Space12}>
                        {ocgaTargeting && (
                            <Paper
                                elevation={0}
                                style={{
                                    padding: Dimensions.Space12,
                                    cursor: 'pointer',
                                    borderRadius: 'var(--hawkins-dimensions-border-radius-4)',
                                    border: '1px solid var(--hawkins-theme-border-subtle)',
                                    background:
                                        overrideMethod === 'hardware'
                                            ? 'var(--hawkins-theme-surface-highlight)'
                                            : 'transparent',
                                    opacity: overrideMethod === 'hardware' ? 1 : 0.5,
                                }}
                                onClick={() => {
                                    if (!playing) {
                                        setOverrideMethod('hardware');
                                        setValue('ocgaSteeringOverride', '');
                                    }
                                }}
                            >
                                <div
                                    style={{
                                        display: 'flex',
                                        alignItems: 'flex-start',
                                        justifyContent: 'space-between',
                                        gap: Dimensions.Space12,
                                    }}
                                >
                                    <Text
                                        weight='bold'
                                        style={{
                                            paddingTop: Dimensions.Space8,
                                            whiteSpace: 'nowrap',
                                            minWidth: '140px',
                                        }}
                                    >
                                        Select OCGA by Type
                                    </Text>
                                    <div style={{ flex: 1 }}>
                                        <Controller
                                            name='hardwareVersionSelection'
                                            control={control}
                                            render={({ field }) => (
                                                <Dropdown<HardwareOption, string>
                                                    placeholder='Select OCGA...'
                                                    value={hardwareEnvironmentOptions.find(
                                                        (opt) => opt.value === field.value,
                                                    )}
                                                    options={hardwareEnvironmentOptions}
                                                    onChange={(selectedOption) => {
                                                        if (!playing && overrideMethod !== 'hardware') {
                                                            setOverrideMethod('hardware');
                                                            setValue('ocgaSteeringOverride', '');
                                                        }
                                                        field.onChange(selectedOption?.value);
                                                    }}
                                                    disabled={playing}
                                                    loading={isLoadingHardwareVersions}
                                                    getOptionSubtitle={(option) => option?.subtitle}
                                                    DropdownListItemLabel={CustomDropdownListItemLabel}
                                                />
                                            )}
                                        />
                                    </div>
                                </div>
                            </Paper>
                        )}

                        <Paper
                            elevation={0}
                            style={{
                                padding: Dimensions.Space12,
                                cursor: 'pointer',
                                borderRadius: 'var(--hawkins-dimensions-border-radius-4)',
                                border: '1px solid var(--hawkins-theme-border-subtle)',
                                background:
                                    overrideMethod === 'uuid'
                                        ? 'var(--hawkins-theme-surface-highlight)'
                                        : 'transparent',
                                opacity: overrideMethod === 'uuid' ? 1 : 0.5,
                            }}
                            onClick={() => {
                                if (!playing) {
                                    setOverrideMethod('uuid');
                                    setValue('hardwareVersionSelection', undefined);
                                }
                            }}
                        >
                            <div
                                style={{
                                    display: 'flex',
                                    alignItems: 'flex-start',
                                    justifyContent: 'space-between',
                                    gap: Dimensions.Space12,
                                }}
                            >
                                <Text
                                    weight='bold'
                                    style={{ paddingTop: Dimensions.Space8, whiteSpace: 'nowrap', minWidth: '140px' }}
                                >
                                    Override by UUID
                                </Text>
                                <div style={{ flex: 1 }}>
                                    <Popover open={isPopoverOpen} onToggle={onToggle} width='target' interactive>
                                        <Popover.Trigger>
                                            <Input
                                                placeholder='********-****-****-****-***********'
                                                value={currentOcgaSteering || ''}
                                                onChange={(e) =>
                                                    setValue('ocgaSteeringOverride', e.target.value.trim())
                                                }
                                                onKeyDown={(e) => {
                                                    if (e.key === 'Enter') {
                                                        setPopoverOpen(false);
                                                        onSubmit();
                                                    }
                                                }}
                                                onFocus={() => {
                                                    if (!playing && overrideMethod !== 'uuid') {
                                                        setOverrideMethod('uuid');
                                                        setValue('hardwareVersionSelection', undefined);
                                                    }
                                                }}
                                                validationMessage={errors.ocgaSteeringOverride?.message}
                                                validationStatus={errors.ocgaSteeringOverride ? 'error' : undefined}
                                                fullWidth
                                                autoComplete='off'
                                                disabled={playing}
                                            />
                                        </Popover.Trigger>
                                        <Popover.Content>
                                            {overrideHistory.length > 0 && (
                                                <div
                                                    style={{
                                                        display: 'flex',
                                                        flexDirection: 'column',
                                                        padding: Dimensions.Space8,
                                                        backgroundColor: 'var(--hawkins-theme-surface-raised)',
                                                        borderRadius: 'var(--hawkins-dimensions-border-radius-4)',
                                                        minWidth: '200px',
                                                    }}
                                                >
                                                    <Text
                                                        variant='label'
                                                        colorVariant='faded'
                                                        style={{ padding: Dimensions.Space4 }}
                                                    >
                                                        Override History
                                                    </Text>
                                                    {overrideHistory.map((uuid) => (
                                                        <button
                                                            key={uuid}
                                                            type='button'
                                                            style={{
                                                                padding: `${Dimensions.Space8}px ${Dimensions.Space12}px`,
                                                                cursor: 'pointer',
                                                                borderRadius:
                                                                    'var(--hawkins-dimensions-border-radius-4)',
                                                                border: 'none',
                                                                background: 'transparent',
                                                                textAlign: 'left',
                                                                width: '100%',
                                                            }}
                                                            onClick={() => {
                                                                setValue('ocgaSteeringOverride', uuid);
                                                                setPopoverOpen(false);
                                                            }}
                                                            onMouseEnter={(e) => {
                                                                e.currentTarget.style.backgroundColor =
                                                                    'var(--hawkins-theme-surface-highlight)';
                                                            }}
                                                            onMouseLeave={(e) => {
                                                                e.currentTarget.style.backgroundColor = 'transparent';
                                                            }}
                                                        >
                                                            <Text variant='body'>{uuid}</Text>
                                                        </button>
                                                    ))}
                                                </div>
                                            )}
                                        </Popover.Content>
                                    </Popover>
                                </div>
                            </div>
                        </Paper>
                    </Stack>
                )}
            </Stack>

            <Stack gap={Dimensions.Space12}>
                <Toggle
                    disabled={playing}
                    checked={overrideOcgaVideoSettings}
                    label='Override OCGA Video Settings'
                    name='OCGA Video Settings Override Toggle'
                    onChange={(_event, newChecked) => {
                        setOverrideOcgaVideoSettings(newChecked);
                        if (newChecked) {
                            applyDefaults();
                        } else {
                            setValue('resolutionOverride', undefined);
                            setValue('fpsOverride', undefined);
                        }
                    }}
                />
                {overrideOcgaVideoSettings && (
                    <Stack gap={Dimensions.Space12}>
                        <Dropdown
                            label='Resolution'
                            clearable
                            value={resolutionOptionValue}
                            options={VIDEO_RESOLUTION_OPTIONS}
                            onChange={(selectedOption: DropdownOption<number> | null) =>
                                setValue('resolutionOverride', selectedOption?.value)
                            }
                            disabled={playing}
                        />
                        <Dropdown
                            label='FPS'
                            clearable
                            value={fpsOptionValue}
                            options={TEST_FPS_OPTIONS}
                            onChange={(selectedOption: DropdownOption<number> | null) =>
                                setValue('fpsOverride', selectedOption?.value)
                            }
                            disabled={playing}
                        />
                    </Stack>
                )}
            </Stack>

            {overrideOcgaVideoSettings && (
                <div style={{ display: 'flex', justifyContent: 'flex-start' }}>
                    <Button
                        icon={IconRefresh}
                        onClick={applyDefaults}
                        disabled={playing}
                        variant='tertiary'
                        compact
                        style={{ gap: '6px' }}
                    >
                        Reset to Default
                    </Button>
                </div>
            )}

            {showFooter && (
                <ButtonGroup justifyContent='flex-end' style={{ marginTop: Dimensions.Space8 }}>
                    {onCancel && (
                        <Button onClick={playing ? onCancel : handleSaveAndClose} variant='secondary'>
                            {playing ? 'Close' : 'Cancel'}
                        </Button>
                    )}
                    <Button onClick={onSubmit} disabled={playing || Boolean(errors.ocgaSteeringOverride)}>
                        Save
                    </Button>
                </ButtonGroup>
            )}
        </Stack>
    );
});
