import {
    SOFTWARE_GAME_DEV_POOL_VALUES,
    type SessionSettings,
    type SoftwareGameDevPoolValue,
} from '@gsm-app/routes/Play/components/SessionSettingsModal/SessionSettingsModal';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useNgpConfig } from './useNgpConfig';
import { DEFAULT_TEST_RESOLUTION, DEFAULT_TEST_FPS } from '@gsm-app/constants';

export enum SessionSettingType {
    ocgaUUID = 'ocgaUUID',
    resolution = 'resolution',
    fps = 'fps',
    hardwareVersion = 'hardwareVersion',
    softwareGameDevPool = 'softwareGameDevPool',
}

const SETTING_KEYS = Object.values(SessionSettingType);
const VALID_RESOLUTION_VALUES = [720, 1080];
const VALID_FPS_VALUES = [24, 30, 60];

export const useSessionSettings = (gameId?: string) => {
    const [searchParams, setSearchParams] = useSearchParams();
    const [sessionSettings, setSessionSettings] = useState<SessionSettings>({});
    const { data: ngpConfig } = useNgpConfig(gameId);

    useEffect(() => {
        const settingsOverrides: SessionSettings = {};
        for (const [key, _value] of searchParams) {
            if (SETTING_KEYS.includes(key as SessionSettingType) && searchParams.get(key) !== '') {
                switch (key) {
                    case SessionSettingType.ocgaUUID: {
                        const ocgaUUID = searchParams.get(SessionSettingType.ocgaUUID);
                        if (ocgaUUID) {
                            settingsOverrides.ocgaSteeringOverride = ocgaUUID;
                        }
                        break;
                    }
                    case SessionSettingType.resolution: {
                        try {
                            const resolutionOverride = Number(searchParams.get(SessionSettingType.resolution));
                            if (VALID_RESOLUTION_VALUES.includes(resolutionOverride)) {
                                settingsOverrides.resolutionOverride = resolutionOverride;
                            } else {
                                console.log(`Invalid resolution: ${resolutionOverride}`);
                            }
                        } catch (error) {
                            console.error(
                                `Invalid resolution override: ${searchParams.get(SessionSettingType.resolution)}`,
                            );
                        }
                        break;
                    }
                    case SessionSettingType.fps: {
                        try {
                            const fpsOverride = Number(searchParams.get(SessionSettingType.fps));
                            if (VALID_FPS_VALUES.includes(fpsOverride)) {
                                settingsOverrides.fpsOverride = fpsOverride;
                            } else {
                                console.log(`Invalid FPS: ${fpsOverride}`);
                            }
                        } catch (error) {
                            console.error(`Invalid FPS override: ${searchParams.get(SessionSettingType.fps)}`);
                        }
                        break;
                    }
                    case SessionSettingType.hardwareVersion: {
                        const hardwareVersion = searchParams.get(SessionSettingType.hardwareVersion);
                        if (hardwareVersion) {
                            settingsOverrides.hardwareVersionSelection = hardwareVersion;
                        }
                        break;
                    }
                    case SessionSettingType.softwareGameDevPool: {
                        const pool = searchParams.get(SessionSettingType.softwareGameDevPool);
                        if (pool && SOFTWARE_GAME_DEV_POOL_VALUES.includes(pool as SoftwareGameDevPoolValue)) {
                            settingsOverrides.softwareGameDevPool = pool as SoftwareGameDevPoolValue;
                        }
                        break;
                    }
                    default:
                        break;
                }
            }
        }

        // OCGA steering: at most one of UUID, hardware selection, or software pool
        let coerced: SessionSettings = { ...settingsOverrides };
        if (coerced.ocgaSteeringOverride && (coerced.hardwareVersionSelection || coerced.softwareGameDevPool)) {
            const { hardwareVersionSelection: _hw, softwareGameDevPool: _sw, ...rest } = coerced;
            coerced = rest;
        } else if (coerced.hardwareVersionSelection && coerced.softwareGameDevPool) {
            const { softwareGameDevPool: _sw, ...rest } = coerced;
            coerced = rest;
        }

        setSessionSettings(coerced);
    }, [searchParams]);

    const onSetSessionSettings = useCallback(
        (settings: SessionSettings) => {
            const newSearchParams = new URLSearchParams(searchParams);

            // Handle OCGA UUID
            if (settings?.ocgaSteeringOverride) {
                newSearchParams.set('ocgaUUID', settings.ocgaSteeringOverride);
            } else {
                newSearchParams.delete('ocgaUUID');
            }

            // Handle resolution
            if (settings?.resolutionOverride) {
                newSearchParams.set('resolution', String(settings.resolutionOverride));
            } else {
                newSearchParams.delete('resolution');
            }

            // Handle FPS
            if (settings?.fpsOverride) {
                newSearchParams.set('fps', String(settings.fpsOverride));
            } else {
                newSearchParams.delete('fps');
            }

            // Handle hardware version selection
            if (settings?.hardwareVersionSelection) {
                newSearchParams.set('hardwareVersion', settings.hardwareVersionSelection);
            } else {
                newSearchParams.delete('hardwareVersion');
            }

            if (settings?.softwareGameDevPool) {
                newSearchParams.set(SessionSettingType.softwareGameDevPool, settings.softwareGameDevPool);
            } else {
                newSearchParams.delete(SessionSettingType.softwareGameDevPool);
            }

            setSearchParams(newSearchParams);
            setSessionSettings(settings);
        },
        [searchParams, setSearchParams],
    );

    const clearUrlParamKeys = (keysToClear: Array<string>) => {
        const newSearchParams = new URLSearchParams(searchParams);
        keysToClear.forEach((key) => newSearchParams.delete(key));
        setSearchParams(newSearchParams);
    };

    const clearSessionSettings = () => {
        clearUrlParamKeys(SETTING_KEYS);
        onSetSessionSettings({});
    };

    // Resolved values: override -> game default -> system default
    const resolution = useMemo(() => {
        return sessionSettings.resolutionOverride ?? ngpConfig?.resolution ?? DEFAULT_TEST_RESOLUTION;
    }, [sessionSettings.resolutionOverride, ngpConfig?.resolution]);

    const fps = useMemo(() => {
        return sessionSettings.fpsOverride ?? ngpConfig?.fps ?? DEFAULT_TEST_FPS;
    }, [sessionSettings.fpsOverride, ngpConfig?.fps]);

    return {
        sessionSettings,
        setSessionSettings: onSetSessionSettings,
        clearSessionSettings,
        resolution,
        fps,
    };
};
