import type { ErrorMessage } from '@gsm-app/models/ErrorMessage';
import type { Message } from '@gsm-app/models/Message';
import { useStateDebounced } from '@gsm-common/hooks/useStateDebounced';
import { InteropValue, MessageType } from '@ocga/proto';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useTelemetry } from './useTelemetry';

type UseControllerLogsProps = {
    sessionId?: string | undefined;
    disabled?: boolean;
};

type Log = {
    MessageType: number;
    Timestamp: string;
    Message: {
        LogEvent?: {
            Fields?: { [key: string]: InteropValue.Value };
            Message?: string;
        };
    };
};

const EVENT_TYPE_FIELD = 'event_most_derived_type';

/**
 * Extract a display string from an InteropValue.Value
 */
const getValueString = (value: InteropValue.Value | undefined): string | undefined => {
    if (!value) return undefined;
    switch (value.Kind) {
        case InteropValue.Kind.String:
            return value.String;
        case InteropValue.Kind.Int:
            return String(value.Int);
        case InteropValue.Kind.Float:
            return String(value.Float);
        case InteropValue.Kind.Bool:
            return String(value.Bool);
        case InteropValue.Kind.Map:
            if (value.Map && Object.keys(value.Map).length > 0) {
                return formatMapValue(value.Map);
            }
            return undefined;
        default:
            return undefined;
    }
};

/**
 * Format a Map value as a JSON-like string
 */
const formatMapValue = (map: { [key: string]: InteropValue.Value }): string => {
    const parts: string[] = [];
    for (const [key, value] of Object.entries(map)) {
        const strValue = getValueString(value);
        if (strValue !== undefined) {
            parts.push(`${key}:${strValue}`);
        }
    }
    return `{${parts.join(', ')}}`;
};

/**
 * Format fields as key=value pairs
 */
const formatFields = (fields: { [key: string]: InteropValue.Value }): string => {
    const parts: string[] = [];

    for (const [key, value] of Object.entries(fields)) {
        // Skip EVENT_TYPE_FIELD since it's already shown as the prefix
        if (key === EVENT_TYPE_FIELD) continue;
        const strValue = getValueString(value);
        if (strValue) {
            parts.push(`${key}=${strValue}`);
        }
    }

    return parts.join(', ');
};

export const formatControllerLog = (message: Message<Log>): undefined | string[] => {
    if (message.data?.MessageType !== MessageType.MessageType.LogEvent) {
        return undefined;
    }

    const logEvent = message?.data?.Message?.LogEvent;
    const fields = logEvent?.Fields || {};
    const logMessage = logEvent?.Message;

    let msg: string | undefined;

    // Get event type
    const eventType = getValueString(fields[EVENT_TYPE_FIELD]);

    // Use log message if present, otherwise format from fields
    if (logMessage) {
        msg = logMessage;
    } else if (eventType) {
        const fieldStr = formatFields(fields);
        msg = fieldStr ? `${eventType}: ${fieldStr}` : eventType;
    }

    let timestamp = message?.data?.Timestamp;

    if (!msg || !timestamp) {
        return undefined;
    }

    timestamp = new Date(Number(timestamp.slice(0, 10)) * 1000).toISOString();

    return [timestamp, msg];
};

export const useControllerLogs = ({ disabled, sessionId }: UseControllerLogsProps = {}) => {
    const [error, setError] = useState<ErrorMessage | undefined>();
    const [logs, setLogs] = useStateDebounced<string[][]>([], 200, { maxWait: 2000, leading: true });
    const [streamComplete, setStreamComplete] = useState(false);
    const hasReceivedDataRef = useRef(false);
    const pendingLogs = useRef<string[][]>([]);

    const onMessage = useCallback(
        (message: Message<Log>) => {
            hasReceivedDataRef.current = true;
            const log = formatControllerLog(message);
            if (log) {
                pendingLogs.current.push(log);
                setLogs((prev) => {
                    const newLogs = [...prev, ...pendingLogs.current];
                    pendingLogs.current = [];
                    return newLogs;
                });
            }
        },
        [setLogs],
    );

    // Clear state on new session
    useEffect(() => {
        setLogs([]);
        setError(undefined);
        setStreamComplete(false);
        hasReceivedDataRef.current = false;
        pendingLogs.current = [];
    }, [setLogs, sessionId]);

    const onError = useCallback(({ message }: any) => {
        setError(message);
    }, []);

    const onComplete = useCallback(() => {
        setStreamComplete(true);
        // If stream completed with no data, show error message
        if (!hasReceivedDataRef.current) {
            setError({
                type: 'Error',
                message:
                    'No controller logs available for this session. This may indicate no mobile controller was connected.',
            });
        }
    }, []);

    useTelemetry<Log>({
        sessionId,
        disabled,
        context: 'controller',
        onMessage,
        onError,
        onComplete,
    });

    // Loading until stream completes, we have data, or there's an error
    const loading = !streamComplete && logs.length === 0 && !error;

    const clearLogs = useCallback(() => {
        setLogs([]);
        pendingLogs.current = [];
    }, [setLogs]);

    return {
        error,
        data: logs,
        loading,
        clearLogs,
    };
};
