import screen01 from './assets/gameplay-placeholders/screen-01.png';
import screen02 from './assets/gameplay-placeholders/screen-02.png';
import screen03 from './assets/gameplay-placeholders/screen-03.png';
import screen04 from './assets/gameplay-placeholders/screen-04.png';
import screen05 from './assets/gameplay-placeholders/screen-05.png';
import screen06 from './assets/gameplay-placeholders/screen-06.png';
import screen07 from './assets/gameplay-placeholders/screen-07.png';
import screen08 from './assets/gameplay-placeholders/screen-08.png';
import screen09 from './assets/gameplay-placeholders/screen-09.png';
import screen10 from './assets/gameplay-placeholders/screen-10.png';
import screen11 from './assets/gameplay-placeholders/screen-11.png';

/**
 * Shared placeholder art for mock-play-mode's "gameplay" — reused both by the video-area crossfade
 * (`MockGameplayPlaceholder`) and by the mock screenshot capture (`useMockPeriodicScreenshots`), so
 * a "screenshot" taken at a given moment shows the exact frame that was on-screen at that moment.
 */
export const MOCK_GAMEPLAY_SCREENS = [
    screen01,
    screen02,
    screen03,
    screen04,
    screen05,
    screen06,
    screen07,
    screen08,
    screen09,
    screen10,
    screen11,
];

export const MOCK_GAMEPLAY_ROTATE_INTERVAL_MS = 3500;

/**
 * Deterministic frame lookup by wall-clock time — two independent components calling this with the
 * same `timestampMs` always agree on the same image, with no shared React state required.
 */
export const getMockScreenAt = (timestampMs: number): string => {
    const index = Math.floor(timestampMs / MOCK_GAMEPLAY_ROTATE_INTERVAL_MS) % MOCK_GAMEPLAY_SCREENS.length;
    return MOCK_GAMEPLAY_SCREENS[index];
};
