import { useTelemetryMessageTypesEvents } from '@gsm-app/hooks/useTelemetryHostnameIpLogs';
import { Dimensions } from '@hawkins/variables';
import * as OcgaProto from '@ocga/proto';
import { Button, Stack, Text } from '@hawkins/components';

import {
    AllCommunityModule,
    type ColDef,
    type ColGroupDef,
    ColumnsToolPanelModule,
    FiltersToolPanelModule,
    MenuModule,
    SetFilterModule,
    SideBarModule,
    TableNext,
} from '@hawkins/table-next';
import { useCallback, useMemo } from 'react';
import { PAGINATION_OPTIONS, PAGINATION_PAGE_SIZE } from '@gsm-app/constants';

export interface HostConnectionEventMessage {
    hostname: string;
    ipAddr: string;
    port: number;
    internal?: boolean;
}

export type NetworkActivityTableProps = {
    gameId?: number | undefined;
    sessionId: string | undefined
};

const NetworkActivityTable = (props: NetworkActivityTableProps) => {
    const { sessionId, gameId } = props;
    const { logs, isFetching, lastFetch, refetch } = useTelemetryMessageTypesEvents(sessionId, [OcgaProto.MessageType.MessageType.HostConnectionEvent]);

    const modules = useMemo(
        () => [
            AllCommunityModule,
            SetFilterModule,
            MenuModule,
            SideBarModule,
            ColumnsToolPanelModule,
            FiltersToolPanelModule,
        ],
        [],
    );

    const defaultColDef = useMemo<ColDef>(() => {
        return {
            editable: false,
            filter: true,
            floatingFilter: true,
            minWidth: 100,
            resizable: true,
            sortable: true,
        };
    }, []);

    const autoGroupColumnDef = useMemo<ColDef>(() => {
        return {
            cellRendererParams: {
                checkbox: false,
                suppressCount: false,
            },
            headerName: 'Group',
            menuTabs: [],
            minWidth: 250,
        };
    }, []);

    const onRefetch = useCallback(() => {
        refetch();
    }, [refetch]);

    const columnDefs = useMemo<(ColDef<HostConnectionEventMessage> | ColGroupDef<HostConnectionEventMessage>)[]>(() => {
        return [
            {
                field: 'hostname',
                headerName: 'Hostname',
                filter: 'agTextColumnFilter',
                flex: 1,
            },
            {
                field: 'ipAddr',
                headerName: 'IP Address',
                filter: 'agTextColumnFilter',
            },
            {
                field: 'port',
                headerName: 'Port',
                filter: 'agNumberColumnFilter',
            }
        ];
    }, []);
    const data = useMemo(() => {
        return logs.map((log) => {
            return {
                hostname: log.Hostname,
                ipAddr: log.IPAddr,
                port: log.Port,
            };
        });
    }, [logs]);

    return (
        <div style={{ padding: Dimensions.Space24 }}>
            <Stack orientation='horizontal' layout={{ display: 'flex', justifyContent: 'end' }} gap={Dimensions.Space8} style={{ marginBottom: Dimensions.Space8 }}>
                {lastFetch > 0 && (
                    <Stack>
                        <Text level={0} variant='label' colorVariant='faded'>Last checked</Text>
                        <Text level={0} variant='label' colorVariant='faded'>{
                            new Date(lastFetch).toLocaleTimeString()
                        }</Text>
                    </Stack>
                )}
                <Button compact variant='secondary' onClick={onRefetch} disabled={!sessionId} executing={isFetching}>
                    Refresh
                </Button>

            </Stack>
            {
                logs ? (
                    <div style={{ height: Dimensions.Size448, width: '100%' }}>
                        <TableNext<HostConnectionEventMessage>
                            animateRows={true}
                            loading={isFetching}
                            autoGroupColumnDef={autoGroupColumnDef}
                            columnDefs={columnDefs}
                            enableCellTextSelection={true}
                            ensureDomOrder={true}
                            defaultColDef={defaultColDef}
                            groupDefaultExpanded={1}
                            modules={modules}
                            noRowsOverlayComponent={() => <Text>No data</Text>}
                            pagination={true}
                            paginationPageSize={PAGINATION_PAGE_SIZE}
                            paginationPageSizeSelector={PAGINATION_OPTIONS}
                            rowData={data}
                            style={{ height: '100%', width: '100%' }}
                        />
                    </div>
                ) : null
            }
        </div>
    )
};

export default NetworkActivityTable;
