import { useModal } from '@gsm-app/providers/ModalProvider';
import { type SopAccountType, useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { IconCheckmark, IconPencil, IconTrashCan } from '@hawkins/assets';
import { Button, Heading, type ListItemProps, MenuItem, Text } from '@hawkins/components';
import clsx from 'clsx';
import styles from './SopAccountDropdown.module.css';

export type SopAccountDropdownItemProps = {
    disableActions?: boolean;
} & ListItemProps<SopAccountType>;

export const SopAccountDropdownItem = ({
    classes,
    onSelected,
    option,
    index,
    selectedIndex,
    selectedOptionsIds,
    disableActions,
}: SopAccountDropdownItemProps) => {
    const { showModal } = useModal();
    const { savedAccounts, setSavedAccounts, selectedAccount, setSelectedAccount } = useSopAccounts();

    const isSelected = selectedOptionsIds && selectedOptionsIds.has(option.value);
    const isHovered = index === selectedIndex;
    const computedDropdownClasses = clsx(classes?.listItemContainer, {
        hovered: isHovered,
        selected: isSelected,
    });

    return (
        <MenuItem
            classes={{ root: computedDropdownClasses }}
            component='div'
            label={
                <div className={styles.listItem}>
                    <div className={styles.checkmarkContainer}>
                        {isSelected && <IconCheckmark size='small' className={styles.checkmark} />}
                    </div>
                    <Text className={styles.label}>{option.label}</Text>
                    {!disableActions && (
                        <>
                            <Button
                                icon={IconPencil}
                                onClick={() => showModal('sopAccount', { edit: option.value, pin: option.pin })}
                                variant='icon'
                                className={styles.editButton}
                                compact
                            >
                                Edit Account
                            </Button>
                            <Button
                                icon={IconTrashCan}
                                onClick={(e) => {
                                    e.preventDefault();
                                    e.stopPropagation();
                                    if (option.value === selectedAccount?.value) {
                                        setSelectedAccount(undefined);
                                    }
                                    setSavedAccounts([
                                        ...savedAccounts.filter((sop) => {
                                            return sop.value !== option.value;
                                        }),
                                    ]);
                                }}
                                variant='icon'
                                className={styles.deleteButton}
                                compact
                            >
                                Delete Account
                            </Button>
                        </>
                    )}
                </div>
            }
            onClick={() =>
                onSelected({
                    option: option,
                    remove: isSelected,
                })
            }
            role='option'
            selected={!!isSelected}
        />
    );
};

export const SopAccountDropdownFooter = () => {
    const { showModal } = useModal();

    return (
        <div className={styles.addAccountFooter}>
            <Button onClick={() => showModal('sopAccount')} variant='secondary' compact>
                Add Test Account
            </Button>
        </div>
    );
};

export const SopAccountDropdownEmpty = () => {
    const { showModal } = useModal();

    return (
        <div className={styles.emptyStateContainer}>
            <img src='/user.png' className={styles.userImage} />
            <Heading level={1}>No Saved Test Account</Heading>
            <Text>Add a test account below to get started</Text>
            <Button
                className={styles.emptyStateAddAccountButton}
                onClick={() => showModal('sopAccount')}
                variant='secondary'
            >
                Add Test Account
            </Button>
        </div>
    );
};
