import { type ScaleFn, TimeSeries, XYGridLines } from '@netflix-internal/react-vizkit';
import type { ReactNode } from 'react';

export type SessionChartProps = {
    data: any;
    height: number | 'auto';
    defaultHeight?: number;
    brushXExtent?: any[] | null;
    color?: { scale: ScaleFn };
    children?: ReactNode;
};

/**
 * Shared TimeSeries wrapper for all session timeline charts.
 * Enforces consistent axis/grid/endcap styling — pass only what varies per chart.
 */
export const SessionChart = ({ data, height, defaultHeight, brushXExtent, color, children }: SessionChartProps) => (
    <TimeSeries
        data={data}
        width='100%'
        height={height}
        defaultHeight={defaultHeight}
        x={{
            accessor: 'date',
            title: 'Time',
            showTitle: false,
            domain: brushXExtent ?? undefined,
            axis: false,
        }}
        y={{
            accessor: 'value',
            domainMin: 0,
            axis: false,
        }}
        disableGroups={['LineEndcaps', 'CursorLine']}
        color={color}
    >
        <XYGridLines x={false} />
        {children}
    </TimeSeries>
);
