import { classifyLog } from '@gsm-app/components/LogViewer/logTypeUtils';
import { useMemo } from 'react';

export type LogErrorWarningEvent = {
    date: Date;
    // Kept as a union (rather than narrowed to a literal 'error') so this type keeps working
    // unmodified if warnings are ever reintroduced — only the collection below is filtered.
    severity: 'error' | 'warn';
    source: 'game' | 'controller';
    message: string;
};

/** Derives error marker events from game + controller logs, reusing the same classifier used by
 * the log panel's type filter so markers always match what the logs list would highlight as
 * Error. Warnings are intentionally excluded — only 'error'-classified log lines are surfaced in
 * the performance graph markers and the Overview tab's error table. */
export const useLogErrorWarningEvents = (
    gameLogs: string[][] | undefined,
    controllerLogs: string[][] | undefined,
): LogErrorWarningEvent[] => {
    return useMemo(() => {
        const events: LogErrorWarningEvent[] = [];

        const collect = (logs: string[][] | undefined, source: 'game' | 'controller') => {
            for (const log of logs ?? []) {
                const severity = classifyLog(log);
                if (severity !== 'error') continue;
                const time = new Date(log[0]).getTime();
                if (Number.isNaN(time)) continue;
                events.push({ date: new Date(time), severity, source, message: log[1] });
            }
        };

        collect(gameLogs, 'game');
        collect(controllerLogs, 'controller');
        events.sort((a, b) => a.date.getTime() - b.date.getTime());
        return events;
    }, [gameLogs, controllerLogs]);
};
