import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

export const TARGET_INSTANCE_COUNT_KEY = 'targetInstanceCount';
export const DEFAULT_TARGET_INSTANCE_COUNT = 50;

const fetchTargetInstanceCount = async (gameId: string | undefined, resolution?: number): Promise<any> => {
    const params = new URLSearchParams({
        ...(resolution && { resolution: String(resolution) }),
    });
    const queryString = params.toString();
    const response = await fetch(`/api/games/${gameId}/target-instance-count${queryString ? `?${queryString}` : ''}`, {
        headers: {
            'Content-Type': 'application/json',
        },
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(errorData);
    }

    return await response.json();
};

export function useTargetInstanceCount(gameId: string | undefined, resolution?: number) {
    const query = useQuery({
        queryKey: [TARGET_INSTANCE_COUNT_KEY, gameId, resolution],
        meta: {
            pollIntervalMs: 30000,
        },
        enabled: Boolean(gameId),
        queryFn: () => fetchTargetInstanceCount(gameId, resolution),
    });

    const { error, isError } = query;
    useEffect(() => {
        if (isError) {
            console.error(`Error getting target instance count. ${error?.message}`);
        }
    }, [error, isError]);

    return {
        ...query,
        targetInstanceCount: query?.data?.data || DEFAULT_TARGET_INSTANCE_COUNT,
    };
}
