import { useTheme } from '@hawkins/components';

interface TextHighlightProps {
    terms: string[];
    text: string;
}

const escapeRegExp = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const buildHighlightRegex = (terms: string[]): RegExp => {
    const patterns = terms.map((t) => {
        try {
            new RegExp(t);
            return t;
        } catch {
            return escapeRegExp(t);
        }
    });
    try {
        return new RegExp(`(${patterns.join('|')})`, 'gi');
    } catch {
        return new RegExp(`(${terms.map(escapeRegExp).join('|')})`, 'gi');
    }
};

export const TextHighlight = ({ text, terms }: TextHighlightProps) => {
    const hawkinsTheme = useTheme();

    if (terms.length === 0) {
        return <span>{text}</span>;
    }

    const regex = buildHighlightRegex(terms);
    const parts = text.split(regex);
    const matchRegex = new RegExp(regex.source, 'i');

    return (
        <span>
            {parts.map((part, index) =>
                matchRegex.test(part) ? (
                    <span
                        key={index}
                        style={{
                            backgroundColor: hawkinsTheme.ForegroundSystemWarning,
                            color: hawkinsTheme.ForegroundInverse,
                        }}
                    >
                        {part}
                    </span>
                ) : (
                    part
                ),
            )}
        </span>
    );
};
