import { useVizContext } from '@netflix-internal/react-vizkit';
import { type MutableRefObject, useEffect } from 'react';

export type VizBridgeRef = {
    toggle: (key: string) => void;
};

/**
 * Renders nothing. Lives inside a TimeSeries so it can access VizContext,
 * then writes `toggleVisibleDataset` into the provided ref so parent components
 * outside the chart tree can trigger line visibility toggles.
 */
export const VizBridge = ({ bridgeRef }: { bridgeRef: MutableRefObject<VizBridgeRef | null> }) => {
    const viz = useVizContext();

    useEffect(() => {
        bridgeRef.current = {
            toggle: (key: string) => viz.toggleVisibleDataset(key),
        };
        return () => {
            bridgeRef.current = null;
        };
    });

    return null;
};
