import { ansiLogFormatter } from '@gsm-app/utils/ansi';
import { download } from '@gsm-common/utils/file/download';
import { toCSV } from '@gsm-common/utils/file/toCSV';
import { toLog } from '@gsm-common/utils/file/toLog';
import { Loader, Text } from '@hawkins/components';
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react';
import styles from './LogViewer.module.css';
import { GameLogsList } from './components/GameLogsList';
import { SearchToolbar } from './components/SearchToolbar';
import { matchesPositive, parseFilterTerms, passesNegative } from './filterUtils';

export interface LogViewerHandle {
    scrollToLog: (index: number) => void;
}

interface LogSettings {
    autoscroll?: boolean;
    relativeTimestamps?: boolean;
    firstOnly?: boolean;
    showCollapsedCount?: boolean;
}

interface LogViewerProps {
    logs: string[][];
    loading: boolean;
    error?: Error | null;
    format?: (s: string, firstOnly: boolean) => string | JSX.Element | JSX.Element[];
    height: number;
    name: string;
    onClearLogs?: () => void;
    /** When true, the internal SearchToolbar is hidden (controlled by an external toolbar) */
    hideToolbar?: boolean;
    /** When provided, overrides the internal filter state */
    externalFilter?: string;
    /** When provided, overrides the internal filterMatchesOnly state */
    externalFilterMatchesOnly?: boolean;
    /** When provided, overrides internal display settings (used when hideToolbar=true) */
    logSettings?: LogSettings;
    /** Text shown when logs are empty and not loading (e.g. before a session starts) */
    idleMessage?: string;
    streamingComplete?: boolean;
    /** Shared playhead position, in seconds from session start. Null when nothing is selected. */
    currentTime?: number | null;
    /** Epoch ms for t=0 (session start), shared with the graph for consistent time matching. */
    sessionStartMs?: number;
    /** Which side last set currentTime — used to only auto-scroll for graph-originated jumps. */
    playheadSource?: 'graph' | 'log' | null;
    /** Called when the user selects a log row (click or Enter), with its time in seconds from session start. */
    onSelectLog?: (seconds: number) => void;
}

const downloadLog = (name: string, logMsgs: string[][]) => download(name, toLog(logMsgs), 'log');
const downloadCSV = (name: string, logMsgs: string[][]) => download(name, toCSV(logMsgs));

export const LogViewer = forwardRef<LogViewerHandle, LogViewerProps>((props, ref) => {
    const {
        name,
        format = ansiLogFormatter,
        height,
        logs,
        loading,
        error,
        onClearLogs,
        hideToolbar = false,
        externalFilter,
        externalFilterMatchesOnly,
        logSettings,
        idleMessage,
        streamingComplete = true,
        currentTime = null,
        sessionStartMs = 0,
        playheadSource = null,
        onSelectLog,
    } = props;

    const [internalAutoscroll, setAutoscroll] = useState<boolean>(true);
    const [internalRelativeTimestamps, setRelativeTimestamps] = useState<boolean>(true);
    const [internalFirstOnly, setFirstOnly] = useState(false);
    const [internalShowCollapsedCount, setShowCollapsedCount] = useState(true);

    // Prefer external settings when provided (used when hideToolbar=true)
    const autoscroll = logSettings?.autoscroll ?? internalAutoscroll;
    const relativeTimestamps = logSettings?.relativeTimestamps ?? internalRelativeTimestamps;
    const firstOnly = logSettings?.firstOnly ?? internalFirstOnly;
    const showCollapsedCount = logSettings?.showCollapsedCount ?? internalShowCollapsedCount;
    const [filterMatchesOnly, setFilterMatchesOnly] = useState(false);
    const [internalFilter, setInternalFilter] = useState<string>('');
    const listRef = useRef<any>();

    const [searchIndex, setSearchIndex] = useState(-1);

    // Prefer external control when provided
    const filter = externalFilter !== undefined ? externalFilter : internalFilter;
    const activeFilterMatchesOnly =
        externalFilterMatchesOnly !== undefined ? externalFilterMatchesOnly : filterMatchesOnly;

    const { visibleLogs, searchIndices, hiddenLogsCount } = useMemo(() => {
        if (!filter.trim()) {
            return { visibleLogs: logs, searchIndices: [], hiddenLogsCount: 0 };
        }

        const parsed = parseFilterTerms(filter);
        const filtered = parsed.negative.length > 0 ? logs.filter((logMsg) => passesNegative(logMsg[1], parsed)) : logs;

        const finalFiltered =
            activeFilterMatchesOnly && parsed.positive.length > 0
                ? filtered.filter((logMsg) => matchesPositive(logMsg[1], parsed))
                : filtered;

        const indices: number[] = [];
        if (parsed.positive.length > 0) {
            finalFiltered.forEach((logMsg, index) => {
                if (matchesPositive(logMsg[1], parsed)) {
                    indices.push(index);
                }
            });
        }

        return {
            visibleLogs: finalFiltered,
            searchIndices: indices,
            hiddenLogsCount: logs.length - filtered.length,
        };
    }, [logs, filter, activeFilterMatchesOnly]);

    // Expose scrollToLog so parent toolbar can drive navigation
    useImperativeHandle(ref, () => ({
        scrollToLog: (index: number) => {
            listRef.current?.scrollToLog(index);
        },
    }));

    const handleDownloadLog = useCallback(() => downloadLog(name, logs), [name, logs]);
    const handleDownloadCSV = useCallback(() => downloadCSV(name, logs), [name, logs]);

    const onSearchPrevious = useCallback(() => {
        if (!listRef?.current) return;
        const prev = searchIndex === -1 || searchIndex === 0 ? searchIndices.length - 1 : searchIndex - 1;
        setSearchIndex(prev);
        setAutoscroll(false);
        listRef.current?.scrollToLog(searchIndices[prev]);
    }, [searchIndex, searchIndices]);

    // A graph click is about to scroll the list to a specific row — same as manual search
    // navigation, that should win over "stick to the bottom" live-tail autoscroll.
    useEffect(() => {
        if (currentTime !== null && playheadSource === 'graph') {
            setAutoscroll(false);
        }
    }, [currentTime, playheadSource]);

    const onSearchNext = useCallback(() => {
        if (!listRef?.current) return;
        const next = searchIndex === -1 || searchIndex === searchIndices.length - 1 ? 0 : searchIndex + 1;
        setSearchIndex(next);
        setAutoscroll(false);
        listRef.current?.scrollToLog(searchIndices[next]);
    }, [searchIndex, searchIndices]);

    if (height < 100) {
        return null;
    }

    const isStreaming = !loading && !streamingComplete && logs.length > 0;

    return (
        <div className={styles.feedContainer} style={{ height }}>
            {!hideToolbar && (
                <SearchToolbar
                    autoscroll={autoscroll}
                    relativeTimestamps={relativeTimestamps}
                    filter={filter}
                    firstOnly={firstOnly}
                    loading={loading}
                    searchMatchesCount={searchIndices.length}
                    hiddenLogsCount={hiddenLogsCount}
                    searchIndex={searchIndex}
                    onSubmit={onSearchNext}
                    onClear={() => {
                        setSearchIndex(-1);
                    }}
                    onSearchPrevious={onSearchPrevious}
                    onSearchNext={onSearchNext}
                    streamingComplete={streamingComplete}
                    onClearLogs={onClearLogs}
                    onDownloadCSV={handleDownloadCSV}
                    onDownloadLog={handleDownloadLog}
                    setAutoscroll={setAutoscroll}
                    setRelativeTimestamps={setRelativeTimestamps}
                    setFilter={(newFilter) => {
                        if (newFilter.trim() === '') {
                            setSearchIndex(-1);
                            setFilterMatchesOnly(false);
                        }
                        setInternalFilter(newFilter);
                    }}
                    setFirstOnly={setFirstOnly}
                    showCollapsedCount={showCollapsedCount}
                    setShowCollapsedCount={setShowCollapsedCount}
                    filterMatchesOnly={filterMatchesOnly}
                    setFilterMatchesOnly={setFilterMatchesOnly}
                />
            )}
            <div style={{ position: 'relative', flex: 1 }}>
                {isStreaming && (
                    <div className={styles.loadingOverlay}>
                        <Loader />
                        <Text colorVariant='faded'>Loading game logs...</Text>
                    </div>
                )}
                <GameLogsList
                    ref={listRef}
                    format={format}
                    filter={filter}
                    logs={visibleLogs}
                    error={error}
                    loading={loading}
                    searchIndex={searchIndices[searchIndex]}
                    firstOnly={firstOnly}
                    height={height}
                    autoscroll={autoscroll}
                    relativeTimestamps={relativeTimestamps}
                    showCollapsedCount={showCollapsedCount}
                    toolbarOffset={hideToolbar ? 0 : 40}
                    idleMessage={idleMessage}
                    currentTime={currentTime}
                    sessionStartMs={sessionStartMs}
                    playheadSource={playheadSource}
                    onSelectLog={onSelectLog}
                />
            </div>
        </div>
    );
});
