import { useSessionTimelineData } from '@ncgt/session-timeline';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { SessionAvgTile } from './SessionAvgTile';
import styles from './SessionTimelineChart.module.css';

export type SessionTimelineSummaryCardProps = {
    hideInstanceCount?: boolean;
};

const TILE_KEYS = ['percentAllottedGPU', 'percentAllottedCPU', 'percentAllottedRAM', 'percentAllottedVRAM'];

const TILE_LABELS: Record<string, string> = {
    percentAllottedGPU: 'GPU',
    percentAllottedCPU: 'CPU',
    percentAllottedRAM: 'RAM',
    percentAllottedVRAM: 'VRAM',
};

const TILE_UNITS: Record<string, string> = {
    percentAllottedGPU: '%',
    percentAllottedCPU: '%',
    percentAllottedRAM: '%',
    percentAllottedVRAM: '%',
};

export const SessionTimelineSummaryCard = ({ hideInstanceCount = false }: SessionTimelineSummaryCardProps) => {
    const { datasets } = useSessionTimelineData();

    const averages: Record<string, { count: number; value: number }> = {};

    if (datasets?.[ChartType.STATS]) {
        (datasets[ChartType.STATS] as any[]).forEach((point: any) => {
            if (!TILE_KEYS.includes(point.lineKey)) return;
            if (!averages[point.lineKey]) {
                averages[point.lineKey] = { count: 0, value: 0 };
            }
            averages[point.lineKey].count += 1;
            averages[point.lineKey].value += point.value;
        });
    }

    const visibleKeys = TILE_KEYS.filter(
        (key) => !(hideInstanceCount && key === 'percentAllottedVRAM') && averages[key],
    );

    if (visibleKeys.length === 0) return null;

    return (
        <div className={styles.sessionAvgCard}>
            <div className={styles.sessionAvgHeader}>
                <span className={styles.sessionAvgTitle}>Session Average</span>
            </div>
            <div className={styles.sessionAvgTiles}>
                {visibleKeys.map((key) => {
                    const avg = averages[key].value / averages[key].count;
                    return (
                        <SessionAvgTile
                            key={key}
                            label={TILE_LABELS[key]}
                            value={avg}
                            unit={TILE_UNITS[key]}
                            isAlert={avg > 100}
                        />
                    );
                })}
            </div>
        </div>
    );
};
