import type { ErrorMessage } from '@gsm-app/models/ErrorMessage';
import { download } from '@gsm-common/utils/file/download';
import { toCSV } from '@gsm-common/utils/file/toCSV';
import { toLog } from '@gsm-common/utils/file/toLog';
import {
    IconArrowLeft,
    IconArrowRight,
    IconBroom,
    IconCaretDown,
    IconCircleExclamationPointFill,
    IconCircleI,
    IconDownload,
    IconFilter,
    IconMagnifyingGlass,
    IconPanelCardsHorizontal,
    IconPanelCardsVertical,
    IconSettings,
    IconSignalWifi,
    IconSquare,
    IconWarningFill,
} from '@hawkins/assets';
import {
    Button,
    ButtonGroup,
    Checkbox,
    Input,
    Menu,
    MenuGroup,
    MenuItem,
    Text,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import useDimensions from 'react-cool-dimensions';
import { Panel, PanelGroup, PanelResizeHandle } from 'react-resizable-panels';
import { LogViewer, type LogViewerHandle } from '../../LogViewer';
import { matchesPositive, parseFilterTerms, passesNegative } from '../../filterUtils';
import { ALL_LOG_TYPES, LOG_TYPE_ICON_COLOR, LOG_TYPE_LABELS, type LogTypeKey, classifyLog } from '../../logTypeUtils';
import styles from './MultiSourceLogPanel.module.css';

const MIN_LOG_HEIGHT = 300;

type LogView = 'all' | 'game' | 'controller';
export type LogLayoutMode = 'single' | 'split' | 'stacked';

export interface LogSourceData {
    data: string[][];
    loading: boolean;
    error?: ErrorMessage;
    clearLogs: () => void;
    completed?: boolean;
}

export interface MultiSourceLogPanelProps {
    sessionId: string | undefined;
    /** Prefix used for downloaded file names, e.g. `browser_game_logs_${sessionId}` */
    namePrefix: string;
    gameLogs: LogSourceData;
    controllerLogs: LogSourceData;
    idleMessage?: string;
    /** Shows the "x controllers connected" status row — only meaningful for a live session. Default: true */
    showControllerStatusBar?: boolean;
    defaultLogView?: LogView;
    defaultLayoutMode?: LogLayoutMode;
    /** Whether both log streams have finished loading (hides the "still loading" overlay). Default: true */
    streamingComplete?: boolean;
    /** Shared playhead position, in seconds from session start. Omit entirely when there's no graph to sync with. */
    currentTime?: number | null;
    /** Epoch ms for t=0 (session start), shared with the graph for consistent time matching. */
    sessionStartMs?: number;
    /** Which side last set currentTime — used to only auto-scroll for graph-originated jumps. */
    playheadSource?: 'graph' | 'log' | null;
    /** Called when the user selects a log row (click or Enter), with its time in seconds from session start. */
    onSelectLog?: (seconds: number) => void;
}

/** Compute indices of matching lines within a log array */
function computeMatchIndices(logs: string[][], query: string, filterMatchesOnly: boolean): number[] {
    if (!query.trim() || !logs.length) return [];
    const parsed = parseFilterTerms(query);
    if (parsed.positive.length === 0 && parsed.negative.length === 0) return [];

    const source = parsed.negative.length > 0 ? logs.filter((log) => passesNegative(log[1], parsed)) : logs;
    const visible =
        filterMatchesOnly && parsed.positive.length > 0
            ? source.filter((log) => matchesPositive(log[1], parsed))
            : source;

    const indices: number[] = [];
    if (parsed.positive.length > 0) {
        visible.forEach((log, idx) => {
            if (matchesPositive(log[1], parsed)) indices.push(idx);
        });
    }
    return indices;
}

/**
 * A log panel showing Game + Controller log streams with source (All / Game / Controller)
 * and layout (Combined / Split / Stacked) controls, a log-type filter, and cross-pane search.
 * Optionally syncs a shared playhead with an external graph via `currentTime`/`onSelectLog`.
 */
export const MultiSourceLogPanel = ({
    sessionId,
    namePrefix,
    gameLogs,
    controllerLogs,
    idleMessage,
    showControllerStatusBar = true,
    defaultLogView = 'all',
    defaultLayoutMode = 'split',
    streamingComplete = true,
    currentTime = null,
    sessionStartMs = 0,
    playheadSource = null,
    onSelectLog,
}: MultiSourceLogPanelProps) => {
    const { observe: logAreaRef, height: logAreaHeight } = useDimensions<HTMLElement>();

    const [logView, setLogView] = useState<LogView>(defaultLogView);
    const [layoutMode, setLayoutMode] = useState<LogLayoutMode>(defaultLayoutMode);
    const [stackedGamePercent, setStackedGamePercent] = useState(50);
    const [logTypeFilter, setLogTypeFilter] = useState<Set<LogTypeKey>>(new Set(ALL_LOG_TYPES));
    const [searchQuery, setSearchQuery] = useState('');
    const [filterMatchesOnly, setFilterMatchesOnly] = useState(false);
    const [globalSearchIndex, setGlobalSearchIndex] = useState(-1);

    // Shared log display settings — applied to all LogViewer instances
    const [autoscroll, setAutoscroll] = useState(true);
    const [relativeTimestamps, setRelativeTimestamps] = useState(true);
    const [firstOnly, setFirstOnly] = useState(false);
    const [showCollapsedCount, setShowCollapsedCount] = useState(true);

    const gameViewerRef = useRef<LogViewerHandle>(null);
    const controllerViewerRef = useRef<LogViewerHandle>(null);

    const logHeight = useMemo(() => Math.max(logAreaHeight - 1, MIN_LOG_HEIGHT), [logAreaHeight]);

    const gameLoading = !!sessionId && gameLogs.loading;
    const controllerLoading = !!sessionId && controllerLogs.loading;

    const gameLogsError = useMemo(() => (gameLogs.error ? new Error(gameLogs.error.message) : null), [gameLogs.error]);
    const controllerLogsError = useMemo(
        () => (controllerLogs.error ? new Error(controllerLogs.error.message) : null),
        [controllerLogs.error],
    );

    // Timestamp-sorted merge of both log streams for the single-pane combined view.
    // Both arrays use ISO timestamps at index [0], which sort lexicographically.
    const mergedLogs = useMemo<string[][]>(() => {
        const game = gameLogs.data.map((e) => [e[0], `[GAME] ${e[1]}`, ...e.slice(2)]);
        const ctrl = controllerLogs.data.map((e) => [e[0], `[CTRL] ${e[1]}`, ...e.slice(2)]);
        const result: string[][] = [];
        let gi = 0;
        let ci = 0;
        while (gi < game.length && ci < ctrl.length) {
            if (game[gi][0] <= ctrl[ci][0]) result.push(game[gi++]);
            else result.push(ctrl[ci++]);
        }
        while (gi < game.length) result.push(game[gi++]);
        while (ci < ctrl.length) result.push(ctrl[ci++]);
        return result;
    }, [gameLogs.data, controllerLogs.data]);

    const isLogTypeFiltered = logTypeFilter.size < ALL_LOG_TYPES.size;

    const filterByLogType = useCallback(
        (logs: string[][]): string[][] => {
            if (!isLogTypeFiltered) return logs;
            return logs.filter((log) => logTypeFilter.has(classifyLog(log)));
        },
        [logTypeFilter, isLogTypeFiltered],
    );

    const toggleLogType = useCallback((key: LogTypeKey) => {
        setLogTypeFilter((prev) => {
            const next = new Set(prev);
            if (next.has(key)) {
                next.delete(key);
            } else {
                next.add(key);
            }
            return next;
        });
    }, []);

    // Log-type-filtered versions — used for both rendering and match index computation
    const filteredGameLogs = useMemo(() => filterByLogType(gameLogs.data), [filterByLogType, gameLogs.data]);
    const filteredControllerLogs = useMemo(
        () => filterByLogType(controllerLogs.data),
        [filterByLogType, controllerLogs.data],
    );
    const filteredMergedLogs = useMemo(() => filterByLogType(mergedLogs), [filterByLogType, mergedLogs]);

    // Match indices for navigation — mirroring what LogViewer computes internally
    const gameMatchIndices = useMemo(
        () => computeMatchIndices(filteredGameLogs, searchQuery, filterMatchesOnly),
        [filteredGameLogs, searchQuery, filterMatchesOnly],
    );
    const controllerMatchIndices = useMemo(
        () => computeMatchIndices(filteredControllerLogs, searchQuery, filterMatchesOnly),
        [filteredControllerLogs, searchQuery, filterMatchesOnly],
    );

    // Match indices for the merged single-pane view
    const mergedMatchIndices = useMemo(
        () => computeMatchIndices(filteredMergedLogs, searchQuery, filterMatchesOnly),
        [filteredMergedLogs, searchQuery, filterMatchesOnly],
    );

    // Combined navigation list for prev/next search
    const navList = useMemo(() => {
        if (logView === 'game') {
            return gameMatchIndices.map((idx) => ({ pane: 'game' as const, localIndex: idx }));
        }
        if (logView === 'controller') {
            return controllerMatchIndices.map((idx) => ({ pane: 'controller' as const, localIndex: idx }));
        }
        // 'all' with single combined pane — navigate within merged array via gameViewerRef
        if (layoutMode === 'single') {
            return mergedMatchIndices.map((idx) => ({ pane: 'game' as const, localIndex: idx }));
        }
        // 'all' split/stacked — game pane first, then controller
        return [
            ...gameMatchIndices.map((idx) => ({ pane: 'game' as const, localIndex: idx })),
            ...controllerMatchIndices.map((idx) => ({ pane: 'controller' as const, localIndex: idx })),
        ];
    }, [logView, layoutMode, mergedMatchIndices, gameMatchIndices, controllerMatchIndices]);

    const totalMatches = navList.length;

    // Reset navigation when query or view changes
    // biome-ignore lint/correctness/useExhaustiveDependencies: intentionally reset index when these values change
    useEffect(() => {
        setGlobalSearchIndex(-1);
    }, [searchQuery, logView, filterMatchesOnly]);

    const scrollToMatch = useCallback(
        (index: number) => {
            const entry = navList[index];
            if (!entry) return;
            if (entry.pane === 'game') {
                gameViewerRef.current?.scrollToLog(entry.localIndex);
            } else {
                controllerViewerRef.current?.scrollToLog(entry.localIndex);
            }
        },
        [navList],
    );

    const onSearchNext = useCallback(() => {
        if (totalMatches === 0) return;
        const next = globalSearchIndex === -1 || globalSearchIndex === totalMatches - 1 ? 0 : globalSearchIndex + 1;
        setGlobalSearchIndex(next);
        scrollToMatch(next);
    }, [globalSearchIndex, totalMatches, scrollToMatch]);

    const onSearchPrevious = useCallback(() => {
        if (totalMatches === 0) return;
        const prev = globalSearchIndex <= 0 ? totalMatches - 1 : globalSearchIndex - 1;
        setGlobalSearchIndex(prev);
        scrollToMatch(prev);
    }, [globalSearchIndex, totalMatches, scrollToMatch]);

    const handleClearAll = useCallback(() => {
        gameLogs.clearLogs();
        controllerLogs.clearLogs();
    }, [gameLogs, controllerLogs]);

    const getActiveLogs = useCallback((): [string[][], string] => {
        if (logView === 'game') return [filteredGameLogs, `${namePrefix}_game_logs`];
        if (logView === 'controller') return [filteredControllerLogs, `${namePrefix}_controller_logs`];
        return [filteredMergedLogs, `${namePrefix}_combined_logs`];
    }, [logView, filteredGameLogs, filteredControllerLogs, filteredMergedLogs, namePrefix]);

    const handleDownloadLog = useCallback(() => {
        const [logs, name] = getActiveLogs();
        download(name, toLog(logs), 'log');
    }, [getActiveLogs]);

    const handleDownloadCSV = useCallback(() => {
        const [logs, name] = getActiveLogs();
        download(name, toCSV(logs));
    }, [getActiveLogs]);

    const showSearch = searchQuery.trim().length > 0;

    const renderLogContent = () => {
        const sharedViewerProps = {
            hideToolbar: true,
            externalFilter: searchQuery,
            externalFilterMatchesOnly: filterMatchesOnly,
            height: logHeight,
            logSettings: { autoscroll, relativeTimestamps, firstOnly, showCollapsedCount },
            idleMessage,
            streamingComplete,
            currentTime,
            sessionStartMs,
            playheadSource,
            onSelectLog,
        };

        switch (logView) {
            case 'all':
                if (layoutMode === 'single') {
                    return (
                        <div className={styles.singlePane}>
                            <LogViewer
                                ref={gameViewerRef}
                                name={`${namePrefix}_combined_logs_${sessionId}`}
                                logs={filteredMergedLogs}
                                loading={gameLoading && controllerLoading}
                                onClearLogs={handleClearAll}
                                {...sharedViewerProps}
                            />
                        </div>
                    );
                }
                if (layoutMode === 'stacked') {
                    const gameLogHeight = Math.floor((logHeight * stackedGamePercent) / 100);
                    const controllerLogHeight = logHeight - gameLogHeight;
                    return (
                        <div className={styles.stackedPane}>
                            <PanelGroup direction='vertical' style={{ height: '100%' }} key='stacked'>
                                <Panel defaultSize={50} minSize={15} onResize={setStackedGamePercent}>
                                    <LogViewer
                                        ref={gameViewerRef}
                                        name={`${namePrefix}_game_logs_${sessionId}`}
                                        logs={filteredGameLogs}
                                        loading={gameLoading}
                                        onClearLogs={gameLogs.clearLogs}
                                        error={gameLogsError}
                                        {...sharedViewerProps}
                                        height={gameLogHeight}
                                    />
                                </Panel>
                                <PanelResizeHandle className={styles.resizeHandleHorizontal} />
                                <Panel defaultSize={50} minSize={15}>
                                    <LogViewer
                                        ref={controllerViewerRef}
                                        name={`${namePrefix}_controller_logs_${sessionId}`}
                                        logs={filteredControllerLogs}
                                        loading={controllerLoading}
                                        onClearLogs={controllerLogs.clearLogs}
                                        error={controllerLogsError}
                                        {...sharedViewerProps}
                                        height={controllerLogHeight}
                                    />
                                </Panel>
                            </PanelGroup>
                        </div>
                    );
                }
                return (
                    <div className={styles.splitPane}>
                        <PanelGroup direction='horizontal' style={{ height: '100%' }} key='split'>
                            <Panel defaultSize={50} minSize={20}>
                                <LogViewer
                                    ref={gameViewerRef}
                                    name={`${namePrefix}_game_logs_${sessionId}`}
                                    logs={filteredGameLogs}
                                    loading={gameLoading}
                                    onClearLogs={gameLogs.clearLogs}
                                    error={gameLogsError}
                                    {...sharedViewerProps}
                                />
                            </Panel>
                            <PanelResizeHandle className={styles.resizeHandleVertical} />
                            <Panel defaultSize={50} minSize={20}>
                                <LogViewer
                                    ref={controllerViewerRef}
                                    name={`${namePrefix}_controller_logs_${sessionId}`}
                                    logs={filteredControllerLogs}
                                    loading={controllerLoading}
                                    onClearLogs={controllerLogs.clearLogs}
                                    error={controllerLogsError}
                                    {...sharedViewerProps}
                                />
                            </Panel>
                        </PanelGroup>
                    </div>
                );
            case 'game':
                return (
                    <div className={styles.singlePane}>
                        <LogViewer
                            ref={gameViewerRef}
                            name={`${namePrefix}_game_logs_${sessionId}`}
                            logs={filteredGameLogs}
                            loading={gameLoading}
                            onClearLogs={gameLogs.clearLogs}
                            error={gameLogsError}
                            {...sharedViewerProps}
                        />
                    </div>
                );
            case 'controller':
                return (
                    <div className={styles.singlePane}>
                        <LogViewer
                            ref={controllerViewerRef}
                            name={`${namePrefix}_controller_logs_${sessionId}`}
                            logs={filteredControllerLogs}
                            loading={controllerLoading}
                            onClearLogs={controllerLogs.clearLogs}
                            error={controllerLogsError}
                            {...sharedViewerProps}
                        />
                    </div>
                );
            default:
                return null;
        }
    };

    return (
        <div className={styles.logsPanel}>
            {/* ── Toolbar ── */}
            <div className={styles.toolbar}>
                {/* Log source toggles — flat variant */}
                <div className={styles.toggleFlat}>
                    <ToggleButtonGroup
                        compact
                        exclusive
                        value={logView}
                        onChange={(_ev, value) => {
                            if (value) setLogView(value as LogView);
                        }}
                    >
                        <ToggleButton value='all'>All</ToggleButton>
                        <ToggleButton value='game'>Game Log</ToggleButton>
                        <ToggleButton value='controller'>Controller Log</ToggleButton>
                    </ToggleButtonGroup>
                </div>

                {/* Log Type filter dropdown */}
                <Menu
                    disableAutoFocusOnOpen={true}
                    disableAutoFocusOnClose={true}
                    trigger={
                        <button type='button' className={styles.logTypeButton}>
                            Log Type
                            <IconCaretDown size='small' />
                            {isLogTypeFiltered && <span className={styles.filterActiveDot} />}
                        </button>
                    }
                >
                    <MenuGroup>
                        {(Object.keys(LOG_TYPE_LABELS) as LogTypeKey[]).map((key) => (
                            <MenuItem key={key} onChange={() => toggleLogType(key)}>
                                <Checkbox
                                    checked={logTypeFilter.has(key)}
                                    label={
                                        <span className={styles.logTypeMenuLabel}>
                                            {key === 'error' && (
                                                <IconCircleExclamationPointFill
                                                    size='small'
                                                    color={LOG_TYPE_ICON_COLOR.error}
                                                />
                                            )}
                                            {key === 'warn' && (
                                                <IconWarningFill size='small' color={LOG_TYPE_ICON_COLOR.warn} />
                                            )}
                                            {key === 'info' && (
                                                <IconCircleI size='small' color={LOG_TYPE_ICON_COLOR.info} />
                                            )}
                                            {key === 'network' && (
                                                <IconSignalWifi size='small' color={LOG_TYPE_ICON_COLOR.network} />
                                            )}
                                            {LOG_TYPE_LABELS[key]}
                                        </span>
                                    }
                                />
                            </MenuItem>
                        ))}
                    </MenuGroup>
                </Menu>

                <div className={styles.toolbarSpacer} />

                {/* Filter matches-only toggle */}
                <Button
                    compact
                    icon={IconFilter}
                    variant={filterMatchesOnly ? 'secondary' : 'icon'}
                    aria-label='Show matches only'
                    tooltipLabel='Toggle to search within the logs or to filter the string from the logs'
                    disabled={!showSearch || totalMatches === 0}
                    onClick={() => setFilterMatchesOnly((v) => !v)}
                />

                {/* Search input */}
                <Input
                    compact
                    placeholder='Search both logs'
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    startAdornment={<IconMagnifyingGlass size='small' />}
                    style={{ width: 180 }}
                />

                {/* Prev / Next navigation — only when there are matches */}
                {showSearch && totalMatches > 0 && (
                    <div className={styles.navGroup}>
                        <Text variant='label' colorVariant='faded' className={styles.matchCounter}>
                            {globalSearchIndex === -1
                                ? `${totalMatches}`
                                : `${globalSearchIndex + 1} / ${totalMatches}`}
                        </Text>
                        <ButtonGroup gap={Dimensions.Space4}>
                            <Button
                                compact
                                icon={IconArrowLeft}
                                variant='icon'
                                aria-label='Previous match'
                                onClick={onSearchPrevious}
                            />
                            <Button
                                compact
                                icon={IconArrowRight}
                                variant='icon'
                                aria-label='Next match'
                                onClick={onSearchNext}
                            />
                        </ButtonGroup>
                    </div>
                )}

                <Button compact icon={IconBroom} variant='icon' aria-label='Clear logs' onClick={handleClearAll} />

                <Menu
                    disableAutoFocusOnOpen={true}
                    disableAutoFocusOnClose={true}
                    trigger={
                        <Button
                            compact
                            icon={IconDownload}
                            variant='icon'
                            aria-label='Download logs'
                            tooltipLabel='Download'
                        />
                    }
                >
                    <MenuGroup label='FORMATS'>
                        <MenuItem onClick={handleDownloadLog}>LOG</MenuItem>
                        <MenuItem onClick={handleDownloadCSV}>CSV</MenuItem>
                    </MenuGroup>
                </Menu>

                <Menu
                    showCaret
                    trigger={
                        <Button
                            compact
                            icon={IconSettings}
                            variant='icon'
                            aria-label='Log settings'
                            style={{ marginRight: Dimensions.Space4 }}
                        />
                    }
                >
                    <MenuItem onChange={() => setAutoscroll((v) => !v)}>
                        <Checkbox label='Autoscroll to the bottom' checked={autoscroll} />
                    </MenuItem>
                    <MenuItem onChange={() => setRelativeTimestamps((v) => !v)}>
                        <Checkbox label='Relative time' checked={relativeTimestamps} />
                    </MenuItem>
                    <MenuItem onChange={() => setFirstOnly((v) => !v)}>
                        <Checkbox label='First line only' checked={firstOnly} />
                    </MenuItem>
                    <MenuItem onChange={() => setShowCollapsedCount((v) => !v)}>
                        <Checkbox label='Show collapsed count' checked={showCollapsedCount} />
                    </MenuItem>
                </Menu>
            </div>

            {/* ── Status bar ── */}
            <div className={styles.logStatusBar}>
                {showControllerStatusBar ? (
                    <Text variant='label' colorVariant='faded' className={styles.logStatusText}>
                        x controllers connected
                    </Text>
                ) : (
                    <div />
                )}
                <div className={styles.toggleFlat}>
                    <ToggleButtonGroup
                        compact
                        exclusive
                        value={logView === 'all' ? layoutMode : undefined}
                        onChange={(_ev, value) => {
                            if (!value) return;
                            setLogView('all');
                            setLayoutMode(value as LogLayoutMode);
                        }}
                    >
                        <Tooltip label='Merge game log and controller logs'>
                            <ToggleButton value='single' icon={IconSquare} aria-label='Combined pane' />
                        </Tooltip>
                        <Tooltip label='Horizontally align game logs and controller logs panel'>
                            <ToggleButton value='split' icon={IconPanelCardsHorizontal} aria-label='Split pane' />
                        </Tooltip>
                        <Tooltip label='Vertically align game logs and controller logs panel'>
                            <ToggleButton value='stacked' icon={IconPanelCardsVertical} aria-label='Stacked pane' />
                        </Tooltip>
                    </ToggleButtonGroup>
                </div>
            </div>

            {/* Log content */}
            <div className={styles.logArea} ref={logAreaRef as React.RefCallback<HTMLElement>}>
                {renderLogContent()}
            </div>
        </div>
    );
};
