type LogOptions = { removeEmptyRows?: boolean };

export const toLog = <T>(data: T[][], options: LogOptions = { removeEmptyRows: true }): string => {
    const log: string[] = [];
    data.forEach((row) => {
        if (row) {
            let values = row.map((col) => `${col}`);
            if (options.removeEmptyRows) {
                values = values.filter((v) => v !== '' && v != '""');
            }
            log.push(...values);
        }
    });
    return log.join('\n');
};
