import { type ReactNode, createElement } from 'react';

/**
 * Derives 4 evenly-spaced y-axis labels (top → bottom) from a set of data
 * values, rounded to the nearest multiple of `snap` (default 5).
 */
export const computeYAxisLabels = (values: number[], count = 4, snap = 5): string[] => {
    if (!values.length) return [];
    const max = Math.ceil(Math.max(...values) / snap) * snap;
    const min = Math.floor(Math.min(...values) / snap) * snap;
    const range = max - min;
    if (range === 0) return Array.from({ length: count }, () => String(max));
    const step = range / (count - 1);
    return Array.from({ length: count }, (_, i) => String(Math.round(max - i * step)));
};

export const format = (ms: number) => {
    if (ms < 0) {
        return '';
    }
    const minutes = Math.floor(ms / 60_000);
    const seconds = Math.floor((ms % 60_000) / 1_000);
    const formattedMins = `${minutes}`.padStart(2, '0');
    const formattedSecs = `${seconds}`.padStart(2, '0');

    return `${formattedMins}:${formattedSecs}`;
};

export const formatWithMs = (ms: number) => {
    if (ms < 0) {
        return '';
    }
    const millis = Math.floor(ms % 1_000);
    return `${format(ms)}.${`${millis}`.padStart(3, '0')}`;
};

/**
 * Wraps a hover tooltip's contents (`DataTooltipContentsProps` from `@netflix-internal/react-vizkit`)
 * with a small "elapsed time" badge pinned to the top-right corner, so the exact hovered timestamp
 * is always visible while scrubbing across a chart. `classNames` should come from the caller's own
 * CSS module (expects `.hoverTooltipWrap` and `.hoverTimeCorner`, see SessionTimelineChart.module.css).
 */
export const withHoverTimeCorner = <T extends { wrap?: (props: { contents: ReactNode }) => JSX.Element }>(
    current: T,
    hoveredDate: Date | undefined,
    sessionStartTimestamp: number,
    classNames: { hoverTooltipWrap: string; hoverTimeCorner: string },
): T => {
    const hoveredMs = hoveredDate?.getTime();
    if (hoveredMs == null) return current;
    const timeLabel = format(hoveredMs - sessionStartTimestamp);
    return {
        ...current,
        wrap: ({ contents }: { contents: ReactNode }) =>
            createElement(
                'div',
                { className: classNames.hoverTooltipWrap },
                contents,
                createElement('span', { className: classNames.hoverTimeCorner }, timeLabel),
            ),
    };
};
