const escapeRegExp = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const toRegex = (term: string): RegExp => {
    try {
        return new RegExp(term, 'i');
    } catch {
        return new RegExp(escapeRegExp(term), 'i');
    }
};

export type ParsedFilter = {
    positive: string[];
    negative: string[];
};

export const parseFilterTerms = (filter: string): ParsedFilter => {
    const parts = filter
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean);
    const positive = parts.filter((t) => !t.startsWith('-'));
    const negative = parts
        .filter((t) => t.startsWith('-'))
        .map((t) => t.slice(1).trim())
        .filter(Boolean);
    return { positive, negative };
};

export const matchesPositive = (text: string, { positive }: ParsedFilter): boolean =>
    positive.length === 0 || positive.every((t) => toRegex(t).test(text));

export const passesNegative = (text: string, { negative }: ParsedFilter): boolean =>
    negative.every((t) => !toRegex(t).test(text));

export const matchesFilter = (text: string, parsed: ParsedFilter): boolean =>
    matchesPositive(text, parsed) && passesNegative(text, parsed);
