import styles from './SessionAvgTile.module.css';

export type SessionAvgTileProps = {
    label: string;
    value: number | null;
    unit?: string;
    /** When true, renders the value in red (e.g. dimension exceeded 100%). */
    isAlert?: boolean;
};

export const SessionAvgTile = ({ label, value, unit, isAlert }: SessionAvgTileProps) => (
    <div className={styles.container}>
        <div className={`${styles.dataContainer}${isAlert ? ` ${styles.dataContainerAlert}` : ''}`}>
            <div className={styles.dataBlock}>
                <div className={styles.labelRow}>
                    <span className={styles.label}>{label}</span>
                </div>
                <div className={styles.valueRow}>
                    <span className={styles.valueNumber}>
                        {value != null ? value.toFixed(1) : '—'}
                    </span>
                    {unit && <span className={styles.valueUnit}>{unit}</span>}
                </div>
            </div>
        </div>
    </div>
);
