import { IconCircleExclamationPointFill } from '@hawkins/assets/lib/icons/iconCircleExclamationPointFill';
import { IconWarningFill } from '@hawkins/assets/lib/icons/iconWarningFill';
import { ErrorState, Loader, Tag, Text } from '@hawkins/components';
import { useVirtualizer } from '@tanstack/react-virtual';
import clsx from 'clsx';
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef } from 'react';
import { TextHighlight } from '../../components/TextHighlight';
import { parseFilterTerms } from '../../filterUtils';
import styles from './../../LogViewer.module.css';

const WARN_REGEX = /\bwarn(ing)?\b/i;
const ERROR_REGEX = /\b(error|exception)\b/i;

type LogLevel = 'ERROR' | 'WARN' | 'INFO';

const detectLogLevel = (msg: string): LogLevel => {
    if (ERROR_REGEX.test(msg)) return 'ERROR';
    if (WARN_REGEX.test(msg)) return 'WARN';
    return 'INFO';
};

const LOG_LEVEL_COLOR: Record<LogLevel, string | undefined> = {
    ERROR: 'var(--hawkins-theme-foreground-system-error)',
    WARN: 'var(--hawkins-theme-foreground-system-warning)',
    INFO: undefined,
};

const formatRelativeDuration = (currentTs: string, firstTs: number): string => {
    const diffMs = Math.max(0, new Date(currentTs).getTime() - firstTs);
    const totalSecs = Math.floor(diffMs / 1000);
    const secs = totalSecs % 60;
    const mins = Math.floor(totalSecs / 60) % 60;
    const hours = Math.floor(totalSecs / 3600);
    const pad = (n: number) => String(n).padStart(2, '0');
    if (hours > 0) {
        return `+${hours}:${pad(mins)}:${pad(secs)}`;
    }
    return `+${mins}:${pad(secs)}`;
};

const SOURCE_LABEL: Record<string, string> = {
    game: 'GAME',
    controller: 'CTRL',
};

// Logs are sorted ascending by timestamp — binary search for the last entry at-or-before targetMs.
const findNearestLogIndex = (logs: any[], targetMs: number): number => {
    let lo = 0;
    let hi = logs.length - 1;
    let result = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        const t = new Date(logs[mid][0]).getTime();
        if (t <= targetMs) {
            result = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return result === -1 ? 0 : result;
};

type CollapsedLog = { log: string[]; count: number; firstIndex: number };

interface GameLogsListProps {
    autoscroll?: boolean;
    relativeTimestamps?: boolean;
    logs: any[];
    error?: any;
    loading?: boolean;
    searchIndex?: number;
    height?: number;
    filter: string;
    format: any;
    firstOnly?: boolean;
    showCollapsedCount?: boolean;
    /** Height in px consumed by the toolbar above this list (default 40) */
    toolbarOffset?: number;
    /** Text shown when logs are empty and not loading (e.g. before a session starts) */
    idleMessage?: string;
    /** Shared playhead position, in seconds from session start. Null when nothing is selected. */
    currentTime?: number | null;
    /** Epoch ms for t=0 (session start), shared with the graph for consistent time matching. */
    sessionStartMs?: number;
    /** Which side last set currentTime — used to only auto-scroll for graph-originated jumps. */
    playheadSource?: 'graph' | 'log' | null;
    /** Called when the user selects a log row (click or Enter), with its time in seconds from session start. */
    onSelectLog?: (seconds: number) => void;
}

export const GameLogsList = forwardRef((props: GameLogsListProps, ref: any) => {
    const {
        logs,
        loading,
        error,
        searchIndex,
        autoscroll,
        relativeTimestamps,
        filter,
        height,
        format,
        firstOnly,
        showCollapsedCount = true,
        toolbarOffset = 40,
        idleMessage,
        currentTime = null,
        sessionStartMs = 0,
        playheadSource = null,
        onSelectLog,
    } = props;
    const parentRef = useRef<HTMLDivElement>(null);

    const collapsedLogs = useMemo<CollapsedLog[]>(() => {
        const result: CollapsedLog[] = [];
        for (let i = 0; i < logs.length; i++) {
            const log = logs[i];
            const last = result[result.length - 1];
            if (last && last.log[1] === log[1]) {
                last.count++;
            } else {
                result.push({ log, count: 1, firstIndex: i });
            }
        }
        return result;
    }, [logs]);

    const originalToCollapsed = useMemo(() => {
        const map = new Map<number, number>();
        collapsedLogs.forEach((group, collapsedIdx) => {
            for (let i = group.firstIndex; i < group.firstIndex + group.count; i++) {
                map.set(i, collapsedIdx);
            }
        });
        return map;
    }, [collapsedLogs]);

    const count = collapsedLogs.length;

    const virtualizer = useVirtualizer({
        count,
        getScrollElement: () => parentRef.current,
        overscan: 5,
        estimateSize: () => 45,
    });
    const items = virtualizer.getVirtualItems();

    useImperativeHandle(
        ref,
        () => {
            return {
                scrollToLog: (index: number) => {
                    const collapsedIndex = originalToCollapsed.get(index) ?? index;
                    virtualizer.scrollToIndex(collapsedIndex, {
                        align: 'start',
                    });
                },
            };
        },
        [originalToCollapsed, virtualizer.scrollToIndex],
    );

    const scrollToBottom = useCallback(() => {
        if (count > 0) {
            virtualizer.scrollToIndex(count - 1);
        }
    }, [virtualizer, count]);

    useEffect(() => {
        if (autoscroll) {
            requestAnimationFrame(() => {
                scrollToBottom();
            });
        }
    }, [autoscroll, logs, scrollToBottom]);

    const firstTimestamp = useMemo(() => {
        const first = logs?.[0]?.[0];
        return first ? new Date(first).getTime() : null;
    }, [logs]);

    const collapsedSearchIndex = searchIndex !== undefined ? originalToCollapsed.get(searchIndex) : undefined;

    // Nearest-match: the log at-or-before the playhead time, else the first log.
    const activeOriginalIndex = useMemo(() => {
        if (currentTime === null || logs.length === 0) return null;
        return findNearestLogIndex(logs, sessionStartMs + currentTime * 1000);
    }, [currentTime, sessionStartMs, logs]);

    const collapsedActiveIndex =
        activeOriginalIndex !== null ? (originalToCollapsed.get(activeOriginalIndex) ?? activeOriginalIndex) : null;

    // Graph -> logs: scroll the matching row into view. Skip when the selection came from a log
    // click itself (the row is already visible) to avoid fighting the user's own scroll position.
    useEffect(() => {
        if (playheadSource !== 'graph' || collapsedActiveIndex === null) return;
        virtualizer.scrollToIndex(collapsedActiveIndex, { align: 'center' });
    }, [playheadSource, collapsedActiveIndex, virtualizer.scrollToIndex]);

    const handleSelectLog = useCallback(
        (logMsg: string[]) => {
            if (!onSelectLog || !logMsg[0]) return;
            onSelectLog((new Date(logMsg[0]).getTime() - sessionStartMs) / 1000);
        },
        [onSelectLog, sessionStartMs],
    );

    const positiveTerms = useMemo(() => parseFilterTerms(filter).positive, [filter]);

    const isError = useMemo(() => {
        return error && items.length === 0 && !loading;
    }, [error, items, loading]);

    if (!loading && !isError && count === 0 && idleMessage) {
        return (
            <div
                className={clsx(styles.scrollLog, { [styles.relativeTimestamps]: relativeTimestamps })}
                style={{ height: height ? height - toolbarOffset : 0 }}
            >
                <Text
                    variant='monospaced'
                    level={0}
                    component='span'
                    colorVariant='faded'
                    className={styles.idleMessage}
                >
                    {idleMessage}
                </Text>
            </div>
        );
    }

    return (
        <div
            ref={parentRef}
            className={clsx(styles.scrollLog, {
                [styles.loading]: loading,
                [styles.relativeTimestamps]: relativeTimestamps,
            })}
            style={{ height: height ? height - toolbarOffset : 0 }}
        >
            {loading && <Loader />}
            {isError && (
                <ErrorState
                    size='small'
                    className={styles.errorWrapper}
                    subtitle={typeof error === 'string' ? error : error?.message}
                    title='Logs Error'
                    variant='something-wrong'
                />
            )}
            {!loading && (
                <div
                    className={styles.scrollLogInner}
                    style={{
                        height: virtualizer.getTotalSize(),
                    }}
                >
                    <ol
                        className={styles.log}
                        style={{
                            transform: `translateY(${items[0]?.start ?? 0}px)`,
                        }}
                    >
                        {items.map((item) => {
                            const { log: logMsg, count: groupCount } = collapsedLogs[item.index];
                            const date =
                                relativeTimestamps && firstTimestamp !== null && logMsg[0]
                                    ? formatRelativeDuration(logMsg[0], firstTimestamp)
                                    : logMsg[0];
                            const msg = logMsg[1];
                            const type = logMsg[2];
                            const source = logMsg[3];

                            const logText = format(msg, firstOnly);
                            let content = <span>{logText}</span>;

                            if (typeof logText === 'string' && positiveTerms.length > 0) {
                                content = <TextHighlight terms={positiveTerms} text={logText} />;
                            }

                            const isNetwork = !!type;
                            const logLevel = isNetwork ? 'INFO' : detectLogLevel(msg);
                            const textColor = isNetwork
                                ? 'var(--hawkins-theme-foreground-system-link)'
                                : LOG_LEVEL_COLOR[logLevel];

                            const isActive = currentTime !== null && item.index === collapsedActiveIndex;

                            return (
                                <li
                                    key={item.key as any}
                                    className={clsx(styles.logMessage, {
                                        [styles.searchHighlightBackground]: item.index === collapsedSearchIndex,
                                        [styles.odd]: item.index % 2 === 1,
                                        [styles.activeLog]: isActive,
                                        [styles.selectable]: Boolean(onSelectLog),
                                    })}
                                    data-before={date}
                                    data-index={item.index}
                                    ref={virtualizer.measureElement}
                                    tabIndex={onSelectLog ? 0 : undefined}
                                    aria-current={isActive ? 'true' : undefined}
                                    onClick={onSelectLog ? () => handleSelectLog(logMsg) : undefined}
                                    onKeyDown={
                                        onSelectLog
                                            ? (e) => {
                                                  if (e.key === 'Enter') {
                                                      e.preventDefault();
                                                      handleSelectLog(logMsg);
                                                  }
                                              }
                                            : undefined
                                    }
                                >
                                    <span className={styles.alertingSpace}>
                                        {logLevel === 'ERROR' && (
                                            <IconCircleExclamationPointFill
                                                size='small'
                                                style={{
                                                    color: 'var(--hawkins-theme-foreground-system-error)',
                                                    flexShrink: 0,
                                                }}
                                            />
                                        )}
                                        {logLevel === 'WARN' && (
                                            <IconWarningFill
                                                size='small'
                                                style={{
                                                    color: 'var(--hawkins-theme-foreground-system-warning)',
                                                    flexShrink: 0,
                                                }}
                                            />
                                        )}
                                    </span>
                                    {source && (
                                        <span className={styles.sourceTag}>
                                            <Tag
                                                variant='compact-outlined'
                                                style={{ alignSelf: 'flex-start', flexShrink: 0 }}
                                            >
                                                {SOURCE_LABEL[source] ?? source}
                                            </Tag>
                                        </span>
                                    )}
                                    <span className={styles.counter}>
                                        {showCollapsedCount && groupCount > 1 && (
                                            <Tag
                                                variant='compact-outlined'
                                                style={{ alignSelf: 'flex-start', flexShrink: 0 }}
                                            >
                                                {groupCount}
                                            </Tag>
                                        )}
                                    </span>
                                    <Text
                                        variant='monospaced'
                                        level={0}
                                        component='span'
                                        color={textColor}
                                        bold={isNetwork || logLevel === 'ERROR'}
                                    >
                                        {content}
                                    </Text>
                                </li>
                            );
                        })}
                    </ol>
                </div>
            )}
        </div>
    );
});
