import styles from './GraphSideCard.module.css';

export type GraphSideCardMetric = {
    /** Dataset key used for toggling visibility — matches the vizkit dataset key */
    lineKey?: string;
    color: string;
    label: string;
    value: number | null;
    unit?: string;
    /** If true, the value renders on a new line below the label instead of right-aligned. */
    stackValue?: boolean;
    /** When set, values above this number render in red. */
    threshold?: number;
};

export type GraphSideCardStatRow = {
    label: string;
    value: number | null;
    decimals?: number;
};

export type GraphSideCardProps = {
    title: string;
    /** Shown in the header row (right-aligned) when using metrics layout. */
    scoreValue?: number | null;
    /** Colored dot rows — uses the metrics layout (stats chart). */
    metrics?: GraphSideCardMetric[];
    /** Plain label+value rows — uses the stat layout (FPS / instance count charts). */
    statRows?: GraphSideCardStatRow[];
    yAxisLabels?: string[];
    emptyMessage?: string;
    /** Called with the metric's lineKey when a row is clicked */
    onToggleKey?: (key: string) => void;
    /** Set of lineKeys currently hidden — hides rows */
    hiddenKeys?: Set<string>;
    /** When set, the prominent score number turns red if scoreValue drops below this threshold. */
    scoreAlertBelow?: number;
    /** Reduces padding to 4px top/bottom and fixes height to 40px — used for the screenshots row. */
    compact?: boolean;
};

export const GraphSideCard = ({
    title,
    scoreValue,
    metrics,
    statRows,
    yAxisLabels,
    emptyMessage = 'No data',
    onToggleKey,
    hiddenKeys,
    scoreAlertBelow,
    compact = false,
}: GraphSideCardProps) => {
    const useStatLayout = statRows !== undefined;
    const hasMetrics = (metrics?.length ?? 0) > 0;

    return (
        <div className={styles.card}>
            <div className={compact ? `${styles.content} ${styles.contentCompact}` : styles.content}>
                <div className={styles.header}>
                    <span className={styles.title}>{title}</span>
                    {!useStatLayout && scoreValue != null && <span className={styles.scoreValue}>{scoreValue}</span>}
                </div>

                {useStatLayout ? (
                    <>
                        {scoreValue != null && (
                            <div className={styles.prominentScore}>
                                <span
                                    className={styles.prominentScoreNumber}
                                    style={
                                        scoreAlertBelow != null && scoreValue < scoreAlertBelow
                                            ? { color: '#f7636b' }
                                            : undefined
                                    }
                                >
                                    {Math.round(scoreValue)}
                                </span>
                            </div>
                        )}
                        {statRows.length > 0 && (
                            <div className={styles.statList}>
                                {statRows.map((row, i) => (
                                    <div key={i} className={styles.statBlock}>
                                        <span className={styles.statLabel}>{row.label}</span>
                                        <span className={styles.statValue}>
                                            {row.value != null ? row.value.toFixed(row.decimals ?? 0) : '—'}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </>
                ) : (
                    <div className={styles.metricList}>
                        {hasMetrics ? (
                            metrics!.map((metric, i) => {
                                const isHidden = metric.lineKey ? hiddenKeys?.has(metric.lineKey) : false;
                                const isClickable = metric.lineKey && onToggleKey;
                                return (
                                    <div
                                        key={metric.label ?? i}
                                        className={metric.stackValue ? styles.metricRowStacked : styles.metricRow}
                                        style={{
                                            opacity: isHidden ? 0.3 : 1,
                                            cursor: isClickable ? 'pointer' : undefined,
                                        }}
                                        onClick={isClickable ? () => onToggleKey(metric.lineKey!) : undefined}
                                    >
                                        <div className={styles.glyph}>
                                            <div className={styles.dot} style={{ backgroundColor: metric.color }} />
                                        </div>
                                        <span className={styles.label}>{metric.label}</span>
                                        <div className={styles.valueSection}>
                                            {metric.value != null ? (
                                                <>
                                                    <span
                                                        className={styles.valueNumber}
                                                        style={
                                                            metric.threshold != null && metric.value > metric.threshold
                                                                ? { color: '#f7636b' }
                                                                : undefined
                                                        }
                                                    >
                                                        {metric.value.toFixed(1)}
                                                    </span>
                                                    {metric.unit && (
                                                        <span className={styles.valueUnit}>{metric.unit}</span>
                                                    )}
                                                </>
                                            ) : (
                                                <span className={styles.noData}>—</span>
                                            )}
                                        </div>
                                    </div>
                                );
                            })
                        ) : (
                            <span className={styles.noData}>{emptyMessage}</span>
                        )}
                    </div>
                )}
            </div>

            {yAxisLabels && yAxisLabels.length > 0 && (
                <div className={styles.yAxisColumn}>
                    {yAxisLabels.map((label) => (
                        <div key={label} className={styles.yAxisRow}>
                            <span className={styles.yAxisLabel}>{label}</span>
                            <div className={styles.yAxisTick} />
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
};
