import { useRef, useState } from 'react';

export type PromiseStatus = 'loading' | 'success' | 'error';

export class PromiseTracker<T> {
    status: PromiseStatus = 'loading';
    onStatusChange: (status: PromiseStatus) => void;
    defaultValue: T | null;
    result: T | null = null;
    error: any = null;

    constructor(promise: Promise<T>, onStatusChange: (status: PromiseStatus) => void, defaultValue: T | null = null) {
        this.defaultValue = defaultValue;
        this.onStatusChange = onStatusChange;
        this.onStatusChange(this.status);
        this.track(promise);
    }

    private async track(promise: Promise<T>): Promise<void> {
        try {
            this.result = await promise;
            this.status = 'success';
            this.onStatusChange(this.status);
        } catch (error) {
            this.error = error;
            this.status = 'error';
            this.onStatusChange(this.status);
        }
    }
}

export const usePromiseTracker = <T>(promise: Promise<T>) => {
    const tracker = useRef(new PromiseTracker(promise, status => setStatus(status)));
    const [, setStatus] = useState<PromiseStatus>(tracker.current.status);
    return tracker.current;
};
